-- ============================================================================
-- 하루 에스티아 / 에프넬 스토리 14편 업로드 SQL
-- dev DB character_stories (id 4~17) 에서 추출 (2026-11-04).
--
-- 사용법:
--   1) 아래 캐릭터 id 두 개를 대상 DB 환경에 맞게 수정한다.
--   2) 대상 DB 에서 이 파일 전체를 실행한다.
--
-- 동작:
--   - id 는 지정하지 않는다 (대상 DB 의 AUTO_INCREMENT 사용 — 충돌 없음).
--   - 같은 캐릭터에 같은 제목의 스토리가 이미 있으면 그 편은 건너뛴다 (재실행 안전).
--   - status='published' 로 바로 공개 상태가 된다 (보드는 dev 에서 공개 검증을 통과한 것).
--   - draft_json 과 published_json 은 같은 보드로 넣는다.
-- ============================================================================

SET @haru_id = 7;    -- 하루 에스티아 characters.id (대상 DB 에 맞게 수정)
SET @efnel_id = 10;  -- 에프넬 characters.id (대상 DB 에 맞게 수정)

-- 01. [하루 에스티아] 잔불이 꺼지지 않는 협곡: 소울정크 토벌선
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '잔불이 꺼지지 않는 협곡: 소울정크 토벌선', 'published', 0, '{\"vars\":[{\"name\":\"지휘\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"아르카디아 렐름의 긴급 브리핑\",\"text\":\"비스타 토벌의 열기가 채 식지 않은 아르카디아 렐름의 작전실. 클라우드림 동쪽 협곡에서 소울정크 무리가 마을로 내려오고 있다는 보고가 들어왔다. 하루 에스티아는 지친 몸을 일으켜 지도를 펼치고, 리더로서 침착하게 상황을 정리하려 애쓴다. 속으로는 사람이 다칠까 두려운 마음이 크다. 당신은 별숲리그의 협력자로서 그녀 옆자리에 서 있고, 하루는 작전의 방향을 당신에게도 묻는다. 창밖에서는 아직 비스타 토벌의 잔향이 느껴지는 듯 렐름의 공기가 무겁다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"정면 돌파로 협곡 입구를 막자고 제안한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"우회로로 측면을 노리자고 제안한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_3\",\"text\":\"지원 부대를 기다리자고 제안한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"좁은 절벽길\",\"text\":\"협곡 옆 절벽을 따라 난 좁은 길. 바람이 거세고 발밑의 자갈이 자꾸 굴러 떨어진다. 하루는 높이 때문에 말을 더듬으면서도 당신보다 먼저 한 걸음을 내딛어 길을 확인한다. 아래로 소울정크의 울음소리가 울려 퍼지고, 그녀는 입술을 깨물며 \\\"괜찮아요, 갈 수 있어요\\\"라고 스스로를 다독인다. 당신은 뒤에서 그녀의 안전줄을 잡아 준다. 혹여 발을 헛디딜까 하루는 중간중간 뒤를 돌아보며 당신의 안부를 먼저 묻는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"협곡 입구, 첫 접촉\",\"text\":\"붉게 물든 노을 아래 협곡 입구에서 소울정크 선봉대가 모습을 드러낸다. 하루는 소울럼 소드를 뽑아 들며 순간 숨을 들이쉰다. 전투 직전의 서늘한 눈빛이 되어 평소의 부드러운 말투가 단호하게 변한다. 그러나 등 뒤 마을 사람들이 대피하는 소리가 들리자 그녀는 곧 책임감으로 마음을 다잡는다. 당신은 그녀의 왼편에서 시선을 끌 위치에 선다. 붉은 노을이 대검의 날 위로 길게 번지며 긴장을 더한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"출정 전, 작은 약속\",\"text\":\"출발 직전, 하루 에스티아는 소울워커 대원들을 모아 간단히 인사를 건넨다. 목소리는 차분하지만 손끝은 살짝 떨리고 있다. 그녀는 \\\"모두 꼭 살아서 돌아와요\\\"라고 덧붙이며 곁에 선 당신을 돌아본다. 토마스와 빅터가 빠진 빈자리가 마음 한구석을 아프게 하지만 하루는 애써 웃어 보인다. 렐름 문 밖으로 바람이 불어와 소울럼 소드의 칼집이 달그락 소리를 낸다. 당신은 그 말에 고개를 끄덕이며 함께 돌아오겠다고 조용히 약속한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"흩어지는 소울정크\",\"text\":\"소울정크들이 갑자기 세 갈래로 흩어지며 하루의 대형을 흔든다. 하루는 한 번의 호흡으로 상황을 파악하고 짧고 빠르게 지시를 내리려 한다. 하지만 자신의 판단 하나에 팀의 안위가 달렸다는 무게가 어깨를 짓누르고, 손끝이 살짝 떨린다. 당신은 하루의 시선이 닿는 방향을 읽으며 어떤 역할을 맡을지 정해야 한다. 협곡 벽에 울리는 울음소리가 겹쳐 방향 감각마저 흐려진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"하루와 함께 중앙을 돌파한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"마을 쪽으로 향하는 무리를 먼저 막는다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_3\",\"text\":\"일단 거리를 두고 상황을 관찰한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":250,\"type\":\"story\",\"title\":\"마을을 향한 질주\",\"text\":\"대피 중인 마을 입구 쪽으로 소울정크 한 무리가 돌진한다. 당신이 먼저 몸을 날려 길목을 막자, 하루가 놀란 눈으로 돌아보며 \\\"무리하지 마세요!\\\"라고 외친다. 그녀는 곧 검을 휘둘러 당신 곁의 적을 쓸어내고, 사람이 희생당하는 것만은 절대 안 된다는 단호한 기세를 보인다. 마을 아이의 울음소리가 멀리서 들린다. 흙먼지가 자욱하게 일어나 시야를 가리고 숨소리만 가까이에서 들려온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"부상당한 대원\",\"text\":\"전투 중 소울워커 한 명이 다리를 다쳐 쓰러진다. 하루는 의사를 꿈꾸던 소녀답게 본능적으로 상처 상태를 살피고 응급 처치를 시작한다. 그 사이에도 소울정크는 계속 다가오고 있다. 그녀는 치료와 전투 사이에서 갈등하며 잠시 말을 더듬는다. 당신에게 시선을 보내 도움을 청하는 모습에서 조심스러운 신뢰가 묻어난다. 하루의 손끝에서 번지는 연한 소울의 빛이 상처 부위를 감싸 안는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"내가 막을 테니 치료에 집중하라고 한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"함께 대원을 안전한 곳으로 옮긴다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"전투를 끝내는 게 먼저라고 말한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"서늘한 침묵\",\"text\":\"당신의 말에 하루가 잠시 입을 다문다. 부드럽던 표정이 굳고, 그녀는 조용히 대원의 손을 놓으며 일어선다. 화가 난 것은 아니지만 사람이 먼저라는 신념이 흔들린 듯한 눈빛이다. 곧 하루는 짧게 \\\"알겠어요\\\"라고 답한 뒤 검을 쥐고 적을 향해 나아간다. 어색한 공기 속에서 전투음만 협곡에 울린다. 그녀는 아무 말 없이 협곡 위쪽의 연기를 바라보며 한 호흡을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"우두머리의 포효\",\"text\":\"협곡 안쪽에서 거대한 변이 소울정크가 모습을 드러낸다. 땅이 울릴 만큼의 포효에 하루의 다리가 순간 굳는다. 그녀는 숨을 몰아쉬며 자신에게 \\\"나는 리더야\\\"라고 되뇌고, 검을 고쳐 잡는다. 몇 초의 망설임 뒤, 서늘한 눈빛으로 돌변한 하루가 당신에게 짧게 협공 타이밍을 알린다. 이 한 번의 합이 전투를 가른다. 협곡의 바위벽이 울려 파편이 우수수 떨어지고 공기가 팽팽하게 당겨진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"하루에게 마지막 일격을 맡긴다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"함께 합을 맞춰 마무리한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"혼자서 우두머리를 상대하겠다고 나선다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"두 개의 검광\",\"text\":\"당신과 하루의 움직임이 하나의 선처럼 겹친다. 하루는 당신의 호흡을 읽고 한 박자 먼저 검을 휘둘러 길을 열고, 이어 당신의 일격이 우두머리의 약점을 정확히 꿰뚫는다. 하루가 놀란 얼굴로 돌아보며 \\\"방금 합, 정말 좋았어요\\\"라고 숨을 몰아쉰다. 협곡의 소울정크들이 연이어 쓰러지며 잔불이 사그라든다. 협곡에 번지는 푸른 소울의 빛이 두 사람의 얼굴을 잠시 환하게 비춘다. 하루는 흐트러진 숨을 고르며 다시 자세를 잡는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"쓰러지는 우두머리\",\"text\":\"우두머리가 마지막 힘을 쥐어짜 내듯 포효하며 몸을 뒤틀다 마침내 무너져 내린다. 하루는 검을 거두기 전까지 방심하지 않고 한 번 더 상대를 살핀 뒤에야 숨을 돌린다. 땀에 젖은 머리칼을 쓸어 넘기는 그녀의 얼굴에 안도와 피로가 함께 번진다. 당신과 시선이 마주치자 하루는 작게 고개를 끄덕이며 가벼운 목례로 고마움을 전한다. 협곡을 울리던 포효가 멎고 바람 소리만이 남아 긴 긴장이 서서히 풀려 간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"잔불 위의 일몰\",\"text\":\"전투가 끝나고 협곡에는 소울정크가 남긴 잔불만 가물거린다. 하루는 검을 땅에 꽂고 길게 한숨을 내쉰다. 부상자 확인과 마을 상황 보고를 마친 뒤에야 그녀의 표정이 풀린다. 쑥스러운 듯 당신에게 감사 인사를 건네려다 말을 고르는 모습이 보인다. 노을이 지는 가운데, 둘은 돌아가는 길에 전투를 되짚으며 이야기를 나눈다. 멀리서 마을 사람들의 안도하는 목소리가 바람을 타고 희미하게 들려온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"지휘\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"지휘\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"협곡의 수호자들\",\"text\":\"완벽에 가까운 지휘로 단 한 명의 희생자도 없이 협곡을 지켜 냈다. 마을 사람들이 둘에게 감사 인사를 건네자 하루는 \\\"저 같은 게…\\\"라며 얼굴을 붉히지만, 마음 한켠에서는 리더로서의 자신감이 조금 자라난다. 하루는 당신에게 다음 작전도 곁에서 함께해 달라고 조심스럽게 청한다. 노을이 둘의 어깨 위로 길게 드리운다. 하루의 검 끝에서는 마지막 소울의 빛이 별처럼 흩어져 사라진다. 그 모습을 지켜보며 당신도 조용히 미소를 짓게 된다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"상처 입은 승리\",\"text\":\"토벌은 성공했지만 몇 명의 부상자가 남았다. 하루는 아쉬움을 숨기지 못하고 자책하지만, 당신이 곁에서 위로하자 이내 고개를 들어 다음에는 더 잘하겠다고 다짐한다. 의사를 꿈꾸던 손으로 마지막까지 부상자를 돌보며, 그녀는 지켜야 할 것들의 무게를 다시 새긴다. 돌아가는 길, 노을 아래로 길게 늘어진 두 사람의 그림자가 나란히 걸음을 맞춘다. 침묵 속에서도 서로를 향한 믿음이 조금씩 단단해진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"어긋난 호흡의 밤\",\"text\":\"소울정크는 물리쳤지만 호흡이 맞지 않아 마을 일부가 피해를 입었다. 하루는 말없이 폐허가 된 집터를 바라보다 당신에게 \\\"제 판단이 늦었어요\\\"라고 조용히 말한다. 그녀는 자책 속에서도 이를 악물고, 다음에는 반드시 모두를 지키겠다고 다짐한다. 당신은 그녀 곁에서 함께 잔해를 치운다. 별이 하나둘 떠오르는 밤하늘 아래, 하루는 오래도록 검 손잡이를 놓지 못한 채 서 있다. 당신은 그 곁을 지키며 말없이 시간을 보낸다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n9\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"지휘\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"아르카디아 렐름의 긴급 브리핑\",\"text\":\"비스타 토벌의 열기가 채 식지 않은 아르카디아 렐름의 작전실. 클라우드림 동쪽 협곡에서 소울정크 무리가 마을로 내려오고 있다는 보고가 들어왔다. 하루 에스티아는 지친 몸을 일으켜 지도를 펼치고, 리더로서 침착하게 상황을 정리하려 애쓴다. 속으로는 사람이 다칠까 두려운 마음이 크다. 당신은 별숲리그의 협력자로서 그녀 옆자리에 서 있고, 하루는 작전의 방향을 당신에게도 묻는다. 창밖에서는 아직 비스타 토벌의 잔향이 느껴지는 듯 렐름의 공기가 무겁다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"정면 돌파로 협곡 입구를 막자고 제안한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"우회로로 측면을 노리자고 제안한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_3\",\"text\":\"지원 부대를 기다리자고 제안한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"좁은 절벽길\",\"text\":\"협곡 옆 절벽을 따라 난 좁은 길. 바람이 거세고 발밑의 자갈이 자꾸 굴러 떨어진다. 하루는 높이 때문에 말을 더듬으면서도 당신보다 먼저 한 걸음을 내딛어 길을 확인한다. 아래로 소울정크의 울음소리가 울려 퍼지고, 그녀는 입술을 깨물며 \\\"괜찮아요, 갈 수 있어요\\\"라고 스스로를 다독인다. 당신은 뒤에서 그녀의 안전줄을 잡아 준다. 혹여 발을 헛디딜까 하루는 중간중간 뒤를 돌아보며 당신의 안부를 먼저 묻는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"협곡 입구, 첫 접촉\",\"text\":\"붉게 물든 노을 아래 협곡 입구에서 소울정크 선봉대가 모습을 드러낸다. 하루는 소울럼 소드를 뽑아 들며 순간 숨을 들이쉰다. 전투 직전의 서늘한 눈빛이 되어 평소의 부드러운 말투가 단호하게 변한다. 그러나 등 뒤 마을 사람들이 대피하는 소리가 들리자 그녀는 곧 책임감으로 마음을 다잡는다. 당신은 그녀의 왼편에서 시선을 끌 위치에 선다. 붉은 노을이 대검의 날 위로 길게 번지며 긴장을 더한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"출정 전, 작은 약속\",\"text\":\"출발 직전, 하루 에스티아는 소울워커 대원들을 모아 간단히 인사를 건넨다. 목소리는 차분하지만 손끝은 살짝 떨리고 있다. 그녀는 \\\"모두 꼭 살아서 돌아와요\\\"라고 덧붙이며 곁에 선 당신을 돌아본다. 토마스와 빅터가 빠진 빈자리가 마음 한구석을 아프게 하지만 하루는 애써 웃어 보인다. 렐름 문 밖으로 바람이 불어와 소울럼 소드의 칼집이 달그락 소리를 낸다. 당신은 그 말에 고개를 끄덕이며 함께 돌아오겠다고 조용히 약속한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"흩어지는 소울정크\",\"text\":\"소울정크들이 갑자기 세 갈래로 흩어지며 하루의 대형을 흔든다. 하루는 한 번의 호흡으로 상황을 파악하고 짧고 빠르게 지시를 내리려 한다. 하지만 자신의 판단 하나에 팀의 안위가 달렸다는 무게가 어깨를 짓누르고, 손끝이 살짝 떨린다. 당신은 하루의 시선이 닿는 방향을 읽으며 어떤 역할을 맡을지 정해야 한다. 협곡 벽에 울리는 울음소리가 겹쳐 방향 감각마저 흐려진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"하루와 함께 중앙을 돌파한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"마을 쪽으로 향하는 무리를 먼저 막는다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_3\",\"text\":\"일단 거리를 두고 상황을 관찰한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":250,\"type\":\"story\",\"title\":\"마을을 향한 질주\",\"text\":\"대피 중인 마을 입구 쪽으로 소울정크 한 무리가 돌진한다. 당신이 먼저 몸을 날려 길목을 막자, 하루가 놀란 눈으로 돌아보며 \\\"무리하지 마세요!\\\"라고 외친다. 그녀는 곧 검을 휘둘러 당신 곁의 적을 쓸어내고, 사람이 희생당하는 것만은 절대 안 된다는 단호한 기세를 보인다. 마을 아이의 울음소리가 멀리서 들린다. 흙먼지가 자욱하게 일어나 시야를 가리고 숨소리만 가까이에서 들려온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"부상당한 대원\",\"text\":\"전투 중 소울워커 한 명이 다리를 다쳐 쓰러진다. 하루는 의사를 꿈꾸던 소녀답게 본능적으로 상처 상태를 살피고 응급 처치를 시작한다. 그 사이에도 소울정크는 계속 다가오고 있다. 그녀는 치료와 전투 사이에서 갈등하며 잠시 말을 더듬는다. 당신에게 시선을 보내 도움을 청하는 모습에서 조심스러운 신뢰가 묻어난다. 하루의 손끝에서 번지는 연한 소울의 빛이 상처 부위를 감싸 안는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"내가 막을 테니 치료에 집중하라고 한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"함께 대원을 안전한 곳으로 옮긴다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"전투를 끝내는 게 먼저라고 말한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"서늘한 침묵\",\"text\":\"당신의 말에 하루가 잠시 입을 다문다. 부드럽던 표정이 굳고, 그녀는 조용히 대원의 손을 놓으며 일어선다. 화가 난 것은 아니지만 사람이 먼저라는 신념이 흔들린 듯한 눈빛이다. 곧 하루는 짧게 \\\"알겠어요\\\"라고 답한 뒤 검을 쥐고 적을 향해 나아간다. 어색한 공기 속에서 전투음만 협곡에 울린다. 그녀는 아무 말 없이 협곡 위쪽의 연기를 바라보며 한 호흡을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"우두머리의 포효\",\"text\":\"협곡 안쪽에서 거대한 변이 소울정크가 모습을 드러낸다. 땅이 울릴 만큼의 포효에 하루의 다리가 순간 굳는다. 그녀는 숨을 몰아쉬며 자신에게 \\\"나는 리더야\\\"라고 되뇌고, 검을 고쳐 잡는다. 몇 초의 망설임 뒤, 서늘한 눈빛으로 돌변한 하루가 당신에게 짧게 협공 타이밍을 알린다. 이 한 번의 합이 전투를 가른다. 협곡의 바위벽이 울려 파편이 우수수 떨어지고 공기가 팽팽하게 당겨진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"하루에게 마지막 일격을 맡긴다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"함께 합을 맞춰 마무리한다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"혼자서 우두머리를 상대하겠다고 나선다\",\"varOps\":[{\"var\":\"지휘\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"두 개의 검광\",\"text\":\"당신과 하루의 움직임이 하나의 선처럼 겹친다. 하루는 당신의 호흡을 읽고 한 박자 먼저 검을 휘둘러 길을 열고, 이어 당신의 일격이 우두머리의 약점을 정확히 꿰뚫는다. 하루가 놀란 얼굴로 돌아보며 \\\"방금 합, 정말 좋았어요\\\"라고 숨을 몰아쉰다. 협곡의 소울정크들이 연이어 쓰러지며 잔불이 사그라든다. 협곡에 번지는 푸른 소울의 빛이 두 사람의 얼굴을 잠시 환하게 비춘다. 하루는 흐트러진 숨을 고르며 다시 자세를 잡는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"쓰러지는 우두머리\",\"text\":\"우두머리가 마지막 힘을 쥐어짜 내듯 포효하며 몸을 뒤틀다 마침내 무너져 내린다. 하루는 검을 거두기 전까지 방심하지 않고 한 번 더 상대를 살핀 뒤에야 숨을 돌린다. 땀에 젖은 머리칼을 쓸어 넘기는 그녀의 얼굴에 안도와 피로가 함께 번진다. 당신과 시선이 마주치자 하루는 작게 고개를 끄덕이며 가벼운 목례로 고마움을 전한다. 협곡을 울리던 포효가 멎고 바람 소리만이 남아 긴 긴장이 서서히 풀려 간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"잔불 위의 일몰\",\"text\":\"전투가 끝나고 협곡에는 소울정크가 남긴 잔불만 가물거린다. 하루는 검을 땅에 꽂고 길게 한숨을 내쉰다. 부상자 확인과 마을 상황 보고를 마친 뒤에야 그녀의 표정이 풀린다. 쑥스러운 듯 당신에게 감사 인사를 건네려다 말을 고르는 모습이 보인다. 노을이 지는 가운데, 둘은 돌아가는 길에 전투를 되짚으며 이야기를 나눈다. 멀리서 마을 사람들의 안도하는 목소리가 바람을 타고 희미하게 들려온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"지휘\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"지휘\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"협곡의 수호자들\",\"text\":\"완벽에 가까운 지휘로 단 한 명의 희생자도 없이 협곡을 지켜 냈다. 마을 사람들이 둘에게 감사 인사를 건네자 하루는 \\\"저 같은 게…\\\"라며 얼굴을 붉히지만, 마음 한켠에서는 리더로서의 자신감이 조금 자라난다. 하루는 당신에게 다음 작전도 곁에서 함께해 달라고 조심스럽게 청한다. 노을이 둘의 어깨 위로 길게 드리운다. 하루의 검 끝에서는 마지막 소울의 빛이 별처럼 흩어져 사라진다. 그 모습을 지켜보며 당신도 조용히 미소를 짓게 된다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"상처 입은 승리\",\"text\":\"토벌은 성공했지만 몇 명의 부상자가 남았다. 하루는 아쉬움을 숨기지 못하고 자책하지만, 당신이 곁에서 위로하자 이내 고개를 들어 다음에는 더 잘하겠다고 다짐한다. 의사를 꿈꾸던 손으로 마지막까지 부상자를 돌보며, 그녀는 지켜야 할 것들의 무게를 다시 새긴다. 돌아가는 길, 노을 아래로 길게 늘어진 두 사람의 그림자가 나란히 걸음을 맞춘다. 침묵 속에서도 서로를 향한 믿음이 조금씩 단단해진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"어긋난 호흡의 밤\",\"text\":\"소울정크는 물리쳤지만 호흡이 맞지 않아 마을 일부가 피해를 입었다. 하루는 말없이 폐허가 된 집터를 바라보다 당신에게 \\\"제 판단이 늦었어요\\\"라고 조용히 말한다. 그녀는 자책 속에서도 이를 악물고, 다음에는 반드시 모두를 지키겠다고 다짐한다. 당신은 그녀 곁에서 함께 잔해를 치운다. 별이 하나둘 떠오르는 밤하늘 아래, 하루는 오래도록 검 손잡이를 놓지 못한 채 서 있다. 당신은 그 곁을 지키며 말없이 시간을 보낸다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n9\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '잔불이 꺼지지 않는 협곡: 소울정크 토벌선'
);

-- 02. [하루 에스티아] 하루 선생님의 하루: 아르카디아 병원 봉사
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '하루 선생님의 하루: 아르카디아 병원 봉사', 'published', 0, '{\"vars\":[{\"name\":\"정성\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"흰 가운을 입은 아침\",\"text\":\"전투가 없는 모처럼 평화로운 아침, 하루 에스티아는 아르카디아 렐름의 임시 병원에서 봉사 활동을 시작한다. 흰 가운 소매를 걷으며 그녀는 의사를 꿈꾸던 시절의 설렘을 떠올리고 은은하게 웃는다. 오늘은 당신이 일손을 돕기로 했다. 하루는 약품 목록과 환자 명단을 건네며 부드럽게 설명하지만, 가운 입은 자신이 쑥스러워 말끝이 흐려진다. 복도에는 소독약 냄새와 갓 끓인 차 향기가 섞여 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"약품 정리부터 맡겠다고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"환자들에게 먼저 인사를 건네자고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_3\",\"text\":\"휴식 시간부터 챙기자고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"병실 순회\",\"text\":\"하루와 함께 병실을 돌며 환자들에게 안부를 묻는다. 하루는 한 사람 한 사람의 이름과 증상을 기억하고 있어 당신을 놀라게 한다. 아픈 아이에게는 눈높이를 맞춰 앉아 천천히 말을 건네고, 어르신에게는 존댓말로 정중히 손을 잡는다. 칭찬을 들으면 \\\"저 같은 게…\\\"라며 손사래를 치는 모습이 병실의 분위기를 따뜻하게 만든다. 병실마다 창가에 놓인 작은 화분이 하루의 손길을 기다리는 듯 싱그럽다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"소울정크 부상자\",\"text\":\"오전 중반, 최근 소울정크에게 부상당한 소울워커 한 명이 병원으로 이송된다. 하루는 순간 얼굴이 굳지만 곧 숙련된 손놀림으로 상처를 소독하기 시작한다. 전투에서 보이던 단호함이 의료 현장에서도 이어진다. 한편 환자가 무서워서 소리를 지르자 하루가 낮은 목소리로 안심시키려 한다. 당신은 붕대를 건네는 보조 역할을 맡는다. 병동 전체가 잠시 술렁이지만 그녀가 내리는 낮은 지시에 직원들의 움직임이 빠르게 정돈된다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"약품 창고에서\",\"text\":\"아침 회진 준비를 위해 하루는 당신과 함께 약품 창고로 향한다. 선반에는 라벨이 빼곡하게 붙어 있고, 하루는 약 이름을 줄줄 읊으며 필요한 것들을 능숙하게 골라낸다. 당신이 감탄하자 하루는 \\\"그냥 외우는 걸 좋아했을 뿐이에요\\\"라며 손사래를 친다. 그러다 높은 선반의 상자에 손이 닿지 않아 발끝을 세우고, 조금 부끄러운 얼굴로 도움을 청한다. 당신이 상자를 내려 주자 하루는 헤헤 웃으며 고개를 숙여 고마움을 표한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"울음을 터뜨린 아이\",\"text\":\"병동 한켠에서 어린 환자가 주사가 무섭다며 울음을 터뜨린다. 하루는 주사기를 든 채 곤란해하며 \\\"아하하…\\\"라고 웃지만 사실 자신도 주사가 조금 무섭다. 그래도 아이 앞에서는 어른스러워야 한다며 용기를 내려 한다. 당신은 곁에서 아이의 시선을 다른 곳으로 돌려줄 방법을 찾아야 한다. 병실 한쪽에서는 다른 환자들이 걱정스러운 눈으로 이쪽을 지켜보고 있다. 하루는 아이의 눈높이에 맞춰 앉아 천천히 숨을 고르며 말을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"재미있는 이야기를 들려주며 아이를 달랜다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"하루가 직접 달래도록 지켜본다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"빨리 끝내자고 재촉한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"이야기 시간\",\"text\":\"당신이 꾸며낸 우스꽝스러운 소울정크 이야기에 아이의 울음이 서서히 잦아든다. 하루는 그 틈을 타 조심스럽게 주사를 놓고, 마지막에는 자신도 모르게 숨을 내쉬며 \\\"다 됐어요\\\"라고 속삭인다. 아이가 하루에게 웃어 보이자 그녀의 눈가가 부드럽게 휘어진다. 곁에서 보던 간호사가 두 사람의 호흡을 칭찬한다. 주사 후 아이는 하루에게 작은 종이학을 건네며 수줍게 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"점심, 고기 요리의 유혹\",\"text\":\"점심시간이 되자 병원 식당에서 갓 구운 고기 요리 냄새가 퍼진다. 하루의 배에서 작은 소리가 나고, 그녀는 얼굴을 붉히며 헛기침을 한다. 고기와 빵을 좋아한다는 사실을 들키는 순간이다. 하루는 당신과 나란히 앉아 조심스럽게 식사를 하면서도, 환자들 몫을 먼저 챙기려는 배려를 잊지 않는다. 식당 창가의 햇살이 따뜻하게 쏟아져 들어와 잠시나마 전장의 기억이 멀게 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"환자들 식사 배식을 같이 돕자고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"조용히 둘이 점심을 즐긴다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"하루에게 먼저 식사를 하라고 강권한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"작은 실랑이\",\"text\":\"하루는 손사래를 치며 환자 먼저라고 말하지만 당신의 끈질긴 권유에 결국 한 입을 베어 문다. 그리고 눈이 휘둥그레지며 \\\"맛있어요…\\\"라고 중얼거린다. 그 모습에 주변 직원들이 웃음을 터뜨리고, 하루는 얼굴이 새빨개져 고개를 숙인다. 작은 소동이 병원에 온기를 더한다. 하루는 한 입 더 먹으라는 권유에 끝내 웃음을 터뜨리고 만다. 결국 하루는 접시를 반쯤 비우고 나서야 환자들 몫을 챙기러 일어선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"오후, 지쳐 보이는 환자\",\"text\":\"오후 회진 중, 하루는 말없이 창밖만 바라보는 환자 한 명을 발견한다. 공백 사건으로 가족을 잃은 사람이다. 하루는 자신의 상실이 떠올라 잠시 가슴이 먹먹해지지만 곧 옆에 앉아 조용히 귀를 기울인다. 위로의 말을 고르는 하루의 손이 미세하게 떨린다. 당신은 두 사람의 대화를 지켜보며 한마디를 보탤지 고민한다. 병실에는 오후의 느린 햇살과 시계 초침 소리만이 흐른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"환자의 이야기를 끝까지 함께 들어 준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"차를 한 잔 가져다드린다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"쉬시라고 하고 자리를 비켜 준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":60,\"type\":\"story\",\"title\":\"창가의 이야기\",\"text\":\"당신과 하루는 환자의 곁에 나란히 앉아 천천히 이어지는 이야기를 듣는다. 가족과 함께했던 따뜻한 식탁, 갑작스러웠던 공백의 날. 이야기가 끝나자 하루는 환자의 손을 감싸 쥐고 \\\"말씀해 주셔서 감사해요\\\"라고 조용히 말한다. 환자의 눈가가 젖고, 병실에 따뜻한 침묵이 내려앉는다. 창밖에는 저물어 가는 해가 걸려 있다. 하루는 이야기를 마음에 새기듯 천천히 고개를 끄덕이며 환자의 손을 놓지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"퇴근 전 마지막 회진\",\"text\":\"해가 지기 전 마지막 회진. 하루는 졸음을 참으며 한 병실씩 불을 낮추고 이불을 고쳐 덮어 준다. 아이들은 벌써 잠들었고, 어르신들은 작게 손을 흔들어 인사한다. 하루는 걸음을 최대한 조용히 하며 당신에게 입가에 손을 대고 쉿 하는 시늉을 한다. 복도 끝 창에는 붉은 노을이 가득 들어차 있다. 간호사들이 눈인사로 하루의 하루를 격려하고, 하루는 쑥스러운 듯 가운 소매를 만지작거린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"저녁노을과 마무리\",\"text\":\"하루의 일과가 끝나고 병원 옥상에서 노을을 바라본다. 하루는 가운을 벗으며 오늘 하루를 찬찬히 돌아보고, 당신에게 도와줘서 고맙다고 말한다. 의사의 꿈은 흐려졌지만 이곳에서만큼은 그 꿈 가까이에 닿는 기분이라고, 쑥스러운 듯 털어놓는다. 바람이 부드럽게 불어 둘의 머리칼을 흔든다. 옥상 난간 너머로 렐름의 불빛이 하나둘 켜지기 시작한다. 하루는 한참 노을을 바라보다 가볍게 기지개를 켜고 당신을 돌아본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"하루 선생님, 그리고 당신\",\"text\":\"오늘 하루 병원 사람들은 둘을 향해 \\\"다음에도 꼭 와 주세요\\\"라며 환하게 웃었다. 하루는 당신 덕분에 더 좋은 하루였다고, 조금 용기를 낸 목소리로 말한다. 언젠가 정말 의사가 되는 날이 와도 오늘을 잊지 않겠다며 수줍게 웃는다. 병원 문을 나서는 두 사람의 등 뒤로 환자들의 인사 소리가 오래도록 따라온다. 하루는 문득 뒤를 돌아보고 깊이 고개를 숙인다. 당신에게는 그 모습이 가장 어울리는 의사 선생님의 얼굴로 보인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"조금 서툴렀지만\",\"text\":\"다소 서툰 부분도 있었지만 무사히 하루가 지나갔다. 하루는 \\\"내일은 더 잘해 볼게요\\\"라며 가운을 곱게 접는다. 그 소박한 의지가 노을에 물들어 따뜻해 보인다. 하루는 복도 끝에서 환자 명단을 한 번 더 확인하며 내일 할 일을 메모한다. 당신이 곁에서 그 모습을 지켜보며 조용히 응원의 말을 보탠다. 작지만 확실한 한 걸음이 오늘 하루에 남았다. 가운 주머니에는 환자가 건넨 사탕 하나가 들어 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"피곤한 귀갓길\",\"text\":\"정신없이 하루가 지나 갔다. 하루는 환자들을 충분히 돌보지 못한 것 같아 아쉬워하며 어깨를 늘어뜨린다. 하지만 당신이 곁에서 고생했다고 말하자, 그녀는 작게 고개를 끄덕이며 다음엔 더 잘하겠다고 다짐한다. 노을이 지는 길 위로 지친 두 사람의 그림자가 길게 늘어진다. 하루는 문득 걸음을 멈추고 병원 쪽을 한 번 돌아본다. 아쉬움 속에서도 내일을 기약하는 눈빛이 그녀의 얼굴에 남는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"정성\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"흰 가운을 입은 아침\",\"text\":\"전투가 없는 모처럼 평화로운 아침, 하루 에스티아는 아르카디아 렐름의 임시 병원에서 봉사 활동을 시작한다. 흰 가운 소매를 걷으며 그녀는 의사를 꿈꾸던 시절의 설렘을 떠올리고 은은하게 웃는다. 오늘은 당신이 일손을 돕기로 했다. 하루는 약품 목록과 환자 명단을 건네며 부드럽게 설명하지만, 가운 입은 자신이 쑥스러워 말끝이 흐려진다. 복도에는 소독약 냄새와 갓 끓인 차 향기가 섞여 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"약품 정리부터 맡겠다고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"환자들에게 먼저 인사를 건네자고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_3\",\"text\":\"휴식 시간부터 챙기자고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"병실 순회\",\"text\":\"하루와 함께 병실을 돌며 환자들에게 안부를 묻는다. 하루는 한 사람 한 사람의 이름과 증상을 기억하고 있어 당신을 놀라게 한다. 아픈 아이에게는 눈높이를 맞춰 앉아 천천히 말을 건네고, 어르신에게는 존댓말로 정중히 손을 잡는다. 칭찬을 들으면 \\\"저 같은 게…\\\"라며 손사래를 치는 모습이 병실의 분위기를 따뜻하게 만든다. 병실마다 창가에 놓인 작은 화분이 하루의 손길을 기다리는 듯 싱그럽다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"소울정크 부상자\",\"text\":\"오전 중반, 최근 소울정크에게 부상당한 소울워커 한 명이 병원으로 이송된다. 하루는 순간 얼굴이 굳지만 곧 숙련된 손놀림으로 상처를 소독하기 시작한다. 전투에서 보이던 단호함이 의료 현장에서도 이어진다. 한편 환자가 무서워서 소리를 지르자 하루가 낮은 목소리로 안심시키려 한다. 당신은 붕대를 건네는 보조 역할을 맡는다. 병동 전체가 잠시 술렁이지만 그녀가 내리는 낮은 지시에 직원들의 움직임이 빠르게 정돈된다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"약품 창고에서\",\"text\":\"아침 회진 준비를 위해 하루는 당신과 함께 약품 창고로 향한다. 선반에는 라벨이 빼곡하게 붙어 있고, 하루는 약 이름을 줄줄 읊으며 필요한 것들을 능숙하게 골라낸다. 당신이 감탄하자 하루는 \\\"그냥 외우는 걸 좋아했을 뿐이에요\\\"라며 손사래를 친다. 그러다 높은 선반의 상자에 손이 닿지 않아 발끝을 세우고, 조금 부끄러운 얼굴로 도움을 청한다. 당신이 상자를 내려 주자 하루는 헤헤 웃으며 고개를 숙여 고마움을 표한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"울음을 터뜨린 아이\",\"text\":\"병동 한켠에서 어린 환자가 주사가 무섭다며 울음을 터뜨린다. 하루는 주사기를 든 채 곤란해하며 \\\"아하하…\\\"라고 웃지만 사실 자신도 주사가 조금 무섭다. 그래도 아이 앞에서는 어른스러워야 한다며 용기를 내려 한다. 당신은 곁에서 아이의 시선을 다른 곳으로 돌려줄 방법을 찾아야 한다. 병실 한쪽에서는 다른 환자들이 걱정스러운 눈으로 이쪽을 지켜보고 있다. 하루는 아이의 눈높이에 맞춰 앉아 천천히 숨을 고르며 말을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"재미있는 이야기를 들려주며 아이를 달랜다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"하루가 직접 달래도록 지켜본다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"빨리 끝내자고 재촉한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"이야기 시간\",\"text\":\"당신이 꾸며낸 우스꽝스러운 소울정크 이야기에 아이의 울음이 서서히 잦아든다. 하루는 그 틈을 타 조심스럽게 주사를 놓고, 마지막에는 자신도 모르게 숨을 내쉬며 \\\"다 됐어요\\\"라고 속삭인다. 아이가 하루에게 웃어 보이자 그녀의 눈가가 부드럽게 휘어진다. 곁에서 보던 간호사가 두 사람의 호흡을 칭찬한다. 주사 후 아이는 하루에게 작은 종이학을 건네며 수줍게 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"점심, 고기 요리의 유혹\",\"text\":\"점심시간이 되자 병원 식당에서 갓 구운 고기 요리 냄새가 퍼진다. 하루의 배에서 작은 소리가 나고, 그녀는 얼굴을 붉히며 헛기침을 한다. 고기와 빵을 좋아한다는 사실을 들키는 순간이다. 하루는 당신과 나란히 앉아 조심스럽게 식사를 하면서도, 환자들 몫을 먼저 챙기려는 배려를 잊지 않는다. 식당 창가의 햇살이 따뜻하게 쏟아져 들어와 잠시나마 전장의 기억이 멀게 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"환자들 식사 배식을 같이 돕자고 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"조용히 둘이 점심을 즐긴다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"하루에게 먼저 식사를 하라고 강권한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"작은 실랑이\",\"text\":\"하루는 손사래를 치며 환자 먼저라고 말하지만 당신의 끈질긴 권유에 결국 한 입을 베어 문다. 그리고 눈이 휘둥그레지며 \\\"맛있어요…\\\"라고 중얼거린다. 그 모습에 주변 직원들이 웃음을 터뜨리고, 하루는 얼굴이 새빨개져 고개를 숙인다. 작은 소동이 병원에 온기를 더한다. 하루는 한 입 더 먹으라는 권유에 끝내 웃음을 터뜨리고 만다. 결국 하루는 접시를 반쯤 비우고 나서야 환자들 몫을 챙기러 일어선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"오후, 지쳐 보이는 환자\",\"text\":\"오후 회진 중, 하루는 말없이 창밖만 바라보는 환자 한 명을 발견한다. 공백 사건으로 가족을 잃은 사람이다. 하루는 자신의 상실이 떠올라 잠시 가슴이 먹먹해지지만 곧 옆에 앉아 조용히 귀를 기울인다. 위로의 말을 고르는 하루의 손이 미세하게 떨린다. 당신은 두 사람의 대화를 지켜보며 한마디를 보탤지 고민한다. 병실에는 오후의 느린 햇살과 시계 초침 소리만이 흐른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"환자의 이야기를 끝까지 함께 들어 준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"차를 한 잔 가져다드린다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"쉬시라고 하고 자리를 비켜 준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":60,\"type\":\"story\",\"title\":\"창가의 이야기\",\"text\":\"당신과 하루는 환자의 곁에 나란히 앉아 천천히 이어지는 이야기를 듣는다. 가족과 함께했던 따뜻한 식탁, 갑작스러웠던 공백의 날. 이야기가 끝나자 하루는 환자의 손을 감싸 쥐고 \\\"말씀해 주셔서 감사해요\\\"라고 조용히 말한다. 환자의 눈가가 젖고, 병실에 따뜻한 침묵이 내려앉는다. 창밖에는 저물어 가는 해가 걸려 있다. 하루는 이야기를 마음에 새기듯 천천히 고개를 끄덕이며 환자의 손을 놓지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"퇴근 전 마지막 회진\",\"text\":\"해가 지기 전 마지막 회진. 하루는 졸음을 참으며 한 병실씩 불을 낮추고 이불을 고쳐 덮어 준다. 아이들은 벌써 잠들었고, 어르신들은 작게 손을 흔들어 인사한다. 하루는 걸음을 최대한 조용히 하며 당신에게 입가에 손을 대고 쉿 하는 시늉을 한다. 복도 끝 창에는 붉은 노을이 가득 들어차 있다. 간호사들이 눈인사로 하루의 하루를 격려하고, 하루는 쑥스러운 듯 가운 소매를 만지작거린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"저녁노을과 마무리\",\"text\":\"하루의 일과가 끝나고 병원 옥상에서 노을을 바라본다. 하루는 가운을 벗으며 오늘 하루를 찬찬히 돌아보고, 당신에게 도와줘서 고맙다고 말한다. 의사의 꿈은 흐려졌지만 이곳에서만큼은 그 꿈 가까이에 닿는 기분이라고, 쑥스러운 듯 털어놓는다. 바람이 부드럽게 불어 둘의 머리칼을 흔든다. 옥상 난간 너머로 렐름의 불빛이 하나둘 켜지기 시작한다. 하루는 한참 노을을 바라보다 가볍게 기지개를 켜고 당신을 돌아본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"하루 선생님, 그리고 당신\",\"text\":\"오늘 하루 병원 사람들은 둘을 향해 \\\"다음에도 꼭 와 주세요\\\"라며 환하게 웃었다. 하루는 당신 덕분에 더 좋은 하루였다고, 조금 용기를 낸 목소리로 말한다. 언젠가 정말 의사가 되는 날이 와도 오늘을 잊지 않겠다며 수줍게 웃는다. 병원 문을 나서는 두 사람의 등 뒤로 환자들의 인사 소리가 오래도록 따라온다. 하루는 문득 뒤를 돌아보고 깊이 고개를 숙인다. 당신에게는 그 모습이 가장 어울리는 의사 선생님의 얼굴로 보인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"조금 서툴렀지만\",\"text\":\"다소 서툰 부분도 있었지만 무사히 하루가 지나갔다. 하루는 \\\"내일은 더 잘해 볼게요\\\"라며 가운을 곱게 접는다. 그 소박한 의지가 노을에 물들어 따뜻해 보인다. 하루는 복도 끝에서 환자 명단을 한 번 더 확인하며 내일 할 일을 메모한다. 당신이 곁에서 그 모습을 지켜보며 조용히 응원의 말을 보탠다. 작지만 확실한 한 걸음이 오늘 하루에 남았다. 가운 주머니에는 환자가 건넨 사탕 하나가 들어 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"피곤한 귀갓길\",\"text\":\"정신없이 하루가 지나 갔다. 하루는 환자들을 충분히 돌보지 못한 것 같아 아쉬워하며 어깨를 늘어뜨린다. 하지만 당신이 곁에서 고생했다고 말하자, 그녀는 작게 고개를 끄덕이며 다음엔 더 잘하겠다고 다짐한다. 노을이 지는 길 위로 지친 두 사람의 그림자가 길게 늘어진다. 하루는 문득 걸음을 멈추고 병원 쪽을 한 번 돌아본다. 아쉬움 속에서도 내일을 기약하는 눈빛이 그녀의 얼굴에 남는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '하루 선생님의 하루: 아르카디아 병원 봉사'
);

-- 03. [하루 에스티아] 한밤의 폐병원: 비명 소리의 정체
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '한밤의 폐병원: 비명 소리의 정체', 'published', 0, '{\"vars\":[{\"name\":\"단서\",\"initial\":0},{\"name\":\"용기\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"괴담이 도는 폐병원\",\"text\":\"별숲리그에 접수된 기묘한 민원이다. 클라우드림 외곽의 폐병원에서 한밤마다 비명 소리가 들린다는 것. 하루 에스티아는 소울정크의 흔적일 수 있다는 말에 조사를 맡기로 하지만, 귀신 이야기가 나오자마자 얼굴이 새파랗게 질린다. \\\"귀, 귀신 같은 건 아니겠죠?\\\" 하며 당신의 소매를 슬쩍 붙든다. 둘은 해질녘에 폐병원 앞에 도착한다. 낡은 간판이 바람에 흔들리며 끼익 소리를 내자 하루의 어깨가 움찔한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"정문으로 당당히 들어간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"뒷문의 흔적부터 살핀다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]},{\"id\":\"o2_3\",\"text\":\"하루의 손을 잡고 천천히 들어간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":2}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"뒷문의 발자국\",\"text\":\"건물 뒤편의 풀숲에서 최근 찍힌 듯한 발자국이 발견된다. 사람의 것이 아닌 기묘한 크기다. 하루는 몸을 숙여 자국을 살피며 \\\"소울정크의 것은 아닌 것 같아요\\\"라고 진지하게 말한다. 의사를 꿈꿨던 관찰력이 빛나는 순간이지만, 갑자기 바람에 문이 삐걱거리자 히익 하고 소리를 낸다. 달빛이 구름에 가려졌다 나타나기를 반복하며 숲의 그림자가 일렁인다. 당신이 손전등으로 풀숲을 비추자 하루는 얼른 당신의 옷자락을 붙든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"어둠 속의 복도\",\"text\":\"불이 꺼진 복도에는 먼지 쌓인 휠체어와 깨진 창문이 즐비하다. 하루는 손전등을 두 손으로 꼭 쥐고 당신 옆에 바짝 붙어 걷는다. 때때로 바닥의 삐걱임에 어깨를 움찔하며 \\\"아, 아무것도 아니죠?\\\"라고 확인한다. 하지만 사람이 다칠 수 있다는 생각이 들 때마다 걸음이 조금씩 단단해진다. 손전등 불빛이 닿지 않는 어둠 속에서는 알 수 없는 소리가 이따금 들려온다. 그때마다 하루가 숨을 들이켜는 소리가 당신의 귓가에 닿는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"수상한 간판\",\"text\":\"병원 현관 안쪽 로비에 들어서자 먼지 쌓인 접수 창구와 쓰러진 의자가 두 사람을 맞는다. 벽에는 오래된 진료 안내판과 낙서 같은 기호가 남아 있다. 하루는 손전등으로 기호를 비추며 \\\"어딘가 본 적 있는 문양인데…\\\"라고 중얼거린다. 그때 어딘가에서 쿵 하는 소리가 나 하루가 소스라친다. 당신은 하루의 어깨를 가볍게 잡아 진정시킨다. 천장에서 먼지가 떨어져 내리자 두 사람은 소리를 낮추며 서로를 바라본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"첫 번째 비명\",\"text\":\"복도 끝 어디선가 날카로운 비명이 울려 퍼진다. 하루는 비명을 지르며 당신 뒤로 숨는다. 하지만 이내 그 소리가 사람의 목소리임을 알아채고 표정이 굳어진다. 누군가 갇혀 있을지도 모른다. 하루는 떨리는 목소리로 소리의 방향을 짚으며 당신에게 판단을 맡긴다. 복도에 메아리가 겹쳐 울려 소리의 위치를 가늠하기가 쉽지 않다. 하루는 손전등을 고쳐 잡고 불빛이 흔들리지 않게 애쓴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"소리가 난 쪽으로 곧장 달려간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"조용히 소리를 따라가며 주변을 살핀다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"일단 입구로 물러나 대책을 세운다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"닫힌 문 앞\",\"text\":\"소리가 난 곳의 문은 안쪽에서 잠겨 있다. 하루는 용기를 짜내 문을 두드리며 \\\"누구 있으세요?\\\"라고 외친다. 안에서 희미한 기척이 들려오고, 그녀의 눈이 반짝인다. 사람을 구해야 한다는 마음이 두려움을 눌러 버린 순간이다. 당신은 문을 열 방법을 찾아야 한다. 문틈으로는 희미한 푸른빛이 새어 나오고 있다. 하루는 문고리를 잡은 손에 힘을 주며 당신을 돌아본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"수상한 흔적\",\"text\":\"비명이 들린 방 근처 바닥에서 반짝이는 가루와 누군가 끌려간 듯한 자국이 발견된다. 하루는 가루를 손끝에 묻혀 냄새를 맡고는 소울 에너지의 잔향임을 알아챈다. 귀신이 아니라 누군가의 소행일 가능성이 커졌다. 안도한 듯하면서도 더 위험할 수 있다는 걸 깨닫고 하루가 입술을 깨문다. 가루는 어둠 속에서 작은 별처럼 반짝이며 지하로 이어지는 계단까지 점점이 이어져 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"남은 자국을 따라 지하로 내려간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_2\",\"text\":\"하루에게 판단을 맡긴다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"위험하니 증거만 챙기고 철수하자고 한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"하루의 결정\",\"text\":\"당신이 판단을 묻자 하루는 잠시 눈을 감고 호흡을 고른다. 이윽고 눈을 뜬 그녀의 표정은 한결 단호하다. \\\"지하로 내려가요. 제가 앞에 서겠습니다.\\\" 겁 많은 하루가 리더로서 앞장서는 순간, 당신은 그 뒷모습에서 믿음직함을 느낀다. 그녀의 손은 여전히 조금 떨리고 있다. 지하로 이어지는 계단은 어둠에 잠겨 바닥이 보이지 않는다. 두 사람은 한 걸음씩 신중히 내딛는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"지하의 정체\",\"text\":\"지하실에서 발견된 것은 소울정크 변이체를 몰래 연구하던 네드 컴퍼니의 낡은 장비와, 스피커로 틀어 놓은 비명 녹음이었다. 괴담은 누군가 사람들을 쫓아내려 만든 가짜였던 것. 하루는 어이없다는 듯 웃다가 곧 분노로 눈빛이 서늘해진다. 갑자기 어둠 속에서 경비 변이체가 모습을 드러낸다. 천장에 매달린 형광등이 깜빡이며 기계 사이로 괴이한 그림자를 만들어 낸다. 하루는 검자루를 쥐고 당신 앞에 선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"증거를 사진으로 남기고 장비를 회수한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]},{\"id\":\"o10_2\",\"text\":\"남은 변이체가 없는지 건물을 한 번 더 수색한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"일단 빨리 나가자고 하루의 손을 잡는다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"마지막 수색\",\"text\":\"두 사람은 지하실의 다른 방들을 하나하나 확인한다. 하루는 문을 열 때마다 심호흡을 하지만 이제는 손이 덜 떨린다. 마지막 방에서 쓰러져 있던 경비원을 발견해 응급 처치를 하고 안전한 곳으로 옮긴다. 하루는 \\\"사람이었다니 다행이에요\\\"라며 한숨을 내쉰다. 의사 지망생의 손길이 능숙하게 움직인다. 지하실의 공기는 차갑고 습해서 두 사람의 숨소리까지 선명하게 들린다. 하루는 조용히 문틈의 불빛을 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"새벽의 보고서\",\"text\":\"폐병원을 나온 두 사람은 별숲리그 지부에서 조사 결과를 정리한다. 하루는 졸린 눈을 비비며 보고서를 쓰다가 문득 오늘 밤 일을 떠올리며 작게 웃는다. 겁이 났던 순간과 용기를 냈던 순간이 한꺼번에 스친다. 당신이 곁에서 커피를 건네자 하루는 두 손으로 받아 들고 \\\"고맙습니다\\\"라고 말한다. 창밖에서는 새소리가 들리기 시작한다. 보고서 말미에는 하루의 단정한 글씨로 협력자에 대한 감사의 말이 적힌다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"비명의 끝\",\"text\":\"변이체를 물리치고 나자 폐병원에는 다시 고요가 찾아온다. 하루는 검을 거두고 맥이 풀린 듯 주저앉아 \\\"귀신이 아니라서 다행이에요…\\\"라고 중얼거린다. 그리고 곧 당신을 돌아보며 부끄러운 듯 웃는다. 증거를 정리해 별숲리그에 보고할 시간이다. 창밖으로 새벽빛이 스며들며 폐병원의 음산한 기운이 한결 옅어진다. 하루는 가슴을 쓸어내리며 다시는 이런 조사는 사양이라는 듯 작게 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":5,\"max\":null},{\"var\":\"용기\",\"min\":3,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"진실을 밝힌 밤\",\"text\":\"단서를 꼼꼼히 모으고 용기도 잃지 않은 덕분에 네드 컴퍼니의 은닉 시설 증거를 확보했다. 하루는 보고서를 쓰며 \\\"제가 이렇게 해낼 수 있을 줄은 몰랐어요\\\"라며 놀라워한다. 그리고 당신 덕분이라며 환하게 웃는다. 이제 귀신 이야기는 더 이상 무섭지 않을 것 같다며… 아마도. 돌아오는 길, 하루는 폐병원이 보이지 않게 될 때까지 몇 번이나 뒤를 돌아본다. 당신이 웃으며 괜찮다고 하자 그녀는 \\\"그, 그래도 무서운 건 무서워요\\\"라며 슬쩍 당신 곁으로 붙는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"절반의 진실\",\"text\":\"괴담의 정체는 밝혔지만 증거가 충분하지 않아 네드 컴퍼니까지 추궁하지는 못했다. 하루는 아쉬워하면서도 안전하게 돌아온 것에 안도한다. 돌아오는 길에는 당신 옆에 바짝 붙어 걸으며 자꾸 뒤를 돌아본다. 새벽 하늘이 밝아 오는 가운데 별숲리그에 올릴 보고서를 정리하는 하루의 손이 분주하다. 그녀는 당신과 함께 부족했던 부분을 되짚으며 다음 조사를 위한 점검표를 만든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"무서웠던 기억\",\"text\":\"하루는 겁에 질려 제대로 조사를 하지 못한 채 병원을 빠져나왔다. 단서는 거의 없고, 그녀는 한동안 어둠 속에서 들리던 소리를 잊지 못한다. \\\"다음에는 꼭 제대로 할게요…\\\" 하며 풀 죽은 목소리로 말하는 하루를 당신이 다독인다. 폐병원이 보이지 않는 곳까지 와서야 하루는 겨우 숨을 돌린다. 한동안은 복도의 삐걱거림만 들어도 움찔하게 될 것 같다며 어색하게 웃는다. 당신은 따뜻한 차 한 잔을 권하며 곁을 지킨다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"단서\",\"initial\":0},{\"name\":\"용기\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"괴담이 도는 폐병원\",\"text\":\"별숲리그에 접수된 기묘한 민원이다. 클라우드림 외곽의 폐병원에서 한밤마다 비명 소리가 들린다는 것. 하루 에스티아는 소울정크의 흔적일 수 있다는 말에 조사를 맡기로 하지만, 귀신 이야기가 나오자마자 얼굴이 새파랗게 질린다. \\\"귀, 귀신 같은 건 아니겠죠?\\\" 하며 당신의 소매를 슬쩍 붙든다. 둘은 해질녘에 폐병원 앞에 도착한다. 낡은 간판이 바람에 흔들리며 끼익 소리를 내자 하루의 어깨가 움찔한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"정문으로 당당히 들어간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"뒷문의 흔적부터 살핀다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]},{\"id\":\"o2_3\",\"text\":\"하루의 손을 잡고 천천히 들어간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":2}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"뒷문의 발자국\",\"text\":\"건물 뒤편의 풀숲에서 최근 찍힌 듯한 발자국이 발견된다. 사람의 것이 아닌 기묘한 크기다. 하루는 몸을 숙여 자국을 살피며 \\\"소울정크의 것은 아닌 것 같아요\\\"라고 진지하게 말한다. 의사를 꿈꿨던 관찰력이 빛나는 순간이지만, 갑자기 바람에 문이 삐걱거리자 히익 하고 소리를 낸다. 달빛이 구름에 가려졌다 나타나기를 반복하며 숲의 그림자가 일렁인다. 당신이 손전등으로 풀숲을 비추자 하루는 얼른 당신의 옷자락을 붙든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"어둠 속의 복도\",\"text\":\"불이 꺼진 복도에는 먼지 쌓인 휠체어와 깨진 창문이 즐비하다. 하루는 손전등을 두 손으로 꼭 쥐고 당신 옆에 바짝 붙어 걷는다. 때때로 바닥의 삐걱임에 어깨를 움찔하며 \\\"아, 아무것도 아니죠?\\\"라고 확인한다. 하지만 사람이 다칠 수 있다는 생각이 들 때마다 걸음이 조금씩 단단해진다. 손전등 불빛이 닿지 않는 어둠 속에서는 알 수 없는 소리가 이따금 들려온다. 그때마다 하루가 숨을 들이켜는 소리가 당신의 귓가에 닿는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"수상한 간판\",\"text\":\"병원 현관 안쪽 로비에 들어서자 먼지 쌓인 접수 창구와 쓰러진 의자가 두 사람을 맞는다. 벽에는 오래된 진료 안내판과 낙서 같은 기호가 남아 있다. 하루는 손전등으로 기호를 비추며 \\\"어딘가 본 적 있는 문양인데…\\\"라고 중얼거린다. 그때 어딘가에서 쿵 하는 소리가 나 하루가 소스라친다. 당신은 하루의 어깨를 가볍게 잡아 진정시킨다. 천장에서 먼지가 떨어져 내리자 두 사람은 소리를 낮추며 서로를 바라본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"첫 번째 비명\",\"text\":\"복도 끝 어디선가 날카로운 비명이 울려 퍼진다. 하루는 비명을 지르며 당신 뒤로 숨는다. 하지만 이내 그 소리가 사람의 목소리임을 알아채고 표정이 굳어진다. 누군가 갇혀 있을지도 모른다. 하루는 떨리는 목소리로 소리의 방향을 짚으며 당신에게 판단을 맡긴다. 복도에 메아리가 겹쳐 울려 소리의 위치를 가늠하기가 쉽지 않다. 하루는 손전등을 고쳐 잡고 불빛이 흔들리지 않게 애쓴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"소리가 난 쪽으로 곧장 달려간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"조용히 소리를 따라가며 주변을 살핀다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"일단 입구로 물러나 대책을 세운다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"닫힌 문 앞\",\"text\":\"소리가 난 곳의 문은 안쪽에서 잠겨 있다. 하루는 용기를 짜내 문을 두드리며 \\\"누구 있으세요?\\\"라고 외친다. 안에서 희미한 기척이 들려오고, 그녀의 눈이 반짝인다. 사람을 구해야 한다는 마음이 두려움을 눌러 버린 순간이다. 당신은 문을 열 방법을 찾아야 한다. 문틈으로는 희미한 푸른빛이 새어 나오고 있다. 하루는 문고리를 잡은 손에 힘을 주며 당신을 돌아본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"수상한 흔적\",\"text\":\"비명이 들린 방 근처 바닥에서 반짝이는 가루와 누군가 끌려간 듯한 자국이 발견된다. 하루는 가루를 손끝에 묻혀 냄새를 맡고는 소울 에너지의 잔향임을 알아챈다. 귀신이 아니라 누군가의 소행일 가능성이 커졌다. 안도한 듯하면서도 더 위험할 수 있다는 걸 깨닫고 하루가 입술을 깨문다. 가루는 어둠 속에서 작은 별처럼 반짝이며 지하로 이어지는 계단까지 점점이 이어져 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"남은 자국을 따라 지하로 내려간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_2\",\"text\":\"하루에게 판단을 맡긴다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"위험하니 증거만 챙기고 철수하자고 한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"하루의 결정\",\"text\":\"당신이 판단을 묻자 하루는 잠시 눈을 감고 호흡을 고른다. 이윽고 눈을 뜬 그녀의 표정은 한결 단호하다. \\\"지하로 내려가요. 제가 앞에 서겠습니다.\\\" 겁 많은 하루가 리더로서 앞장서는 순간, 당신은 그 뒷모습에서 믿음직함을 느낀다. 그녀의 손은 여전히 조금 떨리고 있다. 지하로 이어지는 계단은 어둠에 잠겨 바닥이 보이지 않는다. 두 사람은 한 걸음씩 신중히 내딛는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"지하의 정체\",\"text\":\"지하실에서 발견된 것은 소울정크 변이체를 몰래 연구하던 네드 컴퍼니의 낡은 장비와, 스피커로 틀어 놓은 비명 녹음이었다. 괴담은 누군가 사람들을 쫓아내려 만든 가짜였던 것. 하루는 어이없다는 듯 웃다가 곧 분노로 눈빛이 서늘해진다. 갑자기 어둠 속에서 경비 변이체가 모습을 드러낸다. 천장에 매달린 형광등이 깜빡이며 기계 사이로 괴이한 그림자를 만들어 낸다. 하루는 검자루를 쥐고 당신 앞에 선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"증거를 사진으로 남기고 장비를 회수한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"용기\",\"op\":\"add\",\"value\":0}]},{\"id\":\"o10_2\",\"text\":\"남은 변이체가 없는지 건물을 한 번 더 수색한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"일단 빨리 나가자고 하루의 손을 잡는다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":0},{\"var\":\"용기\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"마지막 수색\",\"text\":\"두 사람은 지하실의 다른 방들을 하나하나 확인한다. 하루는 문을 열 때마다 심호흡을 하지만 이제는 손이 덜 떨린다. 마지막 방에서 쓰러져 있던 경비원을 발견해 응급 처치를 하고 안전한 곳으로 옮긴다. 하루는 \\\"사람이었다니 다행이에요\\\"라며 한숨을 내쉰다. 의사 지망생의 손길이 능숙하게 움직인다. 지하실의 공기는 차갑고 습해서 두 사람의 숨소리까지 선명하게 들린다. 하루는 조용히 문틈의 불빛을 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"새벽의 보고서\",\"text\":\"폐병원을 나온 두 사람은 별숲리그 지부에서 조사 결과를 정리한다. 하루는 졸린 눈을 비비며 보고서를 쓰다가 문득 오늘 밤 일을 떠올리며 작게 웃는다. 겁이 났던 순간과 용기를 냈던 순간이 한꺼번에 스친다. 당신이 곁에서 커피를 건네자 하루는 두 손으로 받아 들고 \\\"고맙습니다\\\"라고 말한다. 창밖에서는 새소리가 들리기 시작한다. 보고서 말미에는 하루의 단정한 글씨로 협력자에 대한 감사의 말이 적힌다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"비명의 끝\",\"text\":\"변이체를 물리치고 나자 폐병원에는 다시 고요가 찾아온다. 하루는 검을 거두고 맥이 풀린 듯 주저앉아 \\\"귀신이 아니라서 다행이에요…\\\"라고 중얼거린다. 그리고 곧 당신을 돌아보며 부끄러운 듯 웃는다. 증거를 정리해 별숲리그에 보고할 시간이다. 창밖으로 새벽빛이 스며들며 폐병원의 음산한 기운이 한결 옅어진다. 하루는 가슴을 쓸어내리며 다시는 이런 조사는 사양이라는 듯 작게 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":5,\"max\":null},{\"var\":\"용기\",\"min\":3,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"진실을 밝힌 밤\",\"text\":\"단서를 꼼꼼히 모으고 용기도 잃지 않은 덕분에 네드 컴퍼니의 은닉 시설 증거를 확보했다. 하루는 보고서를 쓰며 \\\"제가 이렇게 해낼 수 있을 줄은 몰랐어요\\\"라며 놀라워한다. 그리고 당신 덕분이라며 환하게 웃는다. 이제 귀신 이야기는 더 이상 무섭지 않을 것 같다며… 아마도. 돌아오는 길, 하루는 폐병원이 보이지 않게 될 때까지 몇 번이나 뒤를 돌아본다. 당신이 웃으며 괜찮다고 하자 그녀는 \\\"그, 그래도 무서운 건 무서워요\\\"라며 슬쩍 당신 곁으로 붙는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"절반의 진실\",\"text\":\"괴담의 정체는 밝혔지만 증거가 충분하지 않아 네드 컴퍼니까지 추궁하지는 못했다. 하루는 아쉬워하면서도 안전하게 돌아온 것에 안도한다. 돌아오는 길에는 당신 옆에 바짝 붙어 걸으며 자꾸 뒤를 돌아본다. 새벽 하늘이 밝아 오는 가운데 별숲리그에 올릴 보고서를 정리하는 하루의 손이 분주하다. 그녀는 당신과 함께 부족했던 부분을 되짚으며 다음 조사를 위한 점검표를 만든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"무서웠던 기억\",\"text\":\"하루는 겁에 질려 제대로 조사를 하지 못한 채 병원을 빠져나왔다. 단서는 거의 없고, 그녀는 한동안 어둠 속에서 들리던 소리를 잊지 못한다. \\\"다음에는 꼭 제대로 할게요…\\\" 하며 풀 죽은 목소리로 말하는 하루를 당신이 다독인다. 폐병원이 보이지 않는 곳까지 와서야 하루는 겨우 숨을 돌린다. 한동안은 복도의 삐걱거림만 들어도 움찔하게 될 것 같다며 어색하게 웃는다. 당신은 따뜻한 차 한 잔을 권하며 곁을 지킨다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '한밤의 폐병원: 비명 소리의 정체'
);

-- 04. [하루 에스티아] 흐릿한 노래, 어머니의 부엌
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '흐릿한 노래, 어머니의 부엌', 'published', 0, '{\"vars\":[{\"name\":\"공감\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"낡은 오르골\",\"text\":\"아르카디아 렐름의 한적한 정원 벤치. 하루 에스티아는 작은 오르골을 손에 쥐고 멍하니 앉아 있다. 공백에서 돌아온 뒤 찾아낸 어머니의 유품이다. 멜로디가 귀에 익지만 어머니의 얼굴은 안개처럼 흐릿하다. 당신이 다가오자 하루는 조심스럽게 오르골을 내밀며 \\\"이 노래, 아세요?\\\"라고 묻는다. 쓸쓸한 미소가 조용히 번진다. 해질녘의 정원에는 바람이 풀잎을 스치는 소리만이 가만히 흐르고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"모른다고 솔직히 말하고 곁에 앉는다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"함께 멜로디를 따라 불러 본다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_3\",\"text\":\"기억이 안 나면 억지로 떠올리지 말라고 한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"엇갈리는 허밍\",\"text\":\"당신이 서툰 허밍으로 멜로디를 따라 하자 하루가 놀란 눈으로 바라본다. 이내 그녀도 작게 따라 부르기 시작하고, 어느 순간 눈가가 촉촉해진다. \\\"어머니가 부엌에서 이런 노래를 흥얼거렸던 것 같아요.\\\" 기억의 조각 하나가 떠오른 듯 하루는 숨을 삼키고, 당신은 방해하지 않으려 조용히 곁을 지킨다. 오르골의 태엽이 풀리며 멜로디가 느려질수록 두 사람의 허밍이 하나로 겹쳐진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"기억의 조각\",\"text\":\"하루의 마음속에는 어머니를 잃은 괴로운 기억을 대신 간직한 내면의 \\\"그 아이\\\"가 있다. 그래서 본인의 기억은 흐릿하다. 하루는 그 사실을 담담하게 이야기하면서도 가끔 말이 끊긴다. 자신이 어머니를 제대로 기억하지 못하는 것이 불효처럼 느껴져 마음이 아프다고 털어놓는다. 당신은 조용히 이야기를 듣는 자리에 있다. 하루는 오르골 뚜껑을 열었다 닫기를 반복하며 시선을 먼 곳에 둔다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"정원에 번지는 저녁\",\"text\":\"벤치에 앉아 있던 하루는 해가 기울자 오르골을 무릎 위에 올려놓고 한참 말이 없다. 정원에는 렐름의 가로등이 하나둘 켜지고, 꽃향기가 바람에 실려 온다. 하루는 당신에게 \\\"이상하죠, 이런 평화로운 곳에서는 더 외로워져요\\\"라고 작게 고백한다. 곁에서 듣는 당신의 존재가 그녀에게 작은 위로가 되고 있다. 하루의 목소리는 조용하고 부드럽다. 당신은 조용히 고개를 끄덕이며 그녀의 이야기가 끝날 때까지 기다린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"어머니의 레시피\",\"text\":\"하루는 어머니가 자주 해 주셨던 고기 수프가 떠오른다고 말한다. 재료도 맛도 흐릿하지만 따뜻하고 포근한 느낌만은 선명하다고. 하루의 눈에 기대와 두려움이 함께 비친다. 직접 만들어 보면 기억이 더 돌아올지도 모른다는 생각에 그녀는 조심스럽게 당신의 의견을 구한다. 주머니에서 낡은 레시피 쪽지를 꺼내 들지만 글자는 반쯤 번져 읽을 수가 없다. 하루는 쪽지를 접어 주머니에 넣고 당신을 보며 도와 달라고 청한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"같이 만들어 보자고 제안한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"기억이 안 나도 괜찮다고 위로한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"기억을 되찾는 게 정말 필요한지 묻는다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"부엌의 두 사람\",\"text\":\"렐름의 공용 부엌에서 하루가 앞치마를 두르고 칼을 든다. 서툰 손놀림이지만 양파를 썰 때 문득 \\\"이렇게 하라고 하셨던 것 같아요\\\"라며 손이 먼저 기억을 따라간다. 당신이 곁에서 불을 맡으며 분위기가 따뜻해진다. 수프 냄새가 퍼지자 하루는 코끝이 시큰해져 고개를 돌린다. 창문으로 오후의 햇살이 스며들어 하얀 김과 함께 부드럽게 일렁인다. 칼질 소리와 끓는 소리가 이어지며 부엌은 천천히 온기로 채워진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"그 아이의 목소리\",\"text\":\"수프가 끓는 동안 하루의 표정이 잠시 멍해진다. 마음 깊은 곳의 \\\"그 아이\\\"가 말을 건 듯, 그녀는 가슴을 부여잡고 숨을 고른다. 괴로운 기억이 스며들 것 같은 두려움에 떨지만 하루는 도망치지 않으려 한다. 당신 앞에서 약한 모습을 보이는 것이 부끄러운 듯하면서도 손은 당신의 소매를 놓지 않는다. 부엌의 소음이 멀어지고 냄비 끓는 소리만이 아득하게 들려온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"손을 꼭 잡고 곁에 있겠다고 말한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"무리하지 말고 잠시 쉬자고 한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"끝까지 기억해 보자고 격려한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"너무 이른 격려\",\"text\":\"당신의 말에 하루가 잠시 숨을 몰아쉰다. 기억의 문을 억지로 열려는 듯 눈을 질끈 감지만 얼굴이 창백해진다. 이내 \\\"괜찮아요…\\\"라며 웃어 보이지만 그 웃음이 위태롭다. 당신이 서둘러 그녀를 의자에 앉히자 하루는 천천히 호흡을 되찾으며 미안하다고 사과한다. 하루는 이마에 맺힌 땀을 닦으며 짧게 호흡을 고르고, 오르골을 가슴에 안는다. 하루는 곧 평소의 부드러운 표정으로 돌아와 당신을 안심시키려 애쓴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"식탁 위의 수프\",\"text\":\"완성된 수프가 식탁에 놓인다. 하루는 한 숟갈을 떠 입에 가져가고, 잠시 눈을 감는다. 맛이 어머니의 것과 같은지는 확신할 수 없지만 따뜻함만큼은 같다고 느낀다. 하루의 눈에서 눈물이 한 방울 흘러내리고, 그녀는 얼른 소매로 닦으며 헤헤 하고 웃는다. 김이 서린 창밖으로 렐름의 등불이 하나씩 켜진다. 두 사람 사이의 침묵이 오히려 편안하게 느껴진다. 당신도 한 숟갈 맛을 보며 따뜻하다고 말하자 하루가 고개를 끄덕인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"어머니는 분명 하루를 자랑스러워할 거라고 말한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"다음에 또 같이 요리하자고 약속한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"이제 늦었으니 쉬자고 한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":60,\"type\":\"story\",\"title\":\"젖은 웃음\",\"text\":\"하루는 놀란 듯 눈을 깜빡이다가 이내 눈물을 닦으며 웃는다. \\\"그렇게 말해 주시니까… 정말 그럴 것 같아요.\\\" 그녀의 목소리가 조금 떨린다. 아직 어머니의 얼굴은 떠오르지 않지만 그 말만은 마음 깊이 스며든다. 당신은 조용히 손수건을 건넨다. 밤공기가 한결 따뜻하게 느껴진다. 정원의 가로등이 켜지고 하루의 눈동자에 작은 불빛이 반짝인다. 그녀는 오르골을 두 손으로 소중히 감싼다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"오르골의 마지막 음\",\"text\":\"식사를 마친 하루는 오르골의 태엽을 한 번 더 감는다. 멜로디가 천천히 흐르다 마지막 음에서 멈추자, 그녀는 한동안 그 여운 속에 머문다. 어머니의 얼굴은 여전히 흐릿하지만 노래가 전해 주던 온기만은 분명하다. 하루는 조용히 오르골을 닫고 당신을 올려다보며 작게 미소 짓는다. 창밖 별빛이 부드럽게 일렁인다. 당신은 아무 말 없이 곁에 앉아 그 고요를 함께 나눈다. 바람이 부드럽게 둘 사이를 지나간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"어머니께 보내는 인사\",\"text\":\"식사 후 하루는 오르골의 태엽을 감으며 창밖의 별빛을 올려다본다. 어머니를 완전히 기억하지 못해도 사랑받았다는 사실만은 분명하다고, 당신에게 천천히 말한다. 복수가 아닌 수호를 위해 싸우겠다는 결심을 다시 한 번 마음에 새기는 하루. 오르골 소리가 조용한 밤에 흩어진다. 하루는 조용히 눈을 감고 어머니께 마음속으로 인사를 건넨다. 당신은 그 곁에서 방해하지 않으려 숨을 죽인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"공감\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"공감\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"어머니의 노래가 닿는 곳\",\"text\":\"하루는 어머니의 흐릿한 얼굴 대신 따스한 목소리를 마음속에서 되찾는다. 당신 덕분에 혼자가 아니라는 걸 알게 되었다며, 처음으로 환하게 웃는다. 오르골 멜로디가 한결 선명하게 울리고, 하루는 \\\"다음에 또 같이 수프를 끓여요\\\"라고 속삭인다. 창밖의 별들이 오르골의 선율에 맞춰 반짝이는 듯하다. 하루는 한결 가벼워진 표정으로 오르골을 품에 안고, 당신에게 오래도록 눈빛으로 감사를 전한다. 고요한 밤이 부드럽게 깊어진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"조금 더 가까워진 밤\",\"text\":\"기억은 여전히 흐릿하지만 하루의 마음은 한결 가벼워졌다. 그녀는 당신에게 고맙다는 말을 몇 번이나 되풀이하고, 오르골을 소중히 품에 안은 채 잠시 눈을 감는다. 하루는 오르골을 침대맡에 두고 불을 끄기 전, 당신에게 편히 쉬라는 인사를 건넨다. 마음속에 작은 등불 하나가 켜진 듯한 밤이다. 내일은 조금 더 어머니를 떠올릴 수 있을지도 모른다. 하루는 끝으로 당신에게 한 번 더 가볍게 인사하고 오르골의 선율을 되새기며 천천히 걸어간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"닫혀 있는 오르골\",\"text\":\"하루는 괜찮은 척 웃지만 어딘가 거리가 느껴진다. 오르골을 조용히 닫고 \\\"오늘은 이만 쉴게요\\\"라며 자리를 뜬다. 마음의 문은 아직 열리지 않았지만, 언젠가 다시 이야기할 수 있기를 바라는 눈빛이 남아 있다. 하루가 떠난 정원에는 오르골의 마지막 여음만이 희미하게 남는다. 당신은 벤치에 남아 그 선율을 오래도록 들으며 다음에는 더 좋은 말을 건넬 수 있기를 바란다. 밤바람이 조용히 스친다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"공감\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"낡은 오르골\",\"text\":\"아르카디아 렐름의 한적한 정원 벤치. 하루 에스티아는 작은 오르골을 손에 쥐고 멍하니 앉아 있다. 공백에서 돌아온 뒤 찾아낸 어머니의 유품이다. 멜로디가 귀에 익지만 어머니의 얼굴은 안개처럼 흐릿하다. 당신이 다가오자 하루는 조심스럽게 오르골을 내밀며 \\\"이 노래, 아세요?\\\"라고 묻는다. 쓸쓸한 미소가 조용히 번진다. 해질녘의 정원에는 바람이 풀잎을 스치는 소리만이 가만히 흐르고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"모른다고 솔직히 말하고 곁에 앉는다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_2\",\"text\":\"함께 멜로디를 따라 불러 본다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_3\",\"text\":\"기억이 안 나면 억지로 떠올리지 말라고 한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"엇갈리는 허밍\",\"text\":\"당신이 서툰 허밍으로 멜로디를 따라 하자 하루가 놀란 눈으로 바라본다. 이내 그녀도 작게 따라 부르기 시작하고, 어느 순간 눈가가 촉촉해진다. \\\"어머니가 부엌에서 이런 노래를 흥얼거렸던 것 같아요.\\\" 기억의 조각 하나가 떠오른 듯 하루는 숨을 삼키고, 당신은 방해하지 않으려 조용히 곁을 지킨다. 오르골의 태엽이 풀리며 멜로디가 느려질수록 두 사람의 허밍이 하나로 겹쳐진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"기억의 조각\",\"text\":\"하루의 마음속에는 어머니를 잃은 괴로운 기억을 대신 간직한 내면의 \\\"그 아이\\\"가 있다. 그래서 본인의 기억은 흐릿하다. 하루는 그 사실을 담담하게 이야기하면서도 가끔 말이 끊긴다. 자신이 어머니를 제대로 기억하지 못하는 것이 불효처럼 느껴져 마음이 아프다고 털어놓는다. 당신은 조용히 이야기를 듣는 자리에 있다. 하루는 오르골 뚜껑을 열었다 닫기를 반복하며 시선을 먼 곳에 둔다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"정원에 번지는 저녁\",\"text\":\"벤치에 앉아 있던 하루는 해가 기울자 오르골을 무릎 위에 올려놓고 한참 말이 없다. 정원에는 렐름의 가로등이 하나둘 켜지고, 꽃향기가 바람에 실려 온다. 하루는 당신에게 \\\"이상하죠, 이런 평화로운 곳에서는 더 외로워져요\\\"라고 작게 고백한다. 곁에서 듣는 당신의 존재가 그녀에게 작은 위로가 되고 있다. 하루의 목소리는 조용하고 부드럽다. 당신은 조용히 고개를 끄덕이며 그녀의 이야기가 끝날 때까지 기다린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"어머니의 레시피\",\"text\":\"하루는 어머니가 자주 해 주셨던 고기 수프가 떠오른다고 말한다. 재료도 맛도 흐릿하지만 따뜻하고 포근한 느낌만은 선명하다고. 하루의 눈에 기대와 두려움이 함께 비친다. 직접 만들어 보면 기억이 더 돌아올지도 모른다는 생각에 그녀는 조심스럽게 당신의 의견을 구한다. 주머니에서 낡은 레시피 쪽지를 꺼내 들지만 글자는 반쯤 번져 읽을 수가 없다. 하루는 쪽지를 접어 주머니에 넣고 당신을 보며 도와 달라고 청한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"같이 만들어 보자고 제안한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"기억이 안 나도 괜찮다고 위로한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"기억을 되찾는 게 정말 필요한지 묻는다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"부엌의 두 사람\",\"text\":\"렐름의 공용 부엌에서 하루가 앞치마를 두르고 칼을 든다. 서툰 손놀림이지만 양파를 썰 때 문득 \\\"이렇게 하라고 하셨던 것 같아요\\\"라며 손이 먼저 기억을 따라간다. 당신이 곁에서 불을 맡으며 분위기가 따뜻해진다. 수프 냄새가 퍼지자 하루는 코끝이 시큰해져 고개를 돌린다. 창문으로 오후의 햇살이 스며들어 하얀 김과 함께 부드럽게 일렁인다. 칼질 소리와 끓는 소리가 이어지며 부엌은 천천히 온기로 채워진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"그 아이의 목소리\",\"text\":\"수프가 끓는 동안 하루의 표정이 잠시 멍해진다. 마음 깊은 곳의 \\\"그 아이\\\"가 말을 건 듯, 그녀는 가슴을 부여잡고 숨을 고른다. 괴로운 기억이 스며들 것 같은 두려움에 떨지만 하루는 도망치지 않으려 한다. 당신 앞에서 약한 모습을 보이는 것이 부끄러운 듯하면서도 손은 당신의 소매를 놓지 않는다. 부엌의 소음이 멀어지고 냄비 끓는 소리만이 아득하게 들려온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"손을 꼭 잡고 곁에 있겠다고 말한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"무리하지 말고 잠시 쉬자고 한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"끝까지 기억해 보자고 격려한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"너무 이른 격려\",\"text\":\"당신의 말에 하루가 잠시 숨을 몰아쉰다. 기억의 문을 억지로 열려는 듯 눈을 질끈 감지만 얼굴이 창백해진다. 이내 \\\"괜찮아요…\\\"라며 웃어 보이지만 그 웃음이 위태롭다. 당신이 서둘러 그녀를 의자에 앉히자 하루는 천천히 호흡을 되찾으며 미안하다고 사과한다. 하루는 이마에 맺힌 땀을 닦으며 짧게 호흡을 고르고, 오르골을 가슴에 안는다. 하루는 곧 평소의 부드러운 표정으로 돌아와 당신을 안심시키려 애쓴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"식탁 위의 수프\",\"text\":\"완성된 수프가 식탁에 놓인다. 하루는 한 숟갈을 떠 입에 가져가고, 잠시 눈을 감는다. 맛이 어머니의 것과 같은지는 확신할 수 없지만 따뜻함만큼은 같다고 느낀다. 하루의 눈에서 눈물이 한 방울 흘러내리고, 그녀는 얼른 소매로 닦으며 헤헤 하고 웃는다. 김이 서린 창밖으로 렐름의 등불이 하나씩 켜진다. 두 사람 사이의 침묵이 오히려 편안하게 느껴진다. 당신도 한 숟갈 맛을 보며 따뜻하다고 말하자 하루가 고개를 끄덕인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"어머니는 분명 하루를 자랑스러워할 거라고 말한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"다음에 또 같이 요리하자고 약속한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"이제 늦었으니 쉬자고 한다\",\"varOps\":[{\"var\":\"공감\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":60,\"type\":\"story\",\"title\":\"젖은 웃음\",\"text\":\"하루는 놀란 듯 눈을 깜빡이다가 이내 눈물을 닦으며 웃는다. \\\"그렇게 말해 주시니까… 정말 그럴 것 같아요.\\\" 그녀의 목소리가 조금 떨린다. 아직 어머니의 얼굴은 떠오르지 않지만 그 말만은 마음 깊이 스며든다. 당신은 조용히 손수건을 건넨다. 밤공기가 한결 따뜻하게 느껴진다. 정원의 가로등이 켜지고 하루의 눈동자에 작은 불빛이 반짝인다. 그녀는 오르골을 두 손으로 소중히 감싼다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"오르골의 마지막 음\",\"text\":\"식사를 마친 하루는 오르골의 태엽을 한 번 더 감는다. 멜로디가 천천히 흐르다 마지막 음에서 멈추자, 그녀는 한동안 그 여운 속에 머문다. 어머니의 얼굴은 여전히 흐릿하지만 노래가 전해 주던 온기만은 분명하다. 하루는 조용히 오르골을 닫고 당신을 올려다보며 작게 미소 짓는다. 창밖 별빛이 부드럽게 일렁인다. 당신은 아무 말 없이 곁에 앉아 그 고요를 함께 나눈다. 바람이 부드럽게 둘 사이를 지나간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"어머니께 보내는 인사\",\"text\":\"식사 후 하루는 오르골의 태엽을 감으며 창밖의 별빛을 올려다본다. 어머니를 완전히 기억하지 못해도 사랑받았다는 사실만은 분명하다고, 당신에게 천천히 말한다. 복수가 아닌 수호를 위해 싸우겠다는 결심을 다시 한 번 마음에 새기는 하루. 오르골 소리가 조용한 밤에 흩어진다. 하루는 조용히 눈을 감고 어머니께 마음속으로 인사를 건넨다. 당신은 그 곁에서 방해하지 않으려 숨을 죽인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"공감\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"공감\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"어머니의 노래가 닿는 곳\",\"text\":\"하루는 어머니의 흐릿한 얼굴 대신 따스한 목소리를 마음속에서 되찾는다. 당신 덕분에 혼자가 아니라는 걸 알게 되었다며, 처음으로 환하게 웃는다. 오르골 멜로디가 한결 선명하게 울리고, 하루는 \\\"다음에 또 같이 수프를 끓여요\\\"라고 속삭인다. 창밖의 별들이 오르골의 선율에 맞춰 반짝이는 듯하다. 하루는 한결 가벼워진 표정으로 오르골을 품에 안고, 당신에게 오래도록 눈빛으로 감사를 전한다. 고요한 밤이 부드럽게 깊어진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"조금 더 가까워진 밤\",\"text\":\"기억은 여전히 흐릿하지만 하루의 마음은 한결 가벼워졌다. 그녀는 당신에게 고맙다는 말을 몇 번이나 되풀이하고, 오르골을 소중히 품에 안은 채 잠시 눈을 감는다. 하루는 오르골을 침대맡에 두고 불을 끄기 전, 당신에게 편히 쉬라는 인사를 건넨다. 마음속에 작은 등불 하나가 켜진 듯한 밤이다. 내일은 조금 더 어머니를 떠올릴 수 있을지도 모른다. 하루는 끝으로 당신에게 한 번 더 가볍게 인사하고 오르골의 선율을 되새기며 천천히 걸어간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"닫혀 있는 오르골\",\"text\":\"하루는 괜찮은 척 웃지만 어딘가 거리가 느껴진다. 오르골을 조용히 닫고 \\\"오늘은 이만 쉴게요\\\"라며 자리를 뜬다. 마음의 문은 아직 열리지 않았지만, 언젠가 다시 이야기할 수 있기를 바라는 눈빛이 남아 있다. 하루가 떠난 정원에는 오르골의 마지막 여음만이 희미하게 남는다. 당신은 벤치에 남아 그 선율을 오래도록 들으며 다음에는 더 좋은 말을 건넬 수 있기를 바란다. 밤바람이 조용히 스친다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '흐릿한 노래, 어머니의 부엌'
);

-- 05. [하루 에스티아] 별빛 가득한 렐름 축제의 밤
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '별빛 가득한 렐름 축제의 밤', 'published', 0, '{\"vars\":[{\"name\":\"축제흥\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"축제 전야의 광장\",\"text\":\"비스타 토벌의 승리를 기념해 아르카디아 렐름에서 작은 축제가 열린다. 광장에는 등불과 노점이 늘어서 있고, 하루 에스티아는 평소와 달리 가벼운 사복 차림으로 서 있다. 이런 자리가 어색해 쭈뼛거리지만 눈은 빵과 고기 꼬치 노점을 향해 반짝인다. 당신은 하루와 함께 축제를 즐기기로 약속한 동행자다. 등불의 따뜻한 빛이 골목마다 번지며 사람들의 웃음소리가 한데 어우러진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"고기 꼬치 노점으로 먼저 간다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_2\",\"text\":\"분위기를 둘러보며 천천히 걷는다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_3\",\"text\":\"사람이 많으니 조용한 곳으로 가자고 한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":60,\"type\":\"story\",\"title\":\"고기 꼬치 한 입\",\"text\":\"노릇하게 구워진 꼬치를 받아 든 하루가 행복한 표정으로 한 입을 베어 문다. 평소의 진중함은 간데없이 눈이 동그래진다. 그러다 당신이 보고 있다는 걸 깨닫고 얼굴을 붉히며 \\\"그, 그냥 배가 고파서요\\\"라고 변명한다. 소스가 입가에 묻은 것도 모른 채다. 구수한 고기 냄새가 퍼져 근처 노점 주인도 흐뭇하게 두 사람을 바라본다. 하루는 당신의 시선을 피해 얼른 입가를 닦는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"사격 노점의 도전\",\"text\":\"광장 한켠의 사격 노점에서 인형을 걸고 도전하는 사람들이 몰려 있다. 큰 곰 인형이 하루의 시선을 끌지만 그녀는 쉽사리 말을 꺼내지 못한다. 대검 사용자라 사격은 서툴다며 소심하게 중얼거리는 모습이 귀엽다. 당신은 그녀의 시선을 눈치채고 말을 걸 수 있다. 노점 주인은 곰 인형 앞에서 머뭇거리는 하루를 눈치채고 슬쩍 눈짓을 보낸다. 하루는 못 본 척 고개를 돌리지만 귀 끝이 빨개져 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"빵집 앞의 줄\",\"text\":\"광장 모퉁이에 갓 구운 빵을 파는 가게가 있고, 긴 줄이 늘어서 있다. 하루는 줄 끝에 서서 코를 킁킁거리며 향기를 들이마신다. 빵 종류가 너무 많아서 무엇을 고를지 진지하게 고민하는 모습이 귀엽다. 당신이 하나 사 주겠다고 하자 하루는 어쩔 줄 몰라 하면서도 눈은 이미 가장 큰 빵을 향한다. 줄이 줄어들며 따뜻한 향이 더욱 짙어진다. 줄이 줄어드는 사이 하루는 군침을 삼키며 당신과 소소한 이야기를 나눈다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"북적이는 사람들\",\"text\":\"축제는 점점 무르익고 사람들이 광장으로 몰려든다. 하루는 인파에 밀려 당신과 떨어질 뻔하다 소매를 붙든다. 평소 많은 사람 앞에서 지휘하던 그녀지만 이런 소란스러움은 낯설고 당황스러운 듯하다. 근처에서 별숲리그 동료들이 하루를 알아보고 손을 흔든다. 어디선가 악단의 연주가 시작되고 사람들이 박수를 치며 흥겹게 몸을 흔든다. 하루는 그 한가운데서 어쩔 줄 몰라 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"사격 노점에 도전해 곰 인형을 노린다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"하루가 직접 해 보도록 권한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_3\",\"text\":\"다른 노점으로 향한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"빗나간 한 발\",\"text\":\"당신의 첫 발이 허공으로 날아가자 하루가 작게 웃음을 터뜨린다. 곧 미안한 듯 입을 가리지만 어깨가 들썩인다. 두 번째 발은 가까스로 인형 귀퉁이를 스치고, 하루가 응원하는 목소리를 높인다. 점점 승부욕이 붙은 두 사람 사이로 웃음이 번진다. 노점 주인은 두 사람의 승부를 구경하며 인형 하나를 더 걸어 주겠다고 장난스럽게 말한다. 하루는 손뼉을 치며 \\\"한 번 더요!\\\"라고 외치고, 평소와 다른 모습에 당신도 웃음이 난다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"등불 띄우기\",\"text\":\"해가 지자 광장 한가운데서 소원 등불을 띄우는 행사가 시작된다. 하루는 등불에 소원을 적으며 오랫동안 펜을 멈춘다. 지키고 싶은 사람들, 아직 흐릿한 어머니의 기억, 토마스와 빅터에 대한 걱정이 마음을 스친다. 당신에게는 어떤 소원을 적었는지 묻는 듯한 눈빛을 보낸다. 수백 개의 등불이 밤하늘로 천천히 오르기 시작하자 광장이 환상적인 빛으로 물든다. 등불 속 촛불이 하루의 표정을 따스하게 비춘다. 당신은 곁에서 조용히 자신의 등불을 쥐고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"모두의 평화를 빈다고 말한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_2\",\"text\":\"하루의 소원이 이루어지길 빈다고 말한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_3\",\"text\":\"소원은 비밀이라고 장난스럽게 답한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"작은 소원\",\"text\":\"하루가 놀란 듯 눈을 크게 뜨더니 이내 얼굴이 붉어진다. \\\"저, 저를요…?\\\" 하며 손끝으로 등불 종이를 만지작거린다. 잠시 후 부끄러운 미소와 함께 \\\"그럼 저도 당신의 소원을 빌게요\\\"라고 작게 속삭인다. 등불이 하늘로 천천히 떠오르며 두 사람의 얼굴을 따뜻하게 비춘다. 하루가 쓴 소원은 접힌 종이 속에 감추어져 당신에게는 보이지 않는다. 다만 종이를 접는 그녀의 손끝에서 따뜻한 마음이 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"불꽃놀이\",\"text\":\"밤하늘에 불꽃이 쏘아 올려진다. 하루는 한순간 놀라 어깨를 움츠리지만 이내 환하게 올려다본다. 불꽃의 빛이 그녀의 얼굴 위로 물결치고, 평화로운 일상이야말로 자신이 지키고 싶은 것임을 새삼 느낀다. 하루는 당신 곁에서 조용히 불꽃을 본다. 쾅 하는 소리가 울릴 때마다 하루의 어깨가 작게 움찔하지만 곧 작게 웃으며 하늘을 올려다본다. 불꽃이 비치는 그녀의 눈동자에 별이 가득하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"손을 잡고 인파를 헤쳐 나간다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"동료들과 합류해 함께 즐긴다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"지쳤으니 숙소로 일찍 돌아가자고 한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":60,\"type\":\"story\",\"title\":\"손끝의 온기\",\"text\":\"인파가 늘어난 광장에서 당신이 하루의 손을 가볍게 잡아 이끈다. 하루는 깜짝 놀라 어깨를 떨지만 곧 고개를 숙인 채 조용히 따라온다. 귀 끝이 불그레하게 물들어 있다. 손을 놓는 순간 서로 어색하게 웃고, 하루는 \\\"죄, 죄송해요, 아니 고마워요\\\"라며 말을 더듬는다. 광장의 불빛이 두 사람 위로 따스하게 내려앉는다. 하루는 손바닥에 남은 온기를 느끼며 잠시 시선을 먼 곳으로 돌린다. 이내 고개를 흔들고 환하게 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"옥상에서 본 광장\",\"text\":\"축제의 마지막 불빛이 사그라드는 시간, 하루와 당신은 숙소 옥상에 올라가 광장을 내려다본다. 조금 전까지 북적이던 거리가 고요하고 따뜻하게 가라앉아 있다. 하루는 난간에 기대어 \\\"평화로운 일상이 이렇게 소중한 건지 몰랐어요\\\"라고 말한다. 바람이 불어와 머리카락이 흩날리고, 그녀는 조용히 눈을 감는다. 당신은 곁에서 고개를 끄덕이며 그녀의 말을 곱씹고, 먼 하늘에는 마지막 불꽃이 반짝인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"축제의 끝자락\",\"text\":\"인파가 흩어지고 등불이 하나둘 꺼진다. 하루는 아쉬운 듯 광장을 한 번 더 둘러보다 당신 앞에 선다. 오늘 하루가 얼마나 즐거웠는지 말하려다 쑥스러워 말끝을 흐린다. 렐름의 밤바람이 불어오는 가운데 둘은 천천히 숙소를 향해 걸음을 옮긴다. 바닥에는 꺼진 불꽃의 잔해와 웃음의 흔적이 남아 있다. 하루는 곰 인형이든 아니든 오늘 얻은 모든 것을 소중히 안고 걸어간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"축제흥\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"축제흥\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"가장 반짝인 밤\",\"text\":\"하루는 오늘의 축제를 평생 잊지 못할 것이라며 쑥스럽게 웃는다. 손에는 곰 인형과 빈 꼬치 막대가 쥐어져 있다. 당신에게 \\\"다음 축제도 같이 와 주세요\\\"라고 작게 속삭이는 목소리에 별빛이 닿는다. 숙소 앞에서 하루는 작별 인사를 하다 말고 한 번 더 광장 쪽을 바라본다. 밤하늘에는 아직 떠 있는 등불이 하나둘 보이고, 둘의 그림자가 나란히 길게 이어진다. 평화로운 일상의 소중함이 마음 깊이 남는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"은은한 여운\",\"text\":\"화려하진 않았지만 평온한 축제였다. 하루는 가볍게 인사를 건네고 숙소로 향하며, 오늘 같은 날이 자주 있었으면 좋겠다고 혼잣말처럼 중얼거린다. 하루는 숙소 문 앞에서 작은 손짓으로 인사를 하고는 조용히 들어간다. 광장의 마지막 등불이 꺼질 때까지 당신은 잠시 서서 오늘의 소리와 빛을 마음속에 새긴다. 소박해서 더 따뜻한 밤이다. 하루는 헤헤 하고 웃으며 인사한 뒤 문을 닫는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"조용히 지나간 밤\",\"text\":\"축제는 어느새 끝나 있었다. 하루는 조금 아쉬운 표정이지만 억지로 웃으며 \\\"다음에는 더 즐겨 봐요\\\"라고 말한다. 당신은 그녀의 아쉬움을 달래 줄 방법을 곰곰이 생각한다. 하루는 숙소 앞에서 조용히 인사를 건네고 돌아선다. 등을 보이며 걷는 그녀의 걸음이 평소보다 조금 느리다. 당신은 내일 다시 함께 거닐 수 있을지 생각하며 광장의 마지막 불빛을 바라본다. 하루는 숙소 문 앞에서 한 번 더 뒤를 돌아본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"축제흥\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"축제 전야의 광장\",\"text\":\"비스타 토벌의 승리를 기념해 아르카디아 렐름에서 작은 축제가 열린다. 광장에는 등불과 노점이 늘어서 있고, 하루 에스티아는 평소와 달리 가벼운 사복 차림으로 서 있다. 이런 자리가 어색해 쭈뼛거리지만 눈은 빵과 고기 꼬치 노점을 향해 반짝인다. 당신은 하루와 함께 축제를 즐기기로 약속한 동행자다. 등불의 따뜻한 빛이 골목마다 번지며 사람들의 웃음소리가 한데 어우러진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"고기 꼬치 노점으로 먼저 간다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_2\",\"text\":\"분위기를 둘러보며 천천히 걷는다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_3\",\"text\":\"사람이 많으니 조용한 곳으로 가자고 한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":60,\"type\":\"story\",\"title\":\"고기 꼬치 한 입\",\"text\":\"노릇하게 구워진 꼬치를 받아 든 하루가 행복한 표정으로 한 입을 베어 문다. 평소의 진중함은 간데없이 눈이 동그래진다. 그러다 당신이 보고 있다는 걸 깨닫고 얼굴을 붉히며 \\\"그, 그냥 배가 고파서요\\\"라고 변명한다. 소스가 입가에 묻은 것도 모른 채다. 구수한 고기 냄새가 퍼져 근처 노점 주인도 흐뭇하게 두 사람을 바라본다. 하루는 당신의 시선을 피해 얼른 입가를 닦는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"사격 노점의 도전\",\"text\":\"광장 한켠의 사격 노점에서 인형을 걸고 도전하는 사람들이 몰려 있다. 큰 곰 인형이 하루의 시선을 끌지만 그녀는 쉽사리 말을 꺼내지 못한다. 대검 사용자라 사격은 서툴다며 소심하게 중얼거리는 모습이 귀엽다. 당신은 그녀의 시선을 눈치채고 말을 걸 수 있다. 노점 주인은 곰 인형 앞에서 머뭇거리는 하루를 눈치채고 슬쩍 눈짓을 보낸다. 하루는 못 본 척 고개를 돌리지만 귀 끝이 빨개져 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"빵집 앞의 줄\",\"text\":\"광장 모퉁이에 갓 구운 빵을 파는 가게가 있고, 긴 줄이 늘어서 있다. 하루는 줄 끝에 서서 코를 킁킁거리며 향기를 들이마신다. 빵 종류가 너무 많아서 무엇을 고를지 진지하게 고민하는 모습이 귀엽다. 당신이 하나 사 주겠다고 하자 하루는 어쩔 줄 몰라 하면서도 눈은 이미 가장 큰 빵을 향한다. 줄이 줄어들며 따뜻한 향이 더욱 짙어진다. 줄이 줄어드는 사이 하루는 군침을 삼키며 당신과 소소한 이야기를 나눈다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"북적이는 사람들\",\"text\":\"축제는 점점 무르익고 사람들이 광장으로 몰려든다. 하루는 인파에 밀려 당신과 떨어질 뻔하다 소매를 붙든다. 평소 많은 사람 앞에서 지휘하던 그녀지만 이런 소란스러움은 낯설고 당황스러운 듯하다. 근처에서 별숲리그 동료들이 하루를 알아보고 손을 흔든다. 어디선가 악단의 연주가 시작되고 사람들이 박수를 치며 흥겹게 몸을 흔든다. 하루는 그 한가운데서 어쩔 줄 몰라 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"사격 노점에 도전해 곰 인형을 노린다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"하루가 직접 해 보도록 권한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_3\",\"text\":\"다른 노점으로 향한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"빗나간 한 발\",\"text\":\"당신의 첫 발이 허공으로 날아가자 하루가 작게 웃음을 터뜨린다. 곧 미안한 듯 입을 가리지만 어깨가 들썩인다. 두 번째 발은 가까스로 인형 귀퉁이를 스치고, 하루가 응원하는 목소리를 높인다. 점점 승부욕이 붙은 두 사람 사이로 웃음이 번진다. 노점 주인은 두 사람의 승부를 구경하며 인형 하나를 더 걸어 주겠다고 장난스럽게 말한다. 하루는 손뼉을 치며 \\\"한 번 더요!\\\"라고 외치고, 평소와 다른 모습에 당신도 웃음이 난다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"등불 띄우기\",\"text\":\"해가 지자 광장 한가운데서 소원 등불을 띄우는 행사가 시작된다. 하루는 등불에 소원을 적으며 오랫동안 펜을 멈춘다. 지키고 싶은 사람들, 아직 흐릿한 어머니의 기억, 토마스와 빅터에 대한 걱정이 마음을 스친다. 당신에게는 어떤 소원을 적었는지 묻는 듯한 눈빛을 보낸다. 수백 개의 등불이 밤하늘로 천천히 오르기 시작하자 광장이 환상적인 빛으로 물든다. 등불 속 촛불이 하루의 표정을 따스하게 비춘다. 당신은 곁에서 조용히 자신의 등불을 쥐고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"모두의 평화를 빈다고 말한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_2\",\"text\":\"하루의 소원이 이루어지길 빈다고 말한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_3\",\"text\":\"소원은 비밀이라고 장난스럽게 답한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"작은 소원\",\"text\":\"하루가 놀란 듯 눈을 크게 뜨더니 이내 얼굴이 붉어진다. \\\"저, 저를요…?\\\" 하며 손끝으로 등불 종이를 만지작거린다. 잠시 후 부끄러운 미소와 함께 \\\"그럼 저도 당신의 소원을 빌게요\\\"라고 작게 속삭인다. 등불이 하늘로 천천히 떠오르며 두 사람의 얼굴을 따뜻하게 비춘다. 하루가 쓴 소원은 접힌 종이 속에 감추어져 당신에게는 보이지 않는다. 다만 종이를 접는 그녀의 손끝에서 따뜻한 마음이 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"불꽃놀이\",\"text\":\"밤하늘에 불꽃이 쏘아 올려진다. 하루는 한순간 놀라 어깨를 움츠리지만 이내 환하게 올려다본다. 불꽃의 빛이 그녀의 얼굴 위로 물결치고, 평화로운 일상이야말로 자신이 지키고 싶은 것임을 새삼 느낀다. 하루는 당신 곁에서 조용히 불꽃을 본다. 쾅 하는 소리가 울릴 때마다 하루의 어깨가 작게 움찔하지만 곧 작게 웃으며 하늘을 올려다본다. 불꽃이 비치는 그녀의 눈동자에 별이 가득하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"손을 잡고 인파를 헤쳐 나간다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"동료들과 합류해 함께 즐긴다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"지쳤으니 숙소로 일찍 돌아가자고 한다\",\"varOps\":[{\"var\":\"축제흥\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":60,\"type\":\"story\",\"title\":\"손끝의 온기\",\"text\":\"인파가 늘어난 광장에서 당신이 하루의 손을 가볍게 잡아 이끈다. 하루는 깜짝 놀라 어깨를 떨지만 곧 고개를 숙인 채 조용히 따라온다. 귀 끝이 불그레하게 물들어 있다. 손을 놓는 순간 서로 어색하게 웃고, 하루는 \\\"죄, 죄송해요, 아니 고마워요\\\"라며 말을 더듬는다. 광장의 불빛이 두 사람 위로 따스하게 내려앉는다. 하루는 손바닥에 남은 온기를 느끼며 잠시 시선을 먼 곳으로 돌린다. 이내 고개를 흔들고 환하게 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"옥상에서 본 광장\",\"text\":\"축제의 마지막 불빛이 사그라드는 시간, 하루와 당신은 숙소 옥상에 올라가 광장을 내려다본다. 조금 전까지 북적이던 거리가 고요하고 따뜻하게 가라앉아 있다. 하루는 난간에 기대어 \\\"평화로운 일상이 이렇게 소중한 건지 몰랐어요\\\"라고 말한다. 바람이 불어와 머리카락이 흩날리고, 그녀는 조용히 눈을 감는다. 당신은 곁에서 고개를 끄덕이며 그녀의 말을 곱씹고, 먼 하늘에는 마지막 불꽃이 반짝인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"축제의 끝자락\",\"text\":\"인파가 흩어지고 등불이 하나둘 꺼진다. 하루는 아쉬운 듯 광장을 한 번 더 둘러보다 당신 앞에 선다. 오늘 하루가 얼마나 즐거웠는지 말하려다 쑥스러워 말끝을 흐린다. 렐름의 밤바람이 불어오는 가운데 둘은 천천히 숙소를 향해 걸음을 옮긴다. 바닥에는 꺼진 불꽃의 잔해와 웃음의 흔적이 남아 있다. 하루는 곰 인형이든 아니든 오늘 얻은 모든 것을 소중히 안고 걸어간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"축제흥\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"축제흥\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"가장 반짝인 밤\",\"text\":\"하루는 오늘의 축제를 평생 잊지 못할 것이라며 쑥스럽게 웃는다. 손에는 곰 인형과 빈 꼬치 막대가 쥐어져 있다. 당신에게 \\\"다음 축제도 같이 와 주세요\\\"라고 작게 속삭이는 목소리에 별빛이 닿는다. 숙소 앞에서 하루는 작별 인사를 하다 말고 한 번 더 광장 쪽을 바라본다. 밤하늘에는 아직 떠 있는 등불이 하나둘 보이고, 둘의 그림자가 나란히 길게 이어진다. 평화로운 일상의 소중함이 마음 깊이 남는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"은은한 여운\",\"text\":\"화려하진 않았지만 평온한 축제였다. 하루는 가볍게 인사를 건네고 숙소로 향하며, 오늘 같은 날이 자주 있었으면 좋겠다고 혼잣말처럼 중얼거린다. 하루는 숙소 문 앞에서 작은 손짓으로 인사를 하고는 조용히 들어간다. 광장의 마지막 등불이 꺼질 때까지 당신은 잠시 서서 오늘의 소리와 빛을 마음속에 새긴다. 소박해서 더 따뜻한 밤이다. 하루는 헤헤 하고 웃으며 인사한 뒤 문을 닫는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"조용히 지나간 밤\",\"text\":\"축제는 어느새 끝나 있었다. 하루는 조금 아쉬운 표정이지만 억지로 웃으며 \\\"다음에는 더 즐겨 봐요\\\"라고 말한다. 당신은 그녀의 아쉬움을 달래 줄 방법을 곰곰이 생각한다. 하루는 숙소 앞에서 조용히 인사를 건네고 돌아선다. 등을 보이며 걷는 그녀의 걸음이 평소보다 조금 느리다. 당신은 내일 다시 함께 거닐 수 있을지 생각하며 광장의 마지막 불빛을 바라본다. 하루는 숙소 문 앞에서 한 번 더 뒤를 돌아본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '별빛 가득한 렐름 축제의 밤'
);

-- 06. [하루 에스티아] 끊어진 통신, 구출 작전 제로아워
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '끊어진 통신, 구출 작전 제로아워', 'published', 0, '{\"vars\":[{\"name\":\"결단\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"끊어진 통신\",\"text\":\"소울워커 정찰조 둘이 공백의 잔재가 남은 폐허에서 통신이 끊겼다. 하루 에스티아는 소식을 듣자마자 검을 챙겨 달려 나온다. 평소의 예의 바른 모습은 사라지고 얼굴엔 긴박함이 서려 있다. 제한 시간은 한 시간. 하루는 당신을 보며 \\\"도와주실 수 있나요?\\\"라고 묻는다. 당신은 구출조의 일원이다. 작전실의 경보음이 연이어 울리고 소울워커들이 분주히 오간다. 하루의 손가락이 지도 위에서 빠르게 움직인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"즉시 출발하자고 한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_2\",\"text\":\"정찰 장비를 챙기고 출발하자고 한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_3\",\"text\":\"본부에 보고하고 승인을 기다린다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"빠른 장비 점검\",\"text\":\"짧은 시간에 구조 로프와 응급키트, 신호탄을 챙긴다. 하루는 손놀림이 빨라 마치 훈련된 군의관 같다. \\\"의사를 꿈꾸던 때가 도움이 되네요\\\"라며 쓴웃음을 짓는다. 당신이 마지막 장비를 확인하는 사이 하루는 지도 위에 이동 경로를 그어 나간다. 시계 초침이 흐르는 소리가 유난히 크게 들린다. 한 시간이라는 제한이 두 사람의 어깨를 짓누른다. 하루는 장비 가방을 단단히 멘 뒤 당신에게 출발 신호를 보낸다. 눈빛이 결연하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"공백의 잔재 지대\",\"text\":\"무너진 건물 사이로 하얀 빛 같은 균열이 곳곳에 남아 있다. 공백의 영향권이라 소울 에너지가 불안정하다. 하루는 검을 쥔 채 신경을 곤두세우며 나아간다. 이곳에서 15년을 보낸 기억이 스치는지 한순간 표정이 굳지만 곧 정신을 가다듬는다. 당신은 후방을 맡아 경계한다. 바닥에는 부서진 간판과 낡은 장난감이 흩어져 있어, 한때 이곳에 평범한 일상이 있었음을 말해 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"희미한 신호\",\"text\":\"폐허 한가운데서 하루는 휴대용 수신기를 꺼내 정찰조의 마지막 신호를 추적한다. 잡음 사이로 희미하게 들리는 목소리는 끊어졌다 이어졌다를 반복한다. 하루는 귀를 바싹 대고 숨을 죽인다. \\\"아직 살아 있어요, 분명히요.\\\" 그녀의 목소리에 희망과 불안이 섞여 있다. 당신은 주변 경계를 서며 무너진 건물 사이를 살핀다. 신호가 끊기자 하루는 입술을 깨물고 곧바로 다음 방향으로 발을 옮긴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"갈림길\",\"text\":\"길이 두 갈래로 나뉜다. 한쪽은 정찰조가 마지막으로 신호를 보낸 지하 통로, 다른 한쪽은 소울정크 둥지로 이어지는 큰길이다. 시간은 촉박하고 어느 쪽에 대원이 있는지 확신할 수 없다. 하루는 빠르게 결정해야 한다는 것을 알면서도 잠시 입술을 깨물고, 당신의 의견을 구한다. 어디선가 희미한 신호음이 들려오지만 방향을 특정할 수 없다. 하루는 귀를 기울이며 조용히 신호의 흐름을 가늠한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"지하 통로로 내려간다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"큰길로 가서 소울정크를 유인한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"하루와 갈라져 양쪽을 동시에 수색한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":250,\"type\":\"story\",\"title\":\"유인 작전\",\"text\":\"당신과 하루는 큰길로 나서 일부러 소리를 내며 소울정크를 끌어낸다. 하루는 \\\"비켜!\\\"라고 낮게 외치며 선두의 적을 베어 넘기고, 곧바로 \\\"아, 죄송해요, 지금은 집중할게요\\\"라며 평소 말투로 돌아온다. 소울정크 무리가 이쪽으로 쏠리며 지하 통로가 한결 안전해진다. 폐허에 울려 퍼지는 전투음이 멀리 숨은 소울정크들까지 깨운다. 하루는 호흡을 가다듬으며 당신과 보폭을 맞춘다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"쓰러진 두 사람\",\"text\":\"무너진 통로 안에서 정찰조 두 명이 발견된다. 한 명은 다리가 낀 채 의식이 흐릿하고 다른 한 명은 출혈이 있다. 하루는 곧바로 무릎을 꿇고 상태를 확인하며 침착하게 지시를 내린다. 그러나 소울정크의 발소리가 점점 가까워진다. 한 명을 먼저 구해야 하는 선택이 눈앞에 닥쳤다. 하루의 목소리는 평소보다 낮고 빠르다. 손은 이미 응급키트를 열고 있다. 그녀의 이마에 맺힌 땀이 어둠 속에서 번쩍인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"출혈이 있는 대원부터 응급 처치한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"낀 다리를 먼저 빼낸다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"둘 다 한꺼번에 업고 나가려 한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"무너지는 천장\",\"text\":\"낀 다리를 빼내는 동안 천장에서 파편이 떨어진다. 하루가 몸을 날려 파편을 대검으로 막아 내며 \\\"서둘러 주세요!\\\"라고 외친다. 팔에 작은 상처가 생겼지만 그녀는 개의치 않고 대원을 부축해 일으킨다. 당신의 손이 빨라질수록 소울정크의 울음소리가 커진다. 먼지 속에서 하루의 눈빛이 번쩍이며, 당신에게 \\\"괜찮아요, 계속하세요\\\"라고 짧게 말한다. 시간은 빠르게 줄어든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"마지막 돌파\",\"text\":\"출구 앞에서 소울정크 무리가 길을 막는다. 하루는 부상자들을 당신 곁에 두고 한 걸음 앞으로 나선다. 서늘하고 단호한 눈빛으로 \\\"용서하지 않겠어\\\"라고 낮게 읊조린 뒤 대검에 소울을 모은다. 겁 많은 소녀의 모습은 어디에도 없다. 당신은 부상자를 지키며 돌파구를 연다. 출구 너머로 희미한 새벽빛이 보이기 시작한다. 하루의 대검이 소울의 빛으로 푸르게 타오른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"부상자를 하루에게 맡기고 길을 개척한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"모두 함께 천천히 이동한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"위험하니 구조 지원을 부르고 기다린다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"느리지만 확실하게\",\"text\":\"부상자를 가운데 두고 세 사람이 한 몸처럼 움직인다. 하루는 앞에서 길을 살피고 당신이 후미를 맡는다. 걸음은 느리지만 한 명도 뒤처지지 않는다. 하루는 부상자에게 계속 말을 걸며 의식을 붙잡아 준다. \\\"조금만 더 가면 돼요, 조금만요.\\\" 폐허를 가르는 바람 속에서 그 목소리가 따뜻하게 이어진다. 새벽 어스름이 폐허 위로 서서히 번지기 시작하고 출구가 가까워진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"출구 앞의 정적\",\"text\":\"무리가 물러가고 폐허에는 잠시 정적이 내려앉는다. 하루는 부상자들의 상태를 마지막으로 점검하고, 신호탄을 쏘아 올려 의무대에 위치를 알린다. 하얀 연기가 새벽 하늘로 천천히 올라간다. 긴장이 풀린 듯 하루의 손이 미세하게 떨리는 것을 당신은 놓치지 않는다. 그녀는 눈이 마주치자 어색하게 웃으며 손을 감춘다. 하루는 연기가 사라질 때까지 하늘을 올려다보며 숨을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"돌아온 아침\",\"text\":\"구출은 끝났다. 새벽 햇살이 폐허 위로 스며들고, 하루는 부상자들이 의무대로 옮겨지는 것을 지켜본다. 그제야 긴장이 풀려 다리가 떨리고 \\\"아하하… 이제야 무서워졌어요\\\"라고 쓴웃음을 짓는다. 당신이 곁에서 물을 건네자 하루는 고맙다며 천천히 숨을 고른다. 멀리서 별숲리그 의무대의 구조 차량이 달려오는 소리가 들린다. 하루는 지평선 너머로 떠오르는 해를 바라보며 천천히 숨을 내쉰다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"결단\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"결단\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"모두가 돌아온 새벽\",\"text\":\"두 대원 모두 무사히 구해 냈다. 하루는 눈물을 글썽이며 당신에게 깊이 고개 숙여 감사한다. \\\"혼자였다면 절대 못 했을 거예요.\\\" 리더로서 또 한 번 성장한 하루는 환하게 웃으며 다음에도 함께 싸우자고 말한다. 의무대 앞에서 구출된 대원들이 서로 부축하며 하루에게 고개를 숙인다. 하루는 당황해 손사래를 치면서도 눈가가 붉어져 있다. 새벽빛 속에서 당신과 하루는 오래도록 나란히 서 있는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"무사하지만 상처 입은 귀환\",\"text\":\"두 대원을 구해 냈지만 한 명은 중상을 입었다. 하루는 자신의 판단이 더 빨랐다면 하고 아쉬워한다. 당신의 위로에 겨우 고개를 끄덕이며 병원으로 향하는 그녀의 어깨가 무겁다. 병실 앞 복도에서 하루는 조용히 벽에 기대 서 있다. 당신이 건넨 따뜻한 차를 두 손으로 받아 들고 한참을 말없이 바라본다. 다음 작전을 위해 더 단단해지겠다는 다짐이 눈빛에 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"늦은 새벽\",\"text\":\"구출은 너무 늦었고 대원들의 상태는 심각하다. 하루는 침묵한 채 이를 악문다. 당신이 곁에 서자 그녀는 작은 목소리로 \\\"다음에는 반드시 지키겠어요\\\"라고 말한다. 눈빛에는 슬픔과 결의가 함께 담겨 있다. 폐허 위로 해가 완전히 떠오르고, 하루는 말없이 검을 거둔다. 그녀는 당신에게 짧게 목례하고 의무대로 향한다. 뒷모습에는 슬픔과 함께 다시는 같은 일을 겪지 않겠다는 굳은 의지가 서려 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n9\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"결단\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"끊어진 통신\",\"text\":\"소울워커 정찰조 둘이 공백의 잔재가 남은 폐허에서 통신이 끊겼다. 하루 에스티아는 소식을 듣자마자 검을 챙겨 달려 나온다. 평소의 예의 바른 모습은 사라지고 얼굴엔 긴박함이 서려 있다. 제한 시간은 한 시간. 하루는 당신을 보며 \\\"도와주실 수 있나요?\\\"라고 묻는다. 당신은 구출조의 일원이다. 작전실의 경보음이 연이어 울리고 소울워커들이 분주히 오간다. 하루의 손가락이 지도 위에서 빠르게 움직인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"즉시 출발하자고 한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_2\",\"text\":\"정찰 장비를 챙기고 출발하자고 한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_3\",\"text\":\"본부에 보고하고 승인을 기다린다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"빠른 장비 점검\",\"text\":\"짧은 시간에 구조 로프와 응급키트, 신호탄을 챙긴다. 하루는 손놀림이 빨라 마치 훈련된 군의관 같다. \\\"의사를 꿈꾸던 때가 도움이 되네요\\\"라며 쓴웃음을 짓는다. 당신이 마지막 장비를 확인하는 사이 하루는 지도 위에 이동 경로를 그어 나간다. 시계 초침이 흐르는 소리가 유난히 크게 들린다. 한 시간이라는 제한이 두 사람의 어깨를 짓누른다. 하루는 장비 가방을 단단히 멘 뒤 당신에게 출발 신호를 보낸다. 눈빛이 결연하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"공백의 잔재 지대\",\"text\":\"무너진 건물 사이로 하얀 빛 같은 균열이 곳곳에 남아 있다. 공백의 영향권이라 소울 에너지가 불안정하다. 하루는 검을 쥔 채 신경을 곤두세우며 나아간다. 이곳에서 15년을 보낸 기억이 스치는지 한순간 표정이 굳지만 곧 정신을 가다듬는다. 당신은 후방을 맡아 경계한다. 바닥에는 부서진 간판과 낡은 장난감이 흩어져 있어, 한때 이곳에 평범한 일상이 있었음을 말해 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"희미한 신호\",\"text\":\"폐허 한가운데서 하루는 휴대용 수신기를 꺼내 정찰조의 마지막 신호를 추적한다. 잡음 사이로 희미하게 들리는 목소리는 끊어졌다 이어졌다를 반복한다. 하루는 귀를 바싹 대고 숨을 죽인다. \\\"아직 살아 있어요, 분명히요.\\\" 그녀의 목소리에 희망과 불안이 섞여 있다. 당신은 주변 경계를 서며 무너진 건물 사이를 살핀다. 신호가 끊기자 하루는 입술을 깨물고 곧바로 다음 방향으로 발을 옮긴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"갈림길\",\"text\":\"길이 두 갈래로 나뉜다. 한쪽은 정찰조가 마지막으로 신호를 보낸 지하 통로, 다른 한쪽은 소울정크 둥지로 이어지는 큰길이다. 시간은 촉박하고 어느 쪽에 대원이 있는지 확신할 수 없다. 하루는 빠르게 결정해야 한다는 것을 알면서도 잠시 입술을 깨물고, 당신의 의견을 구한다. 어디선가 희미한 신호음이 들려오지만 방향을 특정할 수 없다. 하루는 귀를 기울이며 조용히 신호의 흐름을 가늠한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"지하 통로로 내려간다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"큰길로 가서 소울정크를 유인한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"하루와 갈라져 양쪽을 동시에 수색한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":250,\"type\":\"story\",\"title\":\"유인 작전\",\"text\":\"당신과 하루는 큰길로 나서 일부러 소리를 내며 소울정크를 끌어낸다. 하루는 \\\"비켜!\\\"라고 낮게 외치며 선두의 적을 베어 넘기고, 곧바로 \\\"아, 죄송해요, 지금은 집중할게요\\\"라며 평소 말투로 돌아온다. 소울정크 무리가 이쪽으로 쏠리며 지하 통로가 한결 안전해진다. 폐허에 울려 퍼지는 전투음이 멀리 숨은 소울정크들까지 깨운다. 하루는 호흡을 가다듬으며 당신과 보폭을 맞춘다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"쓰러진 두 사람\",\"text\":\"무너진 통로 안에서 정찰조 두 명이 발견된다. 한 명은 다리가 낀 채 의식이 흐릿하고 다른 한 명은 출혈이 있다. 하루는 곧바로 무릎을 꿇고 상태를 확인하며 침착하게 지시를 내린다. 그러나 소울정크의 발소리가 점점 가까워진다. 한 명을 먼저 구해야 하는 선택이 눈앞에 닥쳤다. 하루의 목소리는 평소보다 낮고 빠르다. 손은 이미 응급키트를 열고 있다. 그녀의 이마에 맺힌 땀이 어둠 속에서 번쩍인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"출혈이 있는 대원부터 응급 처치한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"낀 다리를 먼저 빼낸다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"둘 다 한꺼번에 업고 나가려 한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"무너지는 천장\",\"text\":\"낀 다리를 빼내는 동안 천장에서 파편이 떨어진다. 하루가 몸을 날려 파편을 대검으로 막아 내며 \\\"서둘러 주세요!\\\"라고 외친다. 팔에 작은 상처가 생겼지만 그녀는 개의치 않고 대원을 부축해 일으킨다. 당신의 손이 빨라질수록 소울정크의 울음소리가 커진다. 먼지 속에서 하루의 눈빛이 번쩍이며, 당신에게 \\\"괜찮아요, 계속하세요\\\"라고 짧게 말한다. 시간은 빠르게 줄어든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"마지막 돌파\",\"text\":\"출구 앞에서 소울정크 무리가 길을 막는다. 하루는 부상자들을 당신 곁에 두고 한 걸음 앞으로 나선다. 서늘하고 단호한 눈빛으로 \\\"용서하지 않겠어\\\"라고 낮게 읊조린 뒤 대검에 소울을 모은다. 겁 많은 소녀의 모습은 어디에도 없다. 당신은 부상자를 지키며 돌파구를 연다. 출구 너머로 희미한 새벽빛이 보이기 시작한다. 하루의 대검이 소울의 빛으로 푸르게 타오른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"부상자를 하루에게 맡기고 길을 개척한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"모두 함께 천천히 이동한다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"위험하니 구조 지원을 부르고 기다린다\",\"varOps\":[{\"var\":\"결단\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"느리지만 확실하게\",\"text\":\"부상자를 가운데 두고 세 사람이 한 몸처럼 움직인다. 하루는 앞에서 길을 살피고 당신이 후미를 맡는다. 걸음은 느리지만 한 명도 뒤처지지 않는다. 하루는 부상자에게 계속 말을 걸며 의식을 붙잡아 준다. \\\"조금만 더 가면 돼요, 조금만요.\\\" 폐허를 가르는 바람 속에서 그 목소리가 따뜻하게 이어진다. 새벽 어스름이 폐허 위로 서서히 번지기 시작하고 출구가 가까워진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"출구 앞의 정적\",\"text\":\"무리가 물러가고 폐허에는 잠시 정적이 내려앉는다. 하루는 부상자들의 상태를 마지막으로 점검하고, 신호탄을 쏘아 올려 의무대에 위치를 알린다. 하얀 연기가 새벽 하늘로 천천히 올라간다. 긴장이 풀린 듯 하루의 손이 미세하게 떨리는 것을 당신은 놓치지 않는다. 그녀는 눈이 마주치자 어색하게 웃으며 손을 감춘다. 하루는 연기가 사라질 때까지 하늘을 올려다보며 숨을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"돌아온 아침\",\"text\":\"구출은 끝났다. 새벽 햇살이 폐허 위로 스며들고, 하루는 부상자들이 의무대로 옮겨지는 것을 지켜본다. 그제야 긴장이 풀려 다리가 떨리고 \\\"아하하… 이제야 무서워졌어요\\\"라고 쓴웃음을 짓는다. 당신이 곁에서 물을 건네자 하루는 고맙다며 천천히 숨을 고른다. 멀리서 별숲리그 의무대의 구조 차량이 달려오는 소리가 들린다. 하루는 지평선 너머로 떠오르는 해를 바라보며 천천히 숨을 내쉰다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"결단\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"결단\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"모두가 돌아온 새벽\",\"text\":\"두 대원 모두 무사히 구해 냈다. 하루는 눈물을 글썽이며 당신에게 깊이 고개 숙여 감사한다. \\\"혼자였다면 절대 못 했을 거예요.\\\" 리더로서 또 한 번 성장한 하루는 환하게 웃으며 다음에도 함께 싸우자고 말한다. 의무대 앞에서 구출된 대원들이 서로 부축하며 하루에게 고개를 숙인다. 하루는 당황해 손사래를 치면서도 눈가가 붉어져 있다. 새벽빛 속에서 당신과 하루는 오래도록 나란히 서 있는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"무사하지만 상처 입은 귀환\",\"text\":\"두 대원을 구해 냈지만 한 명은 중상을 입었다. 하루는 자신의 판단이 더 빨랐다면 하고 아쉬워한다. 당신의 위로에 겨우 고개를 끄덕이며 병원으로 향하는 그녀의 어깨가 무겁다. 병실 앞 복도에서 하루는 조용히 벽에 기대 서 있다. 당신이 건넨 따뜻한 차를 두 손으로 받아 들고 한참을 말없이 바라본다. 다음 작전을 위해 더 단단해지겠다는 다짐이 눈빛에 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"늦은 새벽\",\"text\":\"구출은 너무 늦었고 대원들의 상태는 심각하다. 하루는 침묵한 채 이를 악문다. 당신이 곁에 서자 그녀는 작은 목소리로 \\\"다음에는 반드시 지키겠어요\\\"라고 말한다. 눈빛에는 슬픔과 결의가 함께 담겨 있다. 폐허 위로 해가 완전히 떠오르고, 하루는 말없이 검을 거둔다. 그녀는 당신에게 짧게 목례하고 의무대로 향한다. 뒷모습에는 슬픔과 함께 다시는 같은 일을 겪지 않겠다는 굳은 의지가 서려 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n9\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '끊어진 통신, 구출 작전 제로아워'
);

-- 07. [하루 에스티아] 하루의 고기 요리 대결: 렐름 쿠킹 배틀
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @haru_id, '하루의 고기 요리 대결: 렐름 쿠킹 배틀', 'published', 0, '{\"vars\":[{\"name\":\"맛점수\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"쿠킹 배틀 초대장\",\"text\":\"렐름의 식당 주인이 작은 요리 대결을 연다는 소문이 돌았고, 어느새 하루 에스티아가 참가자 명단에 이름이 올라 있다. 하루는 어쩔 줄 몰라 하며 \\\"제가 요리 대결이라니요…\\\"라고 중얼거린다. 하지만 고기 요리를 좋아하는 마음에 슬그머니 흥미가 생긴다. 상대는 소울워커 동료 릴리. 당신은 하루의 보조 요리사로 지명된다. 식당 게시판에는 우승 상품인 고기 세트 그림이 크게 그려져 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"주제를 고기 요리로 정하자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_2\",\"text\":\"빵도 곁들이자고 제안한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_3\",\"text\":\"무난하게 수프를 만들자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"빵 반죽의 비밀\",\"text\":\"하루는 빵 반죽을 치대며 눈을 반짝인다. 좋아하는 것이라 손놀림이 자연스럽다. 반죽이 부풀기를 기다리는 동안 그녀는 어머니와 함께 빵을 구웠던 것 같은 느낌이 든다며 작게 웃는다. 당신이 오븐 불을 맡아 두 사람의 호흡이 맞아 들어간다. 밀가루가 하루의 볼에 묻은 것도 모른 채 반죽에 열중하는 모습이 사랑스럽다. 반죽은 하루의 손바닥 아래에서 점점 부드러운 모양을 갖춰 가고, 주방에는 고소한 냄새가 서서히 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"시장 장보기\",\"text\":\"아침 시장에서 재료를 고르는 하루. 신선한 고기를 고르는 눈이 매서울 정도로 진지하다. 상인의 칭찬에 \\\"저 같은 게요, 아하하\\\" 하며 손사래를 치지만 값을 깎는 솜씨는 의외로 단호하다. 당신은 짐꾼 겸 조언자로서 재료 선택에 한마디를 보탤 수 있다. 시장 골목에는 빵 굽는 냄새와 향신료 향이 가득 퍼져 있어 하루의 걸음이 자꾸만 느려진다. 당신이 들고 있는 장바구니는 어느새 고기와 채소로 가득 찬다. 하루는 만족스럽게 고개를 끄덕인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"레시피 구상\",\"text\":\"대결을 앞두고 하루는 작은 수첩을 펴 레시피를 적어 나간다. 어머니가 해 주셨던 요리가 흐릿하게 떠오르지만 정확한 방법은 알 수 없어 연필 끝이 자주 멈춘다. 하루는 당신에게 \\\"이런 맛이 아닐까요?\\\" 하며 조심스럽게 의견을 구한다. 두 사람이 이것저것 시도해 보는 동안 주방에는 향신료 냄새가 가득 퍼진다. 하루의 얼굴에 점점 즐거운 기색이 감돈다. 하루는 수첩을 덮고 활짝 웃으며 당신에게 손을 내민다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"대결 시작\",\"text\":\"조리대 앞에 선 하루는 앞치마를 질끈 묶는다. 관중들의 시선에 긴장해 칼질이 조금 떨리지만 이내 집중한다. 맞은편의 릴리는 능숙하게 팬을 돌린다. 시간은 30분. 하루는 당신을 힐끔 보며 \\\"잘 부탁드려요\\\"라고 작게 속삭이고, 불꽃이 확 타오른다. 사회자의 힘찬 신호와 함께 관중의 환호가 터져 나온다. 하루는 깊게 숨을 들이쉰다. 조리대 위에서는 칼과 도마가 부딪치는 경쾌한 소리가 쉴 새 없이 울려 퍼진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"불 조절을 맡아 고기를 완벽하게 굽는다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"하루에게 소스를 맡기고 자신은 곁들임을 만든다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"시간이 없으니 서두르자고 재촉한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":250,\"type\":\"story\",\"title\":\"소스의 승부수\",\"text\":\"하루가 비밀 소스를 만들어 낸다. 과일을 졸이고 향신료를 더하는 손놀림이 놀랍도록 조심스럽다. 한 숟갈 맛을 보고는 눈을 동그랗게 뜨며 \\\"이거… 맛있어요\\\"라고 소곤댄다. 당신이 접시 위에 곁들임을 올리자 요리의 모양새가 한결 살아난다. 달콤한 향이 조리대를 넘어 관중석까지 퍼져 사람들의 코끝을 간지럽힌다. 맞은편의 릴리도 흘끗 이쪽을 바라본다. 하루는 작은 숟가락으로 소스를 한 번 더 맛보고 소금을 아주 조금 더한다. 그 모습이 진지하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"예상치 못한 사고\",\"text\":\"고기에 불이 확 붙어 연기가 치솟는다. 하루는 \\\"히익!\\\" 하고 비명을 지르며 뒤로 물러나지만 곧 정신을 차리고 뚜껑을 덮는다. 관중석이 술렁이고 시간은 5분밖에 남지 않았다. 하루는 당황해서 말을 더듬으면서도 포기하지 않으려 한다. 당신의 대응이 결과를 가른다. 사회자의 해설이 다급하게 커지고 관중들의 웅성거림이 두 사람 귀에 쏟아진다. 연기 속에서도 하루의 시선은 꺼져 가는 불을 놓치지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"침착하게 불을 끄고 고기를 다시 손질한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"소스로 맛을 덮어 마무리하자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"이번 판은 포기하자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"하루의 오기\",\"text\":\"당신의 말에 하루의 눈빛이 단호하게 변한다. \\\"포기하지 않을 거예요.\\\" 전투 때처럼 낮고 서늘한 목소리다. 곧 스스로 놀라 \\\"아, 죄송해요, 열이 올랐네요\\\"라며 얼굴을 붉힌다. 그러나 손은 이미 새 고기를 집어 들고 칼질을 시작한다. 당신은 그 기세에 눌려 불 앞으로 되돌아온다. 조리대 위로 다시 불꽃이 피어오르자 관중들이 환호성을 지른다. 하루의 이마에는 땀방울이 맺혀 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"심사 시간\",\"text\":\"심사위원단이 두 접시를 번갈아 맛본다. 하루는 손을 꼭 모으고 눈을 질끈 감는다. 결과가 어떻든 정성을 다했다고 스스로를 다독이지만 심장이 쿵쿵 뛴다. 당신은 곁에서 함께 숨을 죽이며 결과를 기다린다. 한 입 한 입 맛을 보는 심사위원들의 표정이 쉽게 읽히지 않는다. 관중석이 숨을 죽이고 조리대 위에는 소스의 달콤한 향이 감돈다. 하루는 눈을 가늘게 뜨고 손을 모은 채 아무 말도 못 하고 서 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"접시를 정성스럽게 담아 완성한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"하루가 직접 접시를 장식하게 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"대충 올려서 빨리 제출한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"작은 장식\",\"text\":\"하루는 접시 가장자리에 소스로 작은 별 모양을 그린다. 평소 검을 쥐던 손이 놀랍도록 섬세하게 움직인다. 옆에서 지켜보던 당신이 감탄하자 하루는 쑥스러워하며 \\\"별숲리그의 별이에요\\\"라고 속삭인다. 완성된 접시가 조명 아래 반짝이고, 관중석에서 작은 탄성이 새어 나온다. 하루의 얼굴에 자신감이 비친다. 사람들의 시선이 접시 위의 작은 별 하나에 집중되고, 하루는 그제야 긴장이 조금 풀린 듯 숨을 내쉰다. 렐름의 조명이 접시 위에서 부드럽게 반짝인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"접시를 올리는 순간\",\"text\":\"접시를 심사 테이블로 옮기는 순간 하루의 손이 미세하게 떨린다. 당신도 숨을 죽이고 곁에서 걸음을 맞춘다. 관중석의 소음이 점점 멀어지는 듯하고, 하루는 속으로 \\\"괜찮아, 괜찮아\\\"를 되뇐다. 접시가 테이블에 놓이자 향기가 퍼지고 심사위원 한 명이 눈을 가늘게 뜬다. 하루는 허리를 숙여 정중히 인사한다. 당신은 하루의 어깨를 가볍게 두드려 격려를 건넨다. 하루는 숨을 한 번 들이쉬고 고개를 든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"결과 발표 후\",\"text\":\"결과 발표가 끝나고 관중들이 흩어진다. 하루는 앞치마를 벗으며 길게 숨을 내쉰다. 오늘 하루가 전투만큼이나 두근거렸다며 웃고, 당신에게 남은 고기 요리를 함께 먹자고 청한다. 렐름의 저녁 하늘이 붉게 물든다. 접시 위에는 아직 따뜻한 고기 요리가 남아 있다. 하루는 포크를 들고 당신이 먼저 맛보기를 기대하는 눈으로 바라본다. 그 소박한 기쁨이 대결의 결과보다 더 소중하게 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"맛점수\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"맛점수\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"우승, 그리고 고기 파티\",\"text\":\"하루의 요리가 심사위원 전원의 호평을 받아 우승을 차지한다. 믿기지 않는 듯 눈을 크게 뜬 하루는 곧 당신의 손을 잡고 \\\"이건 정말 둘이서 해낸 거예요\\\"라며 환하게 웃는다. 우승 상품으로 받은 고기 세트로 밤새 파티가 열린다. 트로피를 든 하루의 손은 아직 조금 떨리고 있다. 식당 사람들의 박수와 환호 속에서 그녀는 쑥스러운 미소로 인사를 한다. 노을이 식당 창문으로 스며들어 모두의 얼굴을 황금빛으로 물들인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"아쉬운 준우승\",\"text\":\"아쉽게 근소한 차이로 준우승이 되었다. 하루는 조금 분한 듯하면서도 릴리와 악수를 나누며 웃는다. \\\"다음엔 이길 거예요, 꼭.\\\" 당신 곁에서 남은 요리를 맛있게 먹으며 하루의 눈은 이미 다음 레시피를 향한다. 릴리가 먼저 다가와 하루의 요리를 칭찬하며 레시피를 묻자 하루는 쑥스럽게 웃으며 대답한다. 두 사람의 대화가 길어지는 사이 당신은 접시를 정리하며 흐뭇하게 바라본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"타 버린 접시의 추억\",\"text\":\"결과는 아쉽게도 하위권이었다. 하루는 쑥스럽게 웃으며 \\\"다음엔 불을 조심할게요\\\"라고 한다. 그래도 당신이 남은 요리를 맛있게 먹어 주자 그녀의 얼굴이 환해진다. 서툴렀지만 함께한 즐거움이 노을 속에 남는다. 렐름의 노을 아래서 하루는 당신과 함께 식당 계단에 걸터앉는다. 식어 버린 고기 한 점을 나눠 먹으며 둘은 오늘 있었던 사고를 이야기하다 웃음을 터뜨린다. 서툴러서 더 오래 기억될 하루다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n9\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"맛점수\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"쿠킹 배틀 초대장\",\"text\":\"렐름의 식당 주인이 작은 요리 대결을 연다는 소문이 돌았고, 어느새 하루 에스티아가 참가자 명단에 이름이 올라 있다. 하루는 어쩔 줄 몰라 하며 \\\"제가 요리 대결이라니요…\\\"라고 중얼거린다. 하지만 고기 요리를 좋아하는 마음에 슬그머니 흥미가 생긴다. 상대는 소울워커 동료 릴리. 당신은 하루의 보조 요리사로 지명된다. 식당 게시판에는 우승 상품인 고기 세트 그림이 크게 그려져 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o2_1\",\"text\":\"주제를 고기 요리로 정하자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o2_2\",\"text\":\"빵도 곁들이자고 제안한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o2_3\",\"text\":\"무난하게 수프를 만들자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n3\",\"x\":1020,\"y\":250,\"type\":\"story\",\"title\":\"빵 반죽의 비밀\",\"text\":\"하루는 빵 반죽을 치대며 눈을 반짝인다. 좋아하는 것이라 손놀림이 자연스럽다. 반죽이 부풀기를 기다리는 동안 그녀는 어머니와 함께 빵을 구웠던 것 같은 느낌이 든다며 작게 웃는다. 당신이 오븐 불을 맡아 두 사람의 호흡이 맞아 들어간다. 밀가루가 하루의 볼에 묻은 것도 모른 채 반죽에 열중하는 모습이 사랑스럽다. 반죽은 하루의 손바닥 아래에서 점점 부드러운 모양을 갖춰 가고, 주방에는 고소한 냄새가 서서히 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"story\",\"title\":\"시장 장보기\",\"text\":\"아침 시장에서 재료를 고르는 하루. 신선한 고기를 고르는 눈이 매서울 정도로 진지하다. 상인의 칭찬에 \\\"저 같은 게요, 아하하\\\" 하며 손사래를 치지만 값을 깎는 솜씨는 의외로 단호하다. 당신은 짐꾼 겸 조언자로서 재료 선택에 한마디를 보탤 수 있다. 시장 골목에는 빵 굽는 냄새와 향신료 향이 가득 퍼져 있어 하루의 걸음이 자꾸만 느려진다. 당신이 들고 있는 장바구니는 어느새 고기와 채소로 가득 찬다. 하루는 만족스럽게 고개를 끄덕인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"레시피 구상\",\"text\":\"대결을 앞두고 하루는 작은 수첩을 펴 레시피를 적어 나간다. 어머니가 해 주셨던 요리가 흐릿하게 떠오르지만 정확한 방법은 알 수 없어 연필 끝이 자주 멈춘다. 하루는 당신에게 \\\"이런 맛이 아닐까요?\\\" 하며 조심스럽게 의견을 구한다. 두 사람이 이것저것 시도해 보는 동안 주방에는 향신료 냄새가 가득 퍼진다. 하루의 얼굴에 점점 즐거운 기색이 감돈다. 하루는 수첩을 덮고 활짝 웃으며 당신에게 손을 내민다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"대결 시작\",\"text\":\"조리대 앞에 선 하루는 앞치마를 질끈 묶는다. 관중들의 시선에 긴장해 칼질이 조금 떨리지만 이내 집중한다. 맞은편의 릴리는 능숙하게 팬을 돌린다. 시간은 30분. 하루는 당신을 힐끔 보며 \\\"잘 부탁드려요\\\"라고 작게 속삭이고, 불꽃이 확 타오른다. 사회자의 힘찬 신호와 함께 관중의 환호가 터져 나온다. 하루는 깊게 숨을 들이쉰다. 조리대 위에서는 칼과 도마가 부딪치는 경쾌한 소리가 쉴 새 없이 울려 퍼진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"불 조절을 맡아 고기를 완벽하게 굽는다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"하루에게 소스를 맡기고 자신은 곁들임을 만든다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"시간이 없으니 서두르자고 재촉한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":250,\"type\":\"story\",\"title\":\"소스의 승부수\",\"text\":\"하루가 비밀 소스를 만들어 낸다. 과일을 졸이고 향신료를 더하는 손놀림이 놀랍도록 조심스럽다. 한 숟갈 맛을 보고는 눈을 동그랗게 뜨며 \\\"이거… 맛있어요\\\"라고 소곤댄다. 당신이 접시 위에 곁들임을 올리자 요리의 모양새가 한결 살아난다. 달콤한 향이 조리대를 넘어 관중석까지 퍼져 사람들의 코끝을 간지럽힌다. 맞은편의 릴리도 흘끗 이쪽을 바라본다. 하루는 작은 숟가락으로 소스를 한 번 더 맛보고 소금을 아주 조금 더한다. 그 모습이 진지하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"예상치 못한 사고\",\"text\":\"고기에 불이 확 붙어 연기가 치솟는다. 하루는 \\\"히익!\\\" 하고 비명을 지르며 뒤로 물러나지만 곧 정신을 차리고 뚜껑을 덮는다. 관중석이 술렁이고 시간은 5분밖에 남지 않았다. 하루는 당황해서 말을 더듬으면서도 포기하지 않으려 한다. 당신의 대응이 결과를 가른다. 사회자의 해설이 다급하게 커지고 관중들의 웅성거림이 두 사람 귀에 쏟아진다. 연기 속에서도 하루의 시선은 꺼져 가는 불을 놓치지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"침착하게 불을 끄고 고기를 다시 손질한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"소스로 맛을 덮어 마무리하자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"이번 판은 포기하자고 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":440,\"type\":\"story\",\"title\":\"하루의 오기\",\"text\":\"당신의 말에 하루의 눈빛이 단호하게 변한다. \\\"포기하지 않을 거예요.\\\" 전투 때처럼 낮고 서늘한 목소리다. 곧 스스로 놀라 \\\"아, 죄송해요, 열이 올랐네요\\\"라며 얼굴을 붉힌다. 그러나 손은 이미 새 고기를 집어 들고 칼질을 시작한다. 당신은 그 기세에 눌려 불 앞으로 되돌아온다. 조리대 위로 다시 불꽃이 피어오르자 관중들이 환호성을 지른다. 하루의 이마에는 땀방울이 맺혀 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"심사 시간\",\"text\":\"심사위원단이 두 접시를 번갈아 맛본다. 하루는 손을 꼭 모으고 눈을 질끈 감는다. 결과가 어떻든 정성을 다했다고 스스로를 다독이지만 심장이 쿵쿵 뛴다. 당신은 곁에서 함께 숨을 죽이며 결과를 기다린다. 한 입 한 입 맛을 보는 심사위원들의 표정이 쉽게 읽히지 않는다. 관중석이 숨을 죽이고 조리대 위에는 소스의 달콤한 향이 감돈다. 하루는 눈을 가늘게 뜨고 손을 모은 채 아무 말도 못 하고 서 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"접시를 정성스럽게 담아 완성한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"하루가 직접 접시를 장식하게 한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"대충 올려서 빨리 제출한다\",\"varOps\":[{\"var\":\"맛점수\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":250,\"type\":\"story\",\"title\":\"작은 장식\",\"text\":\"하루는 접시 가장자리에 소스로 작은 별 모양을 그린다. 평소 검을 쥐던 손이 놀랍도록 섬세하게 움직인다. 옆에서 지켜보던 당신이 감탄하자 하루는 쑥스러워하며 \\\"별숲리그의 별이에요\\\"라고 속삭인다. 완성된 접시가 조명 아래 반짝이고, 관중석에서 작은 탄성이 새어 나온다. 하루의 얼굴에 자신감이 비친다. 사람들의 시선이 접시 위의 작은 별 하나에 집중되고, 하루는 그제야 긴장이 조금 풀린 듯 숨을 내쉰다. 렐름의 조명이 접시 위에서 부드럽게 반짝인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"접시를 올리는 순간\",\"text\":\"접시를 심사 테이블로 옮기는 순간 하루의 손이 미세하게 떨린다. 당신도 숨을 죽이고 곁에서 걸음을 맞춘다. 관중석의 소음이 점점 멀어지는 듯하고, 하루는 속으로 \\\"괜찮아, 괜찮아\\\"를 되뇐다. 접시가 테이블에 놓이자 향기가 퍼지고 심사위원 한 명이 눈을 가늘게 뜬다. 하루는 허리를 숙여 정중히 인사한다. 당신은 하루의 어깨를 가볍게 두드려 격려를 건넨다. 하루는 숨을 한 번 들이쉬고 고개를 든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"결과 발표 후\",\"text\":\"결과 발표가 끝나고 관중들이 흩어진다. 하루는 앞치마를 벗으며 길게 숨을 내쉰다. 오늘 하루가 전투만큼이나 두근거렸다며 웃고, 당신에게 남은 고기 요리를 함께 먹자고 청한다. 렐름의 저녁 하늘이 붉게 물든다. 접시 위에는 아직 따뜻한 고기 요리가 남아 있다. 하루는 포크를 들고 당신이 먼저 맛보기를 기대하는 눈으로 바라본다. 그 소박한 기쁨이 대결의 결과보다 더 소중하게 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"맛점수\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"맛점수\",\"min\":3,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"우승, 그리고 고기 파티\",\"text\":\"하루의 요리가 심사위원 전원의 호평을 받아 우승을 차지한다. 믿기지 않는 듯 눈을 크게 뜬 하루는 곧 당신의 손을 잡고 \\\"이건 정말 둘이서 해낸 거예요\\\"라며 환하게 웃는다. 우승 상품으로 받은 고기 세트로 밤새 파티가 열린다. 트로피를 든 하루의 손은 아직 조금 떨리고 있다. 식당 사람들의 박수와 환호 속에서 그녀는 쑥스러운 미소로 인사를 한다. 노을이 식당 창문으로 스며들어 모두의 얼굴을 황금빛으로 물들인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"아쉬운 준우승\",\"text\":\"아쉽게 근소한 차이로 준우승이 되었다. 하루는 조금 분한 듯하면서도 릴리와 악수를 나누며 웃는다. \\\"다음엔 이길 거예요, 꼭.\\\" 당신 곁에서 남은 요리를 맛있게 먹으며 하루의 눈은 이미 다음 레시피를 향한다. 릴리가 먼저 다가와 하루의 요리를 칭찬하며 레시피를 묻자 하루는 쑥스럽게 웃으며 대답한다. 두 사람의 대화가 길어지는 사이 당신은 접시를 정리하며 흐뭇하게 바라본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"타 버린 접시의 추억\",\"text\":\"결과는 아쉽게도 하위권이었다. 하루는 쑥스럽게 웃으며 \\\"다음엔 불을 조심할게요\\\"라고 한다. 그래도 당신이 남은 요리를 맛있게 먹어 주자 그녀의 얼굴이 환해진다. 서툴렀지만 함께한 즐거움이 노을 속에 남는다. 렐름의 노을 아래서 하루는 당신과 함께 식당 계단에 걸터앉는다. 식어 버린 고기 한 점을 나눠 먹으며 둘은 오늘 있었던 사고를 이야기하다 웃음을 터뜨린다. 서툴러서 더 오래 기억될 하루다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"o2_2\",\"to\":\"n3\"},{\"from\":\"n2\",\"fromPort\":\"o2_1\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n2\",\"fromPort\":\"o2_3\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n9\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @haru_id AND title = '하루의 고기 요리 대결: 렐름 쿠킹 배틀'
);

-- 08. [에프넬] 황금 열차 호위전 - 돈 냄새 나는 의뢰
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '황금 열차 호위전 - 돈 냄새 나는 의뢰', 'published', 0, '{\"vars\":[{\"name\":\"성과\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"의뢰서 한 장\",\"text\":\"동부 아르카디아 렐름의 숙소 라운지. 널브러져 있던 에프넬의 눈앞에 두툼한 봉투가 내밀린다. 클라우드림 상인 조합이 맡긴 고액 호위 의뢰, 보수 앞자리 숫자를 본 순간 그녀의 눈이 번쩍 뜨인다. 방전 상태라던 말은 어디로 갔는지 벌써 몸을 일으켜 계약 조건부터 따지는 중이다. 당신은 별숲리그 협력자로서 이 의뢰서를 함께 읽고 있다. 에프넬은 선의를 의심하는 척 빈정대지만 수상한 구석도 놓치지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"수상한 짐칸\",\"text\":\"출발 직전의 역. 상인 조합이 내세운 화물은 철갑으로 봉인된 황금 열차 한 량이다. 조합 대표는 내용물을 끝내 밝히지 않고 보수만 두 번 강조한다. 에프넬은 봉인을 손끝으로 톡톡 두드리며 돈이 이렇게 많은데 왜 이렇게 급하냐고 중얼거린다. 당신은 그녀 곁에서 화물칸과 승객들을 함께 살핀다. 에프넬의 장난기 아래로 사냥꾼 같은 경계심이 깔리기 시작한다. 그녀의 직감은 이 의뢰가 단순한 운송이 아니라고 계속 속삭이고 있고, 당신도 같은 불안을 느낀다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"화물 내용물을 직접 확인하자고 제안한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"보수가 확실하니 묻지 말고 호위에 집중한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"에프넬이 받을 몫을 흥정해 주겠다고 농담한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"봉인 속의 비밀\",\"text\":\"당신의 제안에 에프넬이 의외라는 듯 눈썹을 올리고 슬쩍 봉인 틈을 비집어 연다. 안에서 나온 것은 황금이 아니라 소울정크 반응이 미약하게 새어 나오는 정체불명의 금속 조각이다. 에프넬은 순간 얼굴이 굳었다가 곧 능글맞은 웃음으로 덮는다. 위험수당은 두 배로 받아야겠다며 투덜대지만, 당신의 눈썰미를 인정하는 눈빛이 잠깐 스친다. 의뢰인이 중요한 사실을 숨기고 있다는 것만은 이제 분명해졌고, 두 사람은 경계를 한층 끌어올린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"달리는 열차의 밤\",\"text\":\"열차가 평원을 가르며 달리는 밤. 객차 지붕 위로 올라간 에프넬이 찬바람을 맞으며 창을 빙글 돌리고 있다. 말로는 위치 선정이 좋아서라지만 실은 승객들이 잠든 객차를 지켜 서 있는 것이다. 멀리 지평선 쪽에서 불길한 소울정크의 울음이 들려온다. 당신은 지붕 위 그녀 옆에 자리를 잡는다. 에프넬은 귀찮은 척하면서도 한쪽 자리를 슬쩍 비워 준다. 차가운 밤바람 속에서도 그녀의 눈은 한순간도 어둠 속 움직임을 놓치지 않으며, 당신의 존재를 슬쩍 의식하는 눈치다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"승객 객차에 남아 사람들을 안심시킨다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"에프넬과 함께 지붕에서 적을 기다린다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"선두 차량 기관실부터 확인하러 간다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":60,\"type\":\"story\",\"title\":\"겁먹은 아이의 손\",\"text\":\"당신이 객차에서 사람들을 달래는 동안, 구석에서 울음을 참던 어린 승객이 당신 소매를 붙든다. 소란을 들은 에프넬이 지붕에서 내려와 아이를 보더니 투덜거리면서도 시선을 피한다. 우는 건 요금 외 서비스라는 둥 말하면서 주머니 속 사탕을 건넨다. 아이의 눈빛 앞에서 그녀는 또 지고 만다. 당신과 눈이 마주치자 에프넬은 아니라고 소리친다. 당신의 다정함이 낯설다는 듯 그녀는 괜히 헛기침을 하고, 그 표정을 보며 당신은 웃음을 참느라 애를 먹는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"소울정크 습격\",\"text\":\"굉음과 함께 선로 양옆에서 소울정크 무리가 솟구친다. 열차는 속도를 늦출 수 없고, 에프넬은 지붕에서 창을 뽑아 들며 사망 플래그 같은 소리 하지 말라고 외친다. 체술과 창술이 뒤섞인 변칙적인 움직임으로 놈들을 걷어차 떨구지만 수가 너무 많다. 당신은 객차 연결부를 지키며 그녀의 등을 맡는다. 에프넬의 목소리에 진짜 긴장이 섞인다. 위기 앞에서도 입은 쉬지 않고 놈들을 비웃지만, 호흡이 점점 거칠어지는 것을 당신은 분명히 느낀다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"연결부를 끊어 화물칸을 지키는 데 집중한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_2\",\"text\":\"에프넬과 호흡을 맞춰 적의 중심을 함께 친다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_3\",\"text\":\"승객을 먼저 대피시키고 합류하겠다고 한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"두 개의 창끝\",\"text\":\"당신의 신호에 맞춰 에프넬이 돌진하고, 당신이 옆을 막아 길을 연다. 둘의 호흡이 맞아떨어지자 소울정크 무리의 중심이 한 번에 무너진다. 에프넬은 숨을 몰아쉬며 방금 건 공동 작업 수수료가 붙는다고 낄낄댄다. 하지만 창을 쥔 손에는 힘이 풀려 있고, 당신이 괜찮냐고 묻자 혀를 차며 고개를 돌린다. 소울정크 무리의 잔해가 흩어지는 가운데 열차는 한결 안정을 되찾고, 승객들의 안도 섞인 숨소리가 객차 안에 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"숨어 있던 배신자\",\"text\":\"습격이 잦아들 무렵, 화물칸 앞에서 상인 조합 대표가 봉인을 열려 하고 있다. 그는 소울정크를 일부러 불러들여 호위를 소모시키려 했던 것이다. 에프넬은 차갑게 식은 목소리로 한 푼도 안 깎아줄 거라며 창끝을 겨눈다. 대표가 돈을 두 배로 주겠다고 매달리자 그녀의 입꼬리가 아슬아슬하게 올라간다. 당신은 두 사람 사이에서 어느 쪽으로 움직일지 지켜본다. 돈이 전부라고 떠들던 그녀가 사람의 탐욕 앞에서 보이는 분노는 어딘가 평소와 사뭇 다르고, 당신의 선택이 결말을 좌우한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"대표를 제압하고 증거를 확보한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"에프넬에게 처리를 맡기고 승객을 지킨다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_3\",\"text\":\"두 배 보수 제안을 일단 들어 보는 척한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":440,\"type\":\"story\",\"title\":\"돈의 값어치\",\"text\":\"당신의 말에 대표가 안도하는 사이, 에프넬이 당신을 흘끗 보더니 풉 하고 웃음을 터뜨린다. 연기인 걸 눈치챈 것이다. 그녀는 지켜지지 않는 돈은 돈이 아니라며 대표의 멱살을 잡아 올린다. 돈은 배신하지 않는다던 그녀의 신조가 사람을 배신하는 인간 앞에서 처음으로 뒤집히는 순간이다. 한바탕 소동이 정리되자 객차에는 어색하면서도 후련한 공기가 흐르고, 에프넬은 모른 척 창밖으로 고개를 돌려 버린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"종착역의 새벽\",\"text\":\"새벽빛이 밝아 오는 종착역. 승객들은 모두 무사히 내렸고, 대표는 별숲리그 감시관에게 인계되었다. 에프넬은 플랫폼 벤치에 널브러져 보수 정산서를 들여다본다. 위험수당이 붙은 숫자를 세며 입이 귀에 걸렸지만, 정작 승객 가족들의 감사 인사 앞에서는 도망치듯 고개를 숙인다. 당신은 그녀 옆에 앉아 이 소동의 끝을 함께 맞는다. 밤새 이어진 긴장이 풀리자 몸이 천근같이 무겁지만, 그녀는 승객 수를 몰래 세어 보며 한 명도 빠지지 않았음을 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"정산의 시간\",\"text\":\"정산서를 접던 에프넬이 문득 당신에게 보수의 일부를 쓱 내민다. 공동 작업 몫이라며 퉁명스럽게 말하지만 귀끝이 붉다. 돈은 네드 컴퍼니를 부수는 수단이라던 그녀가 이번에는 그 돈을 사람에게 나누고 있다. 당신은 그 마음을 받을지, 모른 척 웃어넘길지 선택할 수 있다. 에프넬은 이상한 의미 부여 하지 말라고 미리 못을 박는다. 늘 돈을 쫓는 그녀가 스스로 돈을 내미는 일은 극히 드문 일이어서, 둘 사이의 공기가 묘하게 어색해진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"고맙다며 받고 밥을 사겠다고 한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_2\",\"text\":\"몫은 사양하고 수고했다고 말한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_3\",\"text\":\"적다고 투덜대 에프넬을 놀려 본다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"돌아오는 길\",\"text\":\"아르카디아 렐름으로 돌아가는 길. 에프넬은 느긋하게 하품하며 오늘은 일했으니 사흘은 안 움직일 거라고 선언한다. 하지만 걸음걸이는 평소보다 가볍다. 지평선 위로 공백의 흰 빛이 아득히 보이자 그녀는 잠시 말이 없어진다. 당신은 조용히 그녀 곁을 걷는다. 에프넬은 다음 의뢰도 보수 좋은 걸로만 가져오라고 못 박는다. 이번 의뢰는 끝났지만 둘의 여정은 계속되고, 당신은 그녀의 한결 가벼워진 발걸음 속에서 작은 변화를 읽는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"성과\",\"min\":8,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"성과\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"완벽한 호위, 최고의 정산\",\"text\":\"승객과 화물, 호위 모두 흠 하나 없이 끝낸 최고의 결과. 조합은 사례금까지 얹어 주었고 에프넬은 지갑을 끌어안고 행복해한다. 하지만 밤이 되자 그녀는 당신 방문을 두드려 사례금 일부로 사 온 간식을 던지듯 건넨다. 오늘은 같이 일한 값이라고 말하면서도 시선은 딴 곳이다. 당신은 그 서투른 인정이 오늘의 진짜 보수임을 안다. 이런 날이 계속된다면 의뢰 따위 매번 받아도 나쁘지 않겠다는 생각이 슬며시 고개를 든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"적당히 남는 장사\",\"text\":\"큰 사고 없이 의뢰를 마쳤다. 보수는 기대보다 약간 모자랐지만 에프넬은 그럭저럭 남는 장사였다며 투덜대면서도 만족스러운 표정이다. 당신과 나란히 노을 진 역을 걸으며 다음엔 더 비싼 의뢰만 받자고 떠든다. 하지만 지켜낸 승객의 인사를 떠올리는 그녀의 입가에는 은근한 미소가 남아 있다. 큰 소란 없이 무난히 끝난 하루였기에 오히려 둘 사이에는 편안한 침묵이 오래 머문다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"깎인 수당, 남은 찜찜함\",\"text\":\"일은 마쳤지만 허술한 대응으로 위험수당이 크게 깎였다. 에프넬은 정산서를 구기며 한숨을 쉬고는 공짜 노동이었다고 빈정거린다. 그래도 승객들이 무사한 것만은 다행인 듯, 당신에게 다음엔 손발 좀 맞추자며 퉁명스럽게 말한다. 아쉬움이 남지만 둘의 호흡을 다듬을 다음 기회가 있다는 뜻이기도 하다. 다음에는 더 잘해 보자는 말이 입 밖으로 나오지는 않았지만 서로 같은 마음임을 둘 다 알고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"성과\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"의뢰서 한 장\",\"text\":\"동부 아르카디아 렐름의 숙소 라운지. 널브러져 있던 에프넬의 눈앞에 두툼한 봉투가 내밀린다. 클라우드림 상인 조합이 맡긴 고액 호위 의뢰, 보수 앞자리 숫자를 본 순간 그녀의 눈이 번쩍 뜨인다. 방전 상태라던 말은 어디로 갔는지 벌써 몸을 일으켜 계약 조건부터 따지는 중이다. 당신은 별숲리그 협력자로서 이 의뢰서를 함께 읽고 있다. 에프넬은 선의를 의심하는 척 빈정대지만 수상한 구석도 놓치지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"수상한 짐칸\",\"text\":\"출발 직전의 역. 상인 조합이 내세운 화물은 철갑으로 봉인된 황금 열차 한 량이다. 조합 대표는 내용물을 끝내 밝히지 않고 보수만 두 번 강조한다. 에프넬은 봉인을 손끝으로 톡톡 두드리며 돈이 이렇게 많은데 왜 이렇게 급하냐고 중얼거린다. 당신은 그녀 곁에서 화물칸과 승객들을 함께 살핀다. 에프넬의 장난기 아래로 사냥꾼 같은 경계심이 깔리기 시작한다. 그녀의 직감은 이 의뢰가 단순한 운송이 아니라고 계속 속삭이고 있고, 당신도 같은 불안을 느낀다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"화물 내용물을 직접 확인하자고 제안한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"보수가 확실하니 묻지 말고 호위에 집중한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"에프넬이 받을 몫을 흥정해 주겠다고 농담한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"봉인 속의 비밀\",\"text\":\"당신의 제안에 에프넬이 의외라는 듯 눈썹을 올리고 슬쩍 봉인 틈을 비집어 연다. 안에서 나온 것은 황금이 아니라 소울정크 반응이 미약하게 새어 나오는 정체불명의 금속 조각이다. 에프넬은 순간 얼굴이 굳었다가 곧 능글맞은 웃음으로 덮는다. 위험수당은 두 배로 받아야겠다며 투덜대지만, 당신의 눈썰미를 인정하는 눈빛이 잠깐 스친다. 의뢰인이 중요한 사실을 숨기고 있다는 것만은 이제 분명해졌고, 두 사람은 경계를 한층 끌어올린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"달리는 열차의 밤\",\"text\":\"열차가 평원을 가르며 달리는 밤. 객차 지붕 위로 올라간 에프넬이 찬바람을 맞으며 창을 빙글 돌리고 있다. 말로는 위치 선정이 좋아서라지만 실은 승객들이 잠든 객차를 지켜 서 있는 것이다. 멀리 지평선 쪽에서 불길한 소울정크의 울음이 들려온다. 당신은 지붕 위 그녀 옆에 자리를 잡는다. 에프넬은 귀찮은 척하면서도 한쪽 자리를 슬쩍 비워 준다. 차가운 밤바람 속에서도 그녀의 눈은 한순간도 어둠 속 움직임을 놓치지 않으며, 당신의 존재를 슬쩍 의식하는 눈치다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"승객 객차에 남아 사람들을 안심시킨다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"에프넬과 함께 지붕에서 적을 기다린다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"선두 차량 기관실부터 확인하러 간다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":60,\"type\":\"story\",\"title\":\"겁먹은 아이의 손\",\"text\":\"당신이 객차에서 사람들을 달래는 동안, 구석에서 울음을 참던 어린 승객이 당신 소매를 붙든다. 소란을 들은 에프넬이 지붕에서 내려와 아이를 보더니 투덜거리면서도 시선을 피한다. 우는 건 요금 외 서비스라는 둥 말하면서 주머니 속 사탕을 건넨다. 아이의 눈빛 앞에서 그녀는 또 지고 만다. 당신과 눈이 마주치자 에프넬은 아니라고 소리친다. 당신의 다정함이 낯설다는 듯 그녀는 괜히 헛기침을 하고, 그 표정을 보며 당신은 웃음을 참느라 애를 먹는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"소울정크 습격\",\"text\":\"굉음과 함께 선로 양옆에서 소울정크 무리가 솟구친다. 열차는 속도를 늦출 수 없고, 에프넬은 지붕에서 창을 뽑아 들며 사망 플래그 같은 소리 하지 말라고 외친다. 체술과 창술이 뒤섞인 변칙적인 움직임으로 놈들을 걷어차 떨구지만 수가 너무 많다. 당신은 객차 연결부를 지키며 그녀의 등을 맡는다. 에프넬의 목소리에 진짜 긴장이 섞인다. 위기 앞에서도 입은 쉬지 않고 놈들을 비웃지만, 호흡이 점점 거칠어지는 것을 당신은 분명히 느낀다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"연결부를 끊어 화물칸을 지키는 데 집중한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_2\",\"text\":\"에프넬과 호흡을 맞춰 적의 중심을 함께 친다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_3\",\"text\":\"승객을 먼저 대피시키고 합류하겠다고 한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"두 개의 창끝\",\"text\":\"당신의 신호에 맞춰 에프넬이 돌진하고, 당신이 옆을 막아 길을 연다. 둘의 호흡이 맞아떨어지자 소울정크 무리의 중심이 한 번에 무너진다. 에프넬은 숨을 몰아쉬며 방금 건 공동 작업 수수료가 붙는다고 낄낄댄다. 하지만 창을 쥔 손에는 힘이 풀려 있고, 당신이 괜찮냐고 묻자 혀를 차며 고개를 돌린다. 소울정크 무리의 잔해가 흩어지는 가운데 열차는 한결 안정을 되찾고, 승객들의 안도 섞인 숨소리가 객차 안에 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"숨어 있던 배신자\",\"text\":\"습격이 잦아들 무렵, 화물칸 앞에서 상인 조합 대표가 봉인을 열려 하고 있다. 그는 소울정크를 일부러 불러들여 호위를 소모시키려 했던 것이다. 에프넬은 차갑게 식은 목소리로 한 푼도 안 깎아줄 거라며 창끝을 겨눈다. 대표가 돈을 두 배로 주겠다고 매달리자 그녀의 입꼬리가 아슬아슬하게 올라간다. 당신은 두 사람 사이에서 어느 쪽으로 움직일지 지켜본다. 돈이 전부라고 떠들던 그녀가 사람의 탐욕 앞에서 보이는 분노는 어딘가 평소와 사뭇 다르고, 당신의 선택이 결말을 좌우한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"대표를 제압하고 증거를 확보한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"에프넬에게 처리를 맡기고 승객을 지킨다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_3\",\"text\":\"두 배 보수 제안을 일단 들어 보는 척한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":440,\"type\":\"story\",\"title\":\"돈의 값어치\",\"text\":\"당신의 말에 대표가 안도하는 사이, 에프넬이 당신을 흘끗 보더니 풉 하고 웃음을 터뜨린다. 연기인 걸 눈치챈 것이다. 그녀는 지켜지지 않는 돈은 돈이 아니라며 대표의 멱살을 잡아 올린다. 돈은 배신하지 않는다던 그녀의 신조가 사람을 배신하는 인간 앞에서 처음으로 뒤집히는 순간이다. 한바탕 소동이 정리되자 객차에는 어색하면서도 후련한 공기가 흐르고, 에프넬은 모른 척 창밖으로 고개를 돌려 버린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"종착역의 새벽\",\"text\":\"새벽빛이 밝아 오는 종착역. 승객들은 모두 무사히 내렸고, 대표는 별숲리그 감시관에게 인계되었다. 에프넬은 플랫폼 벤치에 널브러져 보수 정산서를 들여다본다. 위험수당이 붙은 숫자를 세며 입이 귀에 걸렸지만, 정작 승객 가족들의 감사 인사 앞에서는 도망치듯 고개를 숙인다. 당신은 그녀 옆에 앉아 이 소동의 끝을 함께 맞는다. 밤새 이어진 긴장이 풀리자 몸이 천근같이 무겁지만, 그녀는 승객 수를 몰래 세어 보며 한 명도 빠지지 않았음을 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"정산의 시간\",\"text\":\"정산서를 접던 에프넬이 문득 당신에게 보수의 일부를 쓱 내민다. 공동 작업 몫이라며 퉁명스럽게 말하지만 귀끝이 붉다. 돈은 네드 컴퍼니를 부수는 수단이라던 그녀가 이번에는 그 돈을 사람에게 나누고 있다. 당신은 그 마음을 받을지, 모른 척 웃어넘길지 선택할 수 있다. 에프넬은 이상한 의미 부여 하지 말라고 미리 못을 박는다. 늘 돈을 쫓는 그녀가 스스로 돈을 내미는 일은 극히 드문 일이어서, 둘 사이의 공기가 묘하게 어색해진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"고맙다며 받고 밥을 사겠다고 한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_2\",\"text\":\"몫은 사양하고 수고했다고 말한다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_3\",\"text\":\"적다고 투덜대 에프넬을 놀려 본다\",\"varOps\":[{\"var\":\"성과\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"돌아오는 길\",\"text\":\"아르카디아 렐름으로 돌아가는 길. 에프넬은 느긋하게 하품하며 오늘은 일했으니 사흘은 안 움직일 거라고 선언한다. 하지만 걸음걸이는 평소보다 가볍다. 지평선 위로 공백의 흰 빛이 아득히 보이자 그녀는 잠시 말이 없어진다. 당신은 조용히 그녀 곁을 걷는다. 에프넬은 다음 의뢰도 보수 좋은 걸로만 가져오라고 못 박는다. 이번 의뢰는 끝났지만 둘의 여정은 계속되고, 당신은 그녀의 한결 가벼워진 발걸음 속에서 작은 변화를 읽는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"성과\",\"min\":8,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"성과\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"완벽한 호위, 최고의 정산\",\"text\":\"승객과 화물, 호위 모두 흠 하나 없이 끝낸 최고의 결과. 조합은 사례금까지 얹어 주었고 에프넬은 지갑을 끌어안고 행복해한다. 하지만 밤이 되자 그녀는 당신 방문을 두드려 사례금 일부로 사 온 간식을 던지듯 건넨다. 오늘은 같이 일한 값이라고 말하면서도 시선은 딴 곳이다. 당신은 그 서투른 인정이 오늘의 진짜 보수임을 안다. 이런 날이 계속된다면 의뢰 따위 매번 받아도 나쁘지 않겠다는 생각이 슬며시 고개를 든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"적당히 남는 장사\",\"text\":\"큰 사고 없이 의뢰를 마쳤다. 보수는 기대보다 약간 모자랐지만 에프넬은 그럭저럭 남는 장사였다며 투덜대면서도 만족스러운 표정이다. 당신과 나란히 노을 진 역을 걸으며 다음엔 더 비싼 의뢰만 받자고 떠든다. 하지만 지켜낸 승객의 인사를 떠올리는 그녀의 입가에는 은근한 미소가 남아 있다. 큰 소란 없이 무난히 끝난 하루였기에 오히려 둘 사이에는 편안한 침묵이 오래 머문다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"깎인 수당, 남은 찜찜함\",\"text\":\"일은 마쳤지만 허술한 대응으로 위험수당이 크게 깎였다. 에프넬은 정산서를 구기며 한숨을 쉬고는 공짜 노동이었다고 빈정거린다. 그래도 승객들이 무사한 것만은 다행인 듯, 당신에게 다음엔 손발 좀 맞추자며 퉁명스럽게 말한다. 아쉬움이 남지만 둘의 호흡을 다듬을 다음 기회가 있다는 뜻이기도 하다. 다음에는 더 잘해 보자는 말이 입 밖으로 나오지는 않았지만 서로 같은 마음임을 둘 다 알고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '황금 열차 호위전 - 돈 냄새 나는 의뢰'
);

-- 09. [에프넬] 버려진 창고의 N 마크 - 네드 컴퍼니의 흔적
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '버려진 창고의 N 마크 - 네드 컴퍼니의 흔적', 'published', 0, '{\"vars\":[{\"name\":\"단서\",\"initial\":0},{\"name\":\"경계\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"익명의 제보\",\"text\":\"아르카디아 렐름 외곽, 밤. 숙소 문틈에 끼워진 익명의 쪽지에는 폐창고 좌표와 N이라는 글자만 적혀 있다. 에프넬은 쪽지를 구기려다 N 마크 모양을 알아보고 손을 멈춘다. 네드 컴퍼니의 상징이다. 평소의 빈정거림이 뚝 끊기고 목소리가 낮아진다. 당신은 협력자로서 그녀가 혼자 뛰쳐나가지 않도록 곁에서 상황을 살핀다. 에프넬은 함정일 가능성이 높다며 정보료부터 따진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"폐창고 앞\",\"text\":\"달빛 아래 녹슨 폐창고. 문 자물쇠는 최근에 누군가 부순 흔적이 있다. 에프넬은 창끝으로 문을 밀어 열며 이런 데는 항상 사망 플래그가 서 있다고 중얼거린다. 안쪽에서 희미한 기계 소음과 약품 냄새가 흘러나온다. 그녀의 손끝이 아주 조금 떨리는 것을 당신은 놓치지 않는다. 에프넬은 들켰냐는 듯 코웃음 치며 앞장선다. 이 안에서 무엇을 보게 되든 끝까지 곁에 있기로 마음먹은 당신은 조심스레 그림자 속으로 발을 들인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"에프넬 곁에 붙어 같이 천천히 들어간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_2\",\"text\":\"먼저 주변에 덫이 있는지 살핀다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_3\",\"text\":\"빠른 조사를 위해 둘이 나뉘어 움직인다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":250,\"type\":\"story\",\"title\":\"숨겨진 센서\",\"text\":\"당신이 바닥을 살피자 문턱 아래에 가느다란 감응선이 숨겨져 있다. 에프넬은 눈을 가늘게 뜨고 이건 소울정크용 경보라고 낮게 중얼거린다. 선을 피해 지나가는 동안 그녀는 당신의 신중함이 마음에 든다는 듯 아니꼬운 표정으로 칭찬을 삼킨다. 하지만 이 센서가 누군가 이곳을 지키고 있다는 증거임을 둘 다 안다. 센서를 무사히 피한 두 사람은 한결 조심스러운 걸음으로 창고 안쪽을 향해 계속 나아간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"빈 연구 선반\",\"text\":\"창고 안쪽에는 약품병이 줄지어 놓인 선반과 뜯긴 서류 더미가 있다. 대부분 불에 그슬렸지만 실험체 관리번호가 적힌 표 한 장이 남아 있다. 에프넬은 번호를 훑다가 갑자기 종이를 쥔 손을 멈춘다. 그녀 몸의 실험 코드와 같은 형식이다. 애써 태연한 척 시꺼라고 중얼거리는 그녀를 당신은 조용히 바라본다. 정보 한 장이 때로는 칼날보다 날카롭다는 것을 알기에, 당신은 그녀가 마음을 추스를 때까지 서두르지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"서류를 먼저 챙겨 분석에 쓰자고 한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"괜찮냐고 에프넬에게 먼저 묻는다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1},{\"var\":\"단서\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"침착하자며 다른 선반도 마저 뒤진다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"걱정은 사절\",\"text\":\"괜찮냐는 말에 에프넬이 발끈하며 쏘아본다. 동정받는 건 질색이라면서도 잠시 후 목소리가 누그러든다. 공짜 위로는 받지 않는다고 하지만 당신이 대답 없이 곁에 서 있자 한숨을 쉰다. 그녀는 서류 한 장을 접어 당신 손에 쥐여 주며 그냥 같이 읽어 달라고 아주 작게 말한다. 그 목소리에는 평소의 빈정거림이 하나도 섞여 있지 않다. 두 사람은 말없이 종이 위의 글자를 따라 읽으며 그림자처럼 조용한 시간을 나눈다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"어둠 속의 인기척\",\"text\":\"창고 깊숙한 곳에서 금속이 끌리는 소리가 난다. 천장 아래 그림자 속에 네드 컴퍼니 마크가 새겨진 경비 기계 두 대가 눈을 켠다. 에프넬은 창을 뽑아 들고 이런 건 폐기 처분이 제 취미라며 앞으로 튀어나간다. 변칙적인 체술이 기계 사이를 가르지만 한 대가 당신 쪽으로 방향을 튼다. 당신은 순간적으로 대응해야 한다. 전투의 소음 속에서도 에프넬의 눈은 오직 기계의 관절 틈만 노리고, 당신은 그 집중력에 감탄하면서도 긴장을 놓지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"기계의 약점을 찾아 에프넬에게 외쳐 알린다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"경계\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_2\",\"text\":\"몸으로 막고 에프넬이 끝낼 틈을 만든다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_3\",\"text\":\"퇴로 확보를 위해 입구를 지킨다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"넌 바보냐\",\"text\":\"당신이 기계의 일격을 막아 낸 순간, 에프넬이 소리를 지르며 기계를 창으로 꿰뚫는다. 불꽃이 튀는 가운데 그녀는 미쳤냐고 화를 내지만 눈가는 파랗게 질려 있다. 공짜로 부려먹을 노예가 사라지면 곤란하다는 변명이 평소보다 한참 떨린다. 당신은 상처가 크지 않음을 보이며 웃어 보인다. 상처가 얕다는 것을 확인하고서야 그녀는 숨을 길게 내쉬며 어깨에서 힘을 뺀다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"기록실의 문\",\"text\":\"기계가 멈추자 안쪽 벽에 숨겨진 기록실 문이 드러난다. 잠금장치에는 실험체 번호를 입력해야 한다고 적혀 있다. 에프넬은 한동안 문을 노려보다가 쯧 하고 혀를 찬다. 자기 번호를 입력하면 열릴지도 모른다는 걸 알지만 그 숫자를 입력하는 건 자신이 실패작임을 인정하는 일 같아서다. 당신은 그녀의 선택을 기다린다. 창고 안의 공기가 한층 무거워졌고, 당신은 그녀가 내릴 선택이 얼마나 무거운지 숨을 죽이고 기다린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"대신 입력해 주겠다고 손을 내민다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_2\",\"text\":\"에프넬이 스스로 정하게 기다려 준다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"경계\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_3\",\"text\":\"위험하니 다른 방법을 찾자고 말린다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"내 번호는 내가\",\"text\":\"한참의 침묵 끝에 에프넬이 직접 코드를 입력한다. 이건 내 거야, 아무도 안 뺏어가라고 낮게 중얼거린다. 문이 열리며 오래된 먼지가 흩날린다. 그녀의 눈이 아주 잠깐 젖어 보이지만 곧 입꼬리를 올려 빈정거린다. 당신이 기다려 준 시간만큼, 그녀는 한 걸음 더 용기를 낸 것이다. 문틈에서 흘러나온 먼지 낀 공기 속에 오래된 시간이 고여 있고, 당신은 말없이 그녀 뒤를 따라 들어선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"남겨진 기록\",\"text\":\"기록실에는 폐기된 프로젝트의 보고서와 낡은 녹음기가 남아 있다. 보고서 끝에는 이 시설이 몇 달 전 이미 이동했고 이곳은 미끼였다는 메모가 적혀 있다. 누군가 일부러 에프넬을 이곳으로 불러들인 것이다. 에프넬은 서류를 손에 쥔 채 이를 악문다. 켄트와 네드 컴퍼니로 이어지는 새로운 단서가 단 한 줄 적혀 있다. 모든 것이 누군가의 계획 안에 있었다는 사실이 서늘하게 다가오고, 에프넬은 종이를 쥔 손에 점점 힘을 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"창고를 나서며\",\"text\":\"창고를 빠져나오자 새벽바람이 두 사람을 맞는다. 에프넬은 서류를 품에 넣고 한동안 말없이 하늘을 올려다본다. 공백의 흰 빛이 지평선 끝에 어른거린다. 오늘 얻은 정보가 얼마나 값어치 있는지 계산하는 척하지만 어깨가 조금 가라앉아 있다. 당신은 그녀 옆에서 걸음을 맞춘다. 에프넬은 이 정보 값은 나중에 받아낼 거라고 퉁명스럽게 덧붙인다. 오늘 밤 둘이 함께 본 것이 앞으로의 길을 바꿀지도 모른다는 예감이 새벽 공기 속에 조용히 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"이 단서를 별숲리그에 함께 보고하자고 제안한다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1},{\"var\":\"단서\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_2\",\"text\":\"일단 둘만 알고 더 조사해 보자고 말한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_3\",\"text\":\"오늘은 푹 쉬고 내일 정리하자고 한다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"정보료 청구서\",\"text\":\"숙소로 돌아온 에프넬은 침대에 대자로 눕더니 정보료 청구서를 쓰는 시늉을 한다. 하지만 펜은 한 글자도 쓰지 못하고 천장만 바라본다. 당신이 곁에 앉자 그녀는 귀찮은 듯 손을 휘저으면서도 쫓아내지 않는다. 오늘 밤은 정리도, 계산도 하기 싫은 모양이다. 당신은 조용히 옆에서 시간을 보낸다. 오늘만큼은 평소처럼 농담으로 분위기를 풀 기운도 없는지, 그녀는 한참을 조용히 앉아 있을 뿐이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":8,\"max\":null},{\"var\":\"경계\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"진짜 추적의 시작\",\"text\":\"수집한 단서와 신중함 덕에 네드 컴퍼니의 이동 경로 일부를 확인했다. 에프넬은 지도 위에 핀을 꽂으며 이제 시작이라고 날카롭게 웃는다. 정보료는 나중에 받겠다던 그녀가 당신에게 자기 몫의 단서를 먼저 보여 주며 같이 가자고 중얼거린다. 복수는 혼자 하는 거라던 그녀가, 처음으로 함께를 입에 올린 밤이다. 이제 쫓기는 쪽이 아니라 쫓는 쪽이라는 확신이 두 사람의 걸음에 단단한 힘을 실어 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"반쪽짜리 지도\",\"text\":\"단서는 모았지만 몇몇 부분이 비어 있다. 에프넬은 반쪽짜리 지도를 펼쳐 보며 절반이면 절반만큼 뛰면 된다고 어깨를 으쓱한다. 아직 다 알아내진 못했지만 방향은 잡았다. 그녀는 당신에게 다음에도 같이 가 줄 거냐고 빈정거림에 감춘 질문을 던진다. 당신의 대답이 곧 다음 조사의 시작이다. 아직 안개 속이지만 같은 방향을 보고 있다는 사실만으로도 앞으로의 길이 그리 어둡지 않게 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"텅 빈 미끼\",\"text\":\"미끼일 뿐이었다는 사실만 확인하고 창고를 떠난다. 에프넬은 헛걸음이었다고 신경질적으로 투덜대지만 곧 한숨 섞인 목소리로 그래도 다 폐기하긴 했네라고 중얼거린다. 얻은 것은 적지만 네드 컴퍼니가 아직 움직이고 있음을 알았다. 당신이 곁에 있었다는 것만은 그녀에게 조금이나마 위안이었다. 그래도 다음 단서를 찾을 힘만은 아직 남아 있고, 두 사람은 서로 말없이 같은 결의를 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n5\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"단서\",\"initial\":0},{\"name\":\"경계\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"익명의 제보\",\"text\":\"아르카디아 렐름 외곽, 밤. 숙소 문틈에 끼워진 익명의 쪽지에는 폐창고 좌표와 N이라는 글자만 적혀 있다. 에프넬은 쪽지를 구기려다 N 마크 모양을 알아보고 손을 멈춘다. 네드 컴퍼니의 상징이다. 평소의 빈정거림이 뚝 끊기고 목소리가 낮아진다. 당신은 협력자로서 그녀가 혼자 뛰쳐나가지 않도록 곁에서 상황을 살핀다. 에프넬은 함정일 가능성이 높다며 정보료부터 따진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"폐창고 앞\",\"text\":\"달빛 아래 녹슨 폐창고. 문 자물쇠는 최근에 누군가 부순 흔적이 있다. 에프넬은 창끝으로 문을 밀어 열며 이런 데는 항상 사망 플래그가 서 있다고 중얼거린다. 안쪽에서 희미한 기계 소음과 약품 냄새가 흘러나온다. 그녀의 손끝이 아주 조금 떨리는 것을 당신은 놓치지 않는다. 에프넬은 들켰냐는 듯 코웃음 치며 앞장선다. 이 안에서 무엇을 보게 되든 끝까지 곁에 있기로 마음먹은 당신은 조심스레 그림자 속으로 발을 들인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"에프넬 곁에 붙어 같이 천천히 들어간다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_2\",\"text\":\"먼저 주변에 덫이 있는지 살핀다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_3\",\"text\":\"빠른 조사를 위해 둘이 나뉘어 움직인다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":250,\"type\":\"story\",\"title\":\"숨겨진 센서\",\"text\":\"당신이 바닥을 살피자 문턱 아래에 가느다란 감응선이 숨겨져 있다. 에프넬은 눈을 가늘게 뜨고 이건 소울정크용 경보라고 낮게 중얼거린다. 선을 피해 지나가는 동안 그녀는 당신의 신중함이 마음에 든다는 듯 아니꼬운 표정으로 칭찬을 삼킨다. 하지만 이 센서가 누군가 이곳을 지키고 있다는 증거임을 둘 다 안다. 센서를 무사히 피한 두 사람은 한결 조심스러운 걸음으로 창고 안쪽을 향해 계속 나아간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"빈 연구 선반\",\"text\":\"창고 안쪽에는 약품병이 줄지어 놓인 선반과 뜯긴 서류 더미가 있다. 대부분 불에 그슬렸지만 실험체 관리번호가 적힌 표 한 장이 남아 있다. 에프넬은 번호를 훑다가 갑자기 종이를 쥔 손을 멈춘다. 그녀 몸의 실험 코드와 같은 형식이다. 애써 태연한 척 시꺼라고 중얼거리는 그녀를 당신은 조용히 바라본다. 정보 한 장이 때로는 칼날보다 날카롭다는 것을 알기에, 당신은 그녀가 마음을 추스를 때까지 서두르지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"서류를 먼저 챙겨 분석에 쓰자고 한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"괜찮냐고 에프넬에게 먼저 묻는다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1},{\"var\":\"단서\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"침착하자며 다른 선반도 마저 뒤진다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"걱정은 사절\",\"text\":\"괜찮냐는 말에 에프넬이 발끈하며 쏘아본다. 동정받는 건 질색이라면서도 잠시 후 목소리가 누그러든다. 공짜 위로는 받지 않는다고 하지만 당신이 대답 없이 곁에 서 있자 한숨을 쉰다. 그녀는 서류 한 장을 접어 당신 손에 쥐여 주며 그냥 같이 읽어 달라고 아주 작게 말한다. 그 목소리에는 평소의 빈정거림이 하나도 섞여 있지 않다. 두 사람은 말없이 종이 위의 글자를 따라 읽으며 그림자처럼 조용한 시간을 나눈다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"어둠 속의 인기척\",\"text\":\"창고 깊숙한 곳에서 금속이 끌리는 소리가 난다. 천장 아래 그림자 속에 네드 컴퍼니 마크가 새겨진 경비 기계 두 대가 눈을 켠다. 에프넬은 창을 뽑아 들고 이런 건 폐기 처분이 제 취미라며 앞으로 튀어나간다. 변칙적인 체술이 기계 사이를 가르지만 한 대가 당신 쪽으로 방향을 튼다. 당신은 순간적으로 대응해야 한다. 전투의 소음 속에서도 에프넬의 눈은 오직 기계의 관절 틈만 노리고, 당신은 그 집중력에 감탄하면서도 긴장을 놓지 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"기계의 약점을 찾아 에프넬에게 외쳐 알린다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":1},{\"var\":\"경계\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_2\",\"text\":\"몸으로 막고 에프넬이 끝낼 틈을 만든다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_3\",\"text\":\"퇴로 확보를 위해 입구를 지킨다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"넌 바보냐\",\"text\":\"당신이 기계의 일격을 막아 낸 순간, 에프넬이 소리를 지르며 기계를 창으로 꿰뚫는다. 불꽃이 튀는 가운데 그녀는 미쳤냐고 화를 내지만 눈가는 파랗게 질려 있다. 공짜로 부려먹을 노예가 사라지면 곤란하다는 변명이 평소보다 한참 떨린다. 당신은 상처가 크지 않음을 보이며 웃어 보인다. 상처가 얕다는 것을 확인하고서야 그녀는 숨을 길게 내쉬며 어깨에서 힘을 뺀다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"기록실의 문\",\"text\":\"기계가 멈추자 안쪽 벽에 숨겨진 기록실 문이 드러난다. 잠금장치에는 실험체 번호를 입력해야 한다고 적혀 있다. 에프넬은 한동안 문을 노려보다가 쯧 하고 혀를 찬다. 자기 번호를 입력하면 열릴지도 모른다는 걸 알지만 그 숫자를 입력하는 건 자신이 실패작임을 인정하는 일 같아서다. 당신은 그녀의 선택을 기다린다. 창고 안의 공기가 한층 무거워졌고, 당신은 그녀가 내릴 선택이 얼마나 무거운지 숨을 죽이고 기다린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"대신 입력해 주겠다고 손을 내민다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_2\",\"text\":\"에프넬이 스스로 정하게 기다려 준다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"경계\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_3\",\"text\":\"위험하니 다른 방법을 찾자고 말린다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"내 번호는 내가\",\"text\":\"한참의 침묵 끝에 에프넬이 직접 코드를 입력한다. 이건 내 거야, 아무도 안 뺏어가라고 낮게 중얼거린다. 문이 열리며 오래된 먼지가 흩날린다. 그녀의 눈이 아주 잠깐 젖어 보이지만 곧 입꼬리를 올려 빈정거린다. 당신이 기다려 준 시간만큼, 그녀는 한 걸음 더 용기를 낸 것이다. 문틈에서 흘러나온 먼지 낀 공기 속에 오래된 시간이 고여 있고, 당신은 말없이 그녀 뒤를 따라 들어선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"남겨진 기록\",\"text\":\"기록실에는 폐기된 프로젝트의 보고서와 낡은 녹음기가 남아 있다. 보고서 끝에는 이 시설이 몇 달 전 이미 이동했고 이곳은 미끼였다는 메모가 적혀 있다. 누군가 일부러 에프넬을 이곳으로 불러들인 것이다. 에프넬은 서류를 손에 쥔 채 이를 악문다. 켄트와 네드 컴퍼니로 이어지는 새로운 단서가 단 한 줄 적혀 있다. 모든 것이 누군가의 계획 안에 있었다는 사실이 서늘하게 다가오고, 에프넬은 종이를 쥔 손에 점점 힘을 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"창고를 나서며\",\"text\":\"창고를 빠져나오자 새벽바람이 두 사람을 맞는다. 에프넬은 서류를 품에 넣고 한동안 말없이 하늘을 올려다본다. 공백의 흰 빛이 지평선 끝에 어른거린다. 오늘 얻은 정보가 얼마나 값어치 있는지 계산하는 척하지만 어깨가 조금 가라앉아 있다. 당신은 그녀 옆에서 걸음을 맞춘다. 에프넬은 이 정보 값은 나중에 받아낼 거라고 퉁명스럽게 덧붙인다. 오늘 밤 둘이 함께 본 것이 앞으로의 길을 바꿀지도 모른다는 예감이 새벽 공기 속에 조용히 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"이 단서를 별숲리그에 함께 보고하자고 제안한다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":1},{\"var\":\"단서\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_2\",\"text\":\"일단 둘만 알고 더 조사해 보자고 말한다\",\"varOps\":[{\"var\":\"단서\",\"op\":\"add\",\"value\":2},{\"var\":\"경계\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_3\",\"text\":\"오늘은 푹 쉬고 내일 정리하자고 한다\",\"varOps\":[{\"var\":\"경계\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"정보료 청구서\",\"text\":\"숙소로 돌아온 에프넬은 침대에 대자로 눕더니 정보료 청구서를 쓰는 시늉을 한다. 하지만 펜은 한 글자도 쓰지 못하고 천장만 바라본다. 당신이 곁에 앉자 그녀는 귀찮은 듯 손을 휘저으면서도 쫓아내지 않는다. 오늘 밤은 정리도, 계산도 하기 싫은 모양이다. 당신은 조용히 옆에서 시간을 보낸다. 오늘만큼은 평소처럼 농담으로 분위기를 풀 기운도 없는지, 그녀는 한참을 조용히 앉아 있을 뿐이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":8,\"max\":null},{\"var\":\"경계\",\"min\":6,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"단서\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"진짜 추적의 시작\",\"text\":\"수집한 단서와 신중함 덕에 네드 컴퍼니의 이동 경로 일부를 확인했다. 에프넬은 지도 위에 핀을 꽂으며 이제 시작이라고 날카롭게 웃는다. 정보료는 나중에 받겠다던 그녀가 당신에게 자기 몫의 단서를 먼저 보여 주며 같이 가자고 중얼거린다. 복수는 혼자 하는 거라던 그녀가, 처음으로 함께를 입에 올린 밤이다. 이제 쫓기는 쪽이 아니라 쫓는 쪽이라는 확신이 두 사람의 걸음에 단단한 힘을 실어 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"반쪽짜리 지도\",\"text\":\"단서는 모았지만 몇몇 부분이 비어 있다. 에프넬은 반쪽짜리 지도를 펼쳐 보며 절반이면 절반만큼 뛰면 된다고 어깨를 으쓱한다. 아직 다 알아내진 못했지만 방향은 잡았다. 그녀는 당신에게 다음에도 같이 가 줄 거냐고 빈정거림에 감춘 질문을 던진다. 당신의 대답이 곧 다음 조사의 시작이다. 아직 안개 속이지만 같은 방향을 보고 있다는 사실만으로도 앞으로의 길이 그리 어둡지 않게 느껴진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"텅 빈 미끼\",\"text\":\"미끼일 뿐이었다는 사실만 확인하고 창고를 떠난다. 에프넬은 헛걸음이었다고 신경질적으로 투덜대지만 곧 한숨 섞인 목소리로 그래도 다 폐기하긴 했네라고 중얼거린다. 얻은 것은 적지만 네드 컴퍼니가 아직 움직이고 있음을 알았다. 당신이 곁에 있었다는 것만은 그녀에게 조금이나마 위안이었다. 그래도 다음 단서를 찾을 힘만은 아직 남아 있고, 두 사람은 서로 말없이 같은 결의를 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n4\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n5\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '버려진 창고의 N 마크 - 네드 컴퍼니의 흔적'
);

-- 10. [에프넬] 남부 빈민가의 꼬마 의뢰인들
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '남부 빈민가의 꼬마 의뢰인들', 'published', 0, '{\"vars\":[{\"name\":\"신뢰\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"골목 끝의 꼬마 도둑\",\"text\":\"아르카디아 렐름 시장 뒷골목. 에프넬의 지갑을 노리던 어린 소매치기가 당신의 손에 붙잡혔다. 꼬질꼬질한 아이는 눈을 부릅뜨고 배고픈 게 죄냐며 대든다. 에프넬은 팔짱을 낀 채 돈 내놔 하고 빈정거리지만, 아이의 마른 손목을 본 순간 시선이 한참 머문다. 당신은 아이를 놓아줄지, 붙잡아 둘지 곁에서 지켜본다. 그녀의 농담에서 평소의 여유가 슬며시 사라진다. 당신의 손 안에서 아이는 발버둥을 멈추고 그녀를 올려다본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"남부 출신의 낯익은 냄새\",\"text\":\"아이는 클라우드림 남부 빈민가에서 동생들과 함께 살고 있다고 털어놓는다. 에프넬의 표정이 딱딱하게 굳는다. 그곳은 그녀가 팔려 나가기 전 자란 동네다. 그녀는 흥미 없다는 듯 하품하지만 발걸음은 이미 아이의 뒤를 따르고 있다. 당신도 말없이 동행하며 시장의 소음이 사라지고 낡은 판자촌이 이어지는 길을 걷는다. 에프넬은 길 안내료는 외상이라며 중얼거린다. 낡은 골목 어귀마다 빨랫줄과 깨진 창문이 이어지고, 그녀의 입은 점점 말수가 줄어든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"아이에게 먹을 것을 먼저 사 주자고 한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"일단 집이 어떤지 직접 보고 판단하자고 한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"소매치기는 나쁜 짓이라고 먼저 타이른다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"공짜는 아니거든\",\"text\":\"에프넬은 시장 노점에서 빵과 수프를 한가득 사 오며 이건 선불이라고 투덜댄다. 계산하는 손길은 누구보다 빠르고, 거스름돈을 세지 않고 주머니에 쑤셔 넣는다. 아이가 허겁지겁 먹는 동안 그녀는 뒤돌아 먼 곳을 본다. 당신은 그 등이 아주 조금 어깨너머로 떨리는 것을 본다. 다 먹으면 일해서 갚으라는 말에도 이미 따뜻한 장난기가 묻어 있다. 아이는 눈물이 맺힌 채 연신 고개를 끄덕이고, 그녀는 못 본 척 돌아서서 먼 하늘만 쳐다본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"무너져 가는 판자촌\",\"text\":\"빈민가 깊숙한 곳, 기울어진 판자집 안에 어린아이 서넛이 모여 있다. 지붕은 비가 샐 듯 구멍이 나 있고, 벽 한쪽에는 얼마 전 소울정크가 할퀴고 간 흔적이 남아 있다. 에프넬은 말없이 집 안을 둘러보다가 낡은 목마 장난감을 집어 든다. 그녀가 어릴 때 보던 것과 닮았다. 당신은 아이들의 눈빛이 에프넬에게 쏠리는 것을 지켜본다. 그녀는 대충 둘러댈 말을 찾지 못한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"아이들과 눈높이를 맞춰 앉아 이름을 묻는다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"에프넬에게 아이들을 어떻게 돕고 싶은지 묻는다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"먼저 지붕과 벽부터 고치자고 말한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"돕는 게 아니라고\",\"text\":\"당신의 질문에 에프넬은 발끈하며 돕는 게 아니라 투자라고 선언한다. 나중에 갚을 놈들이 이자까지 쳐서 갚게 할 거라며 눈을 흘기지만, 목소리에는 힘이 없다. 아이들이 그녀의 소매를 잡아당기자 말문이 막혀 투덜거리며 주저앉는다. 당신이 웃음을 참자 시꺼 착각하지 마라는 말이 허공에 흩어진다. 아이들의 시선이 그녀에게서 떠나지 않자 에프넬은 결국 참지 못하고 주저앉아 큰 한숨을 내쉰다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"수상한 후원자\",\"text\":\"해질 무렵, 말쑥한 차림의 남자가 판자촌에 나타나 아이들에게 일자리를 제안한다. 입에 발린 선의와 달콤한 약속이 가득하지만 에프넬의 눈은 날카롭게 가늘어진다. 그 말투와 서류의 문양이 어딘가 네드 컴퍼니의 인력 모집을 닮았기 때문이다. 아이들은 따뜻한 밥에 마음이 흔들린다. 당신은 에프넬이 억눌러 온 분노가 끓어오르는 것을 곁에서 느낀다. 아이들 앞에서 싸움을 벌일 수 없다는 사실이 그녀의 주먹을 더 세게 쥐게 만든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"남자를 따로 불러 서류를 확인한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_2\",\"text\":\"아이들에게 먼저 위험하다고 알려 준다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_3\",\"text\":\"에프넬이 직접 처리하게 맡겨 둔다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":60,\"type\":\"story\",\"title\":\"돈 냄새가 아니라 피 냄새\",\"text\":\"당신이 서류를 살피자 남자의 얼굴에 땀이 맺힌다. 문서 하단에는 지워지다 만 N 마크가 흐릿하게 남아 있다. 에프넬은 조용히 남자의 앞에 서서 낮은 목소리로 당신이 팔려 나간 애들 몇이나 되는지 아냐고 묻는다. 그 어조에 진짜 분노가 서려 있다. 남자는 변명도 못한 채 뒷걸음질 친다. 소란이 가라앉자 판자촌에는 한동안 숨죽인 정적이 흘렀고, 아이들은 놀란 눈으로 두 사람을 번갈아 본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"에프넬의 선택\",\"text\":\"남자를 몰아낸 뒤 에프넬은 아이들 앞에 선다. 말은 없고 한참 허공만 쳐다보더니 이윽고 지갑을 열어 든든한 돈뭉치를 꺼낸다. 그리고는 이건 대출이라고 연신 되풀이한다. 이자는 연 백 퍼센트라고 협박조로 말하지만 아이들의 눈빛 앞에서 또 지고 만다. 당신은 그 모습을 지켜보며 그녀가 부모에게 팔려 나갔던 어린 시절을 짐작한다. 돈은 배신하지 않는다던 그녀의 신조가 처음으로 누군가를 위해 흔쾌히 쓰이는 순간이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"그 돈이 아이들에게 오래가도록 방법을 함께 찾자고 한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"잘했다고 에프넬에게 솔직하게 말한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_3\",\"text\":\"나머지는 별숲리그에 맡기자고 제안한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"칭찬은 사절\",\"text\":\"잘했다는 한마디에 에프넬은 몸서리를 치며 소름 끼친다고 고함을 지른다. 하지만 귀끝이 새빨갛게 달아올라 있다. 아이들이 와 하고 웃자 그녀는 더 곤란한 표정으로 시꺼를 연발한다. 이런 순간이야말로 그녀가 가장 약해지는 때라는 걸 당신은 알고 있다. 둘은 잠시 서로 눈을 피한 채 가만히 서 있는다. 무심한 척하던 그녀의 가면이 한 겹 더 벗겨진 채, 두 사람 사이로 따뜻한 침묵이 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"마지막 빵 한 조각\",\"text\":\"밤이 깊고 아이들이 잠든 뒤, 에프넬은 판자집 문턱에 앉아 마지막 남은 빵을 반으로 쪼개 당신에게 내민다. 거창한 말은 없다. 어릴 때 이 동네에서 이런 빵 한 조각이 전부였다며 가볍게 웃지만 눈은 별 없는 하늘에 가 있다. 당신은 빵을 받아 들고 그녀 옆에 앉는다. 한참의 침묵 끝에 에프넬은 아주 작게 고마웠다고 중얼거리고 곧바로 못 들은 걸로 하라고 덧붙인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"별 없는 하늘 아래\",\"text\":\"빵을 나눠 먹은 뒤에도 에프넬은 일어나지 않고 판자촌의 낮은 지붕들을 바라본다. 이곳에서 처음 배운 것은 돈이 없으면 아무도 구해 주지 않는다는 사실이었다고 담담히 말한다. 하지만 이제 그녀는 그 돈으로 누군가를 구하는 쪽에 서 있다. 당신은 대답 대신 곁에 앉아 있다. 그녀가 가장 싫어하는 동정이 아니라 그저 같은 곳을 바라보는 동행으로서 밤공기를 나눈다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"새벽, 돌아가는 길\",\"text\":\"동이 트기 전, 두 사람은 아이들을 깨우지 않고 조용히 판자촌을 나선다. 에프넬은 지갑이 가벼워졌다며 한숨을 쉬지만 어깨는 이상하게 가볍다. 앞으로 한 달에 한 번은 들를 거라고 마치 사업 계획처럼 중얼거린다. 당신은 그 말이 약속임을 알고 있다. 남부의 지평선 너머 아침 햇살이 퍼져 나오는 가운데 에프넬은 뒤돌아 판자촌을 한 번 바라본다. 당신이 건넨 한마디 한마디를 그녀가 오래 기억하게 되리라는 예감이 새벽 공기 속에 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"신뢰\",\"min\":8,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"신뢰\",\"min\":5,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"작은 약속, 큰 안식처\",\"text\":\"몇 주 뒤, 판자촌의 지붕은 말끔히 수리되고 아이들은 정기적으로 배급을 받게 되었다. 에프넬은 이건 투자 수익이라며 영수증 따위를 흔들지만, 아이들이 달려와 안기는 순간 얼굴이 새빨개져 도망친다. 당신에게 슬쩍 다가와 다음 방문에는 같이 가 달라고 속삭인다. 돈이 사람을 지키는 방식을 아는 그녀의, 가장 따뜻한 날이다. 그 일이 이렇게 잘 풀린 건 순전히 당신 때문이라는 말은 끝까지 하지 않지만, 눈빛이 대신 말해 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"한 달에 한 번의 방문\",\"text\":\"아이들은 에프넬이 오는 날을 기다리게 되었다. 그녀는 매번 불평하며 짐을 한가득 지고 오고, 매번 아무것도 아니라고 잡아뗀다. 큰 변화는 아니지만 판자촌에는 새로운 웃음소리가 생겼다. 당신은 돌아오는 길에 그녀의 가벼운 발걸음을 보며 조용히 미소 짓는다. 돌아오는 길에 그녀는 간식 하나를 사 들고 아이들의 얼굴을 떠올리며 괜히 혼잣말로 투덜댄다. 당신은 모르는 척 고개를 끄덕여 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"닫힌 문, 열릴 틈\",\"text\":\"아이들은 아직 낯선 어른들에게 마음을 열지 못했고, 에프넬도 서투른 방식으로 거리를 두었다. 그녀는 돈만 두고 간 셈이라며 자조 섞인 농담을 던진다. 하지만 당신이 함께 있다는 사실은 그녀에게 작은 위로가 되었고, 다음번에는 조금 더 가까이 다가가 보자는 다짐이 두 사람 사이에 남는다. 그럼에도 아이들의 배는 채워졌고, 그것만으로도 이날은 의미가 있었다고 그녀는 마음속으로 계산한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"신뢰\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"골목 끝의 꼬마 도둑\",\"text\":\"아르카디아 렐름 시장 뒷골목. 에프넬의 지갑을 노리던 어린 소매치기가 당신의 손에 붙잡혔다. 꼬질꼬질한 아이는 눈을 부릅뜨고 배고픈 게 죄냐며 대든다. 에프넬은 팔짱을 낀 채 돈 내놔 하고 빈정거리지만, 아이의 마른 손목을 본 순간 시선이 한참 머문다. 당신은 아이를 놓아줄지, 붙잡아 둘지 곁에서 지켜본다. 그녀의 농담에서 평소의 여유가 슬며시 사라진다. 당신의 손 안에서 아이는 발버둥을 멈추고 그녀를 올려다본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"남부 출신의 낯익은 냄새\",\"text\":\"아이는 클라우드림 남부 빈민가에서 동생들과 함께 살고 있다고 털어놓는다. 에프넬의 표정이 딱딱하게 굳는다. 그곳은 그녀가 팔려 나가기 전 자란 동네다. 그녀는 흥미 없다는 듯 하품하지만 발걸음은 이미 아이의 뒤를 따르고 있다. 당신도 말없이 동행하며 시장의 소음이 사라지고 낡은 판자촌이 이어지는 길을 걷는다. 에프넬은 길 안내료는 외상이라며 중얼거린다. 낡은 골목 어귀마다 빨랫줄과 깨진 창문이 이어지고, 그녀의 입은 점점 말수가 줄어든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"아이에게 먹을 것을 먼저 사 주자고 한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"일단 집이 어떤지 직접 보고 판단하자고 한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"소매치기는 나쁜 짓이라고 먼저 타이른다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"공짜는 아니거든\",\"text\":\"에프넬은 시장 노점에서 빵과 수프를 한가득 사 오며 이건 선불이라고 투덜댄다. 계산하는 손길은 누구보다 빠르고, 거스름돈을 세지 않고 주머니에 쑤셔 넣는다. 아이가 허겁지겁 먹는 동안 그녀는 뒤돌아 먼 곳을 본다. 당신은 그 등이 아주 조금 어깨너머로 떨리는 것을 본다. 다 먹으면 일해서 갚으라는 말에도 이미 따뜻한 장난기가 묻어 있다. 아이는 눈물이 맺힌 채 연신 고개를 끄덕이고, 그녀는 못 본 척 돌아서서 먼 하늘만 쳐다본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"무너져 가는 판자촌\",\"text\":\"빈민가 깊숙한 곳, 기울어진 판자집 안에 어린아이 서넛이 모여 있다. 지붕은 비가 샐 듯 구멍이 나 있고, 벽 한쪽에는 얼마 전 소울정크가 할퀴고 간 흔적이 남아 있다. 에프넬은 말없이 집 안을 둘러보다가 낡은 목마 장난감을 집어 든다. 그녀가 어릴 때 보던 것과 닮았다. 당신은 아이들의 눈빛이 에프넬에게 쏠리는 것을 지켜본다. 그녀는 대충 둘러댈 말을 찾지 못한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"아이들과 눈높이를 맞춰 앉아 이름을 묻는다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"에프넬에게 아이들을 어떻게 돕고 싶은지 묻는다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"먼저 지붕과 벽부터 고치자고 말한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"돕는 게 아니라고\",\"text\":\"당신의 질문에 에프넬은 발끈하며 돕는 게 아니라 투자라고 선언한다. 나중에 갚을 놈들이 이자까지 쳐서 갚게 할 거라며 눈을 흘기지만, 목소리에는 힘이 없다. 아이들이 그녀의 소매를 잡아당기자 말문이 막혀 투덜거리며 주저앉는다. 당신이 웃음을 참자 시꺼 착각하지 마라는 말이 허공에 흩어진다. 아이들의 시선이 그녀에게서 떠나지 않자 에프넬은 결국 참지 못하고 주저앉아 큰 한숨을 내쉰다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"수상한 후원자\",\"text\":\"해질 무렵, 말쑥한 차림의 남자가 판자촌에 나타나 아이들에게 일자리를 제안한다. 입에 발린 선의와 달콤한 약속이 가득하지만 에프넬의 눈은 날카롭게 가늘어진다. 그 말투와 서류의 문양이 어딘가 네드 컴퍼니의 인력 모집을 닮았기 때문이다. 아이들은 따뜻한 밥에 마음이 흔들린다. 당신은 에프넬이 억눌러 온 분노가 끓어오르는 것을 곁에서 느낀다. 아이들 앞에서 싸움을 벌일 수 없다는 사실이 그녀의 주먹을 더 세게 쥐게 만든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"남자를 따로 불러 서류를 확인한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_2\",\"text\":\"아이들에게 먼저 위험하다고 알려 준다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_3\",\"text\":\"에프넬이 직접 처리하게 맡겨 둔다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":60,\"type\":\"story\",\"title\":\"돈 냄새가 아니라 피 냄새\",\"text\":\"당신이 서류를 살피자 남자의 얼굴에 땀이 맺힌다. 문서 하단에는 지워지다 만 N 마크가 흐릿하게 남아 있다. 에프넬은 조용히 남자의 앞에 서서 낮은 목소리로 당신이 팔려 나간 애들 몇이나 되는지 아냐고 묻는다. 그 어조에 진짜 분노가 서려 있다. 남자는 변명도 못한 채 뒷걸음질 친다. 소란이 가라앉자 판자촌에는 한동안 숨죽인 정적이 흘렀고, 아이들은 놀란 눈으로 두 사람을 번갈아 본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"에프넬의 선택\",\"text\":\"남자를 몰아낸 뒤 에프넬은 아이들 앞에 선다. 말은 없고 한참 허공만 쳐다보더니 이윽고 지갑을 열어 든든한 돈뭉치를 꺼낸다. 그리고는 이건 대출이라고 연신 되풀이한다. 이자는 연 백 퍼센트라고 협박조로 말하지만 아이들의 눈빛 앞에서 또 지고 만다. 당신은 그 모습을 지켜보며 그녀가 부모에게 팔려 나갔던 어린 시절을 짐작한다. 돈은 배신하지 않는다던 그녀의 신조가 처음으로 누군가를 위해 흔쾌히 쓰이는 순간이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"그 돈이 아이들에게 오래가도록 방법을 함께 찾자고 한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"잘했다고 에프넬에게 솔직하게 말한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_3\",\"text\":\"나머지는 별숲리그에 맡기자고 제안한다\",\"varOps\":[{\"var\":\"신뢰\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"칭찬은 사절\",\"text\":\"잘했다는 한마디에 에프넬은 몸서리를 치며 소름 끼친다고 고함을 지른다. 하지만 귀끝이 새빨갛게 달아올라 있다. 아이들이 와 하고 웃자 그녀는 더 곤란한 표정으로 시꺼를 연발한다. 이런 순간이야말로 그녀가 가장 약해지는 때라는 걸 당신은 알고 있다. 둘은 잠시 서로 눈을 피한 채 가만히 서 있는다. 무심한 척하던 그녀의 가면이 한 겹 더 벗겨진 채, 두 사람 사이로 따뜻한 침묵이 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"마지막 빵 한 조각\",\"text\":\"밤이 깊고 아이들이 잠든 뒤, 에프넬은 판자집 문턱에 앉아 마지막 남은 빵을 반으로 쪼개 당신에게 내민다. 거창한 말은 없다. 어릴 때 이 동네에서 이런 빵 한 조각이 전부였다며 가볍게 웃지만 눈은 별 없는 하늘에 가 있다. 당신은 빵을 받아 들고 그녀 옆에 앉는다. 한참의 침묵 끝에 에프넬은 아주 작게 고마웠다고 중얼거리고 곧바로 못 들은 걸로 하라고 덧붙인다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"별 없는 하늘 아래\",\"text\":\"빵을 나눠 먹은 뒤에도 에프넬은 일어나지 않고 판자촌의 낮은 지붕들을 바라본다. 이곳에서 처음 배운 것은 돈이 없으면 아무도 구해 주지 않는다는 사실이었다고 담담히 말한다. 하지만 이제 그녀는 그 돈으로 누군가를 구하는 쪽에 서 있다. 당신은 대답 대신 곁에 앉아 있다. 그녀가 가장 싫어하는 동정이 아니라 그저 같은 곳을 바라보는 동행으로서 밤공기를 나눈다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"새벽, 돌아가는 길\",\"text\":\"동이 트기 전, 두 사람은 아이들을 깨우지 않고 조용히 판자촌을 나선다. 에프넬은 지갑이 가벼워졌다며 한숨을 쉬지만 어깨는 이상하게 가볍다. 앞으로 한 달에 한 번은 들를 거라고 마치 사업 계획처럼 중얼거린다. 당신은 그 말이 약속임을 알고 있다. 남부의 지평선 너머 아침 햇살이 퍼져 나오는 가운데 에프넬은 뒤돌아 판자촌을 한 번 바라본다. 당신이 건넨 한마디 한마디를 그녀가 오래 기억하게 되리라는 예감이 새벽 공기 속에 번진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"신뢰\",\"min\":8,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"신뢰\",\"min\":5,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"작은 약속, 큰 안식처\",\"text\":\"몇 주 뒤, 판자촌의 지붕은 말끔히 수리되고 아이들은 정기적으로 배급을 받게 되었다. 에프넬은 이건 투자 수익이라며 영수증 따위를 흔들지만, 아이들이 달려와 안기는 순간 얼굴이 새빨개져 도망친다. 당신에게 슬쩍 다가와 다음 방문에는 같이 가 달라고 속삭인다. 돈이 사람을 지키는 방식을 아는 그녀의, 가장 따뜻한 날이다. 그 일이 이렇게 잘 풀린 건 순전히 당신 때문이라는 말은 끝까지 하지 않지만, 눈빛이 대신 말해 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"한 달에 한 번의 방문\",\"text\":\"아이들은 에프넬이 오는 날을 기다리게 되었다. 그녀는 매번 불평하며 짐을 한가득 지고 오고, 매번 아무것도 아니라고 잡아뗀다. 큰 변화는 아니지만 판자촌에는 새로운 웃음소리가 생겼다. 당신은 돌아오는 길에 그녀의 가벼운 발걸음을 보며 조용히 미소 짓는다. 돌아오는 길에 그녀는 간식 하나를 사 들고 아이들의 얼굴을 떠올리며 괜히 혼잣말로 투덜댄다. 당신은 모르는 척 고개를 끄덕여 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"닫힌 문, 열릴 틈\",\"text\":\"아이들은 아직 낯선 어른들에게 마음을 열지 못했고, 에프넬도 서투른 방식으로 거리를 두었다. 그녀는 돈만 두고 간 셈이라며 자조 섞인 농담을 던진다. 하지만 당신이 함께 있다는 사실은 그녀에게 작은 위로가 되었고, 다음번에는 조금 더 가까이 다가가 보자는 다짐이 두 사람 사이에 남는다. 그럼에도 아이들의 배는 채워졌고, 그것만으로도 이날은 의미가 있었다고 그녀는 마음속으로 계산한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '남부 빈민가의 꼬마 의뢰인들'
);

-- 11. [에프넬] 숙소 간식 도난 사건 - 범인은 이 중에 있다
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '숙소 간식 도난 사건 - 범인은 이 중에 있다', 'published', 0, '{\"vars\":[{\"name\":\"추리\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"사라진 푸딩\",\"text\":\"아르카디아 렐름 숙소의 아침. 공용 냉장고에 넣어 둔 하루의 특제 푸딩이 통째로 사라졌다. 하루는 울상으로 범인을 찾겠다고 선언하고, 소파에 널브러져 있던 에프넬은 귀를 막으며 시끄럽다고 투덜댄다. 그러나 사건에 현상금이 걸리자 눈이 번쩍 뜨인다. 당신은 하루의 부탁으로 조사에 합류한다. 에프넬은 푸딩 하나로 이 난리냐며 코웃음 치지만 어느새 수사 모드로 몸을 일으킨다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"현장 검증\",\"text\":\"냉장고 앞은 의외로 깨끗하다. 포장지 하나, 숟가락 하나 남아 있지 않다. 에프넬은 쭈그려 앉아 바닥의 가는 흔적을 손끝으로 훑으며 이건 프로의 솜씨라고 진지하게 중얼거린다. 하루는 옆에서 감탄하며 메모를 하고, 당신은 문틈에서 설탕 가루 몇 알을 발견한다. 사소한 사건인데도 에프넬의 장난기와 승부욕이 묘하게 뒤섞여 분위기가 점점 들뜬다. 용의자는 숙소에 있던 세 명이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"냉장고 주변 설탕 가루의 경로를 따라간다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"용의자들을 한 명씩 불러 알리바이를 묻는다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"에프넬이 먹은 건 아니냐고 슬쩍 떠본다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"설탕의 길\",\"text\":\"설탕 가루는 주방에서 복도를 거쳐 어느 방문 앞에서 끊겨 있다. 에프넬은 코를 킁킁거리며 이건 단 냄새에 미친 놈의 짓이라고 득의양양하게 속삭인다. 하루는 그 방이 누구 방이냐고 놀라 입을 가리고, 당신은 문 안쪽에서 들리는 우적우적 소리를 알아챈다. 에프넬은 낄낄대며 사망 플래그가 서 있는 건 범인 쪽이라고 말한다. 숙소 복도는 순식간에 수사극의 무대가 되어, 하루는 발끝을 들고 에프넬은 능청스럽게 문 앞으로 다가선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"첫 번째 용의자\",\"text\":\"복도 끝 방에서 졸린 눈의 동료가 나와 잠결에 억울하다고 호소한다. 에프넬은 알리바이의 허점을 사냥꾼처럼 파고들며 어젯밤 소등 후에 뭘 하고 있었냐고 능글맞게 압박한다. 하루는 그 말투에 눈치를 보며 진정하라고 뜯어말린다. 용의자는 정말 억울해 보이지만 입가에 푸른 얼룩이 묻어 있다. 당신은 대화 속에서 모순점을 찾을 수 있다. 에프넬은 용의자의 반응을 즐기듯 입꼬리를 올리며 취조실 분위기를 한껏 연출한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"입가의 푸른 얼룩이 푸딩 색과 다르다고 지적한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"하루가 만든 푸딩의 재료를 되짚어 본다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"일단 용의자를 풀어주고 다음 사람을 만난다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"하루의 푸딩 레시피\",\"text\":\"하루가 열심히 재료를 읊는 사이 에프넬은 하품을 삼키다가 갑자기 눈을 번쩍 뜬다. 우유와 달걀, 그리고 소울정크 열매를 갈아 넣었다는 말이 단서였다. 그 열매는 먹은 사람 입술을 보랏빛으로 물들이는 것으로 유명하다. 에프넬은 의기양양하게 이건 사건이 아니라 퍼즐이었다고 선언한다. 하루는 자신의 푸딩이 증거가 되었다는 사실에 뿌듯해하며 에프넬과 신나게 눈짓을 주고받는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"두 번째 용의자\",\"text\":\"다음 용의자는 숙소 지붕 위에서 낮잠을 자던 동료다. 에프넬이 사다리를 타고 올라가 깨우자 심술궂은 얼굴로 돈 되는 정보라도 주냐고 맞받아친다. 두 사람이 서로 보수를 흥정하는 와중에 하루는 눈물을 글썽이며 푸딩을 되찾고 싶다고 호소한다. 에프넬은 그 눈빛에 지고 만다. 사소한 서비스라며 마지못해 협조하지만 당신이 보기엔 이미 진심으로 푸딩 사건에 몰입하고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"하루를 안심시키며 증거부터 정리하자고 한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_2\",\"text\":\"에프넬의 흥정을 이용해 정보를 끌어낸다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_3\",\"text\":\"범인은 이미 정해졌다며 직감을 믿는다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"정보료는 푸딩 반쪽\",\"text\":\"당신의 제안으로 에프넬이 용의자에게 정보료 대신 되찾은 푸딩의 절반을 제시한다. 용의자는 흔들리는 눈빛으로 어젯밤 늦게 주방에서 수상한 그림자를 봤다고 털어놓는다. 하루는 이 방법이 통했다며 박수를 치고, 에프넬은 쓸데없이 약속 팔지 말라고 옆구리를 찌르지만 입꼬리는 올라가 있다. 에프넬은 빠르게 용의자 명단을 좁히고, 하루는 뒤에서 열심히 박수를 치며 응원을 보낸다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"한밤의 소동\",\"text\":\"추리가 막바지에 이르렀을 때 주방 쪽에서 쿵 하는 소리와 비명이 터진다. 달려가 보니 하루의 후배 소울워커가 푸딩 접시를 안은 채 얼어붙어 있다. 에프넬은 어랍쇼 하며 잡으려 하지만 상대는 도망치다가 소파 뒤로 구르고 말았다. 숙소는 순식간에 베개와 쿠션이 날아다니는 난장판이 된다. 당신은 혼란 속에서 상황을 정리해야 한다. 한순간에 수사극이 활극으로 변하자 에프넬은 오히려 신이 난 듯 소매를 걷어붙이고 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"범인을 진정시키고 이야기를 들어 준다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"에프넬과 함께 범인을 포위해 붙잡는다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_3\",\"text\":\"하루에게 범인의 정체를 먼저 밝히게 한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"쿠션 포위망\",\"text\":\"에프넬이 정면에서 시선을 끄는 사이 당신이 뒤에서 쿠션으로 퇴로를 막는다. 범인은 결국 푸딩 접시를 든 채 두 손을 든다. 에프넬은 세상에서 제일 한심한 현행범이라며 낄낄대고 하루는 눈물이 쏙 들어간다. 소동의 한가운데서 세 사람이 동시에 웃음을 터뜨리는 순간이다. 에프넬의 눈짓에 당신이 반사적으로 호응하자, 그녀는 마음에 든다는 듯 손가락으로 오케이 사인을 보낸다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"범인의 고백\",\"text\":\"범인은 훈련으로 지쳐 하루의 푸딩 향기에 홀려 몰래 먹었다고 고개를 숙인다. 이미 반 이상은 먹은 뒤라 하루의 표정이 복잡해진다. 에프넬은 팔짱을 낀 채 정말 한심하다며 쯧쯧 혀를 차지만 말투는 이미 풀려 있다. 사건은 사소했지만 숙소에는 묘하게 따뜻한 공기가 흐른다. 당신은 모두의 표정을 보며 이 소동이 어떻게 끝나야 할지 고민한다. 하루의 눈이 슬슬 촉촉해지는 것을 보며 에프넬의 말투는 점점 겉도는 독설이 되어 간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"남은 한 입\",\"text\":\"푸딩은 한 입 남아 있다. 하루가 그 마지막 한 입을 에프넬에게 건네며 사건을 해결해 줘서 고맙다고 활짝 웃는다. 에프넬은 어디서 이런 순수한 눈빛을 배웠냐며 투덜거리면서도 한 입을 받아먹는다. 입에 넣은 순간 그녀의 눈이 반달이 된다. 당신은 그 작은 행복을 놓치지 않고 바라본다. 에프넬은 맛은 평범하다고 말하지만 접시를 끝까지 비운다. 접시를 핥듯 비우는 모습이 어딘가 어린아이 같아서, 하루는 소리 내어 웃음을 터뜨리고 만다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"다음엔 모두가 함께 푸딩을 만들자고 제안한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_2\",\"text\":\"에프넬의 현상금 수령을 도와준다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_3\",\"text\":\"범인에게 설거지 벌칙을 정해 준다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"소동 이후의 오후\",\"text\":\"사건이 정리된 숙소는 평소의 소란으로 돌아왔다. 하루는 푸딩 재료를 다시 사 오겠다며 신나서 뛰어나가고, 에프넬은 소파에 다시 널브러져 졸린 척한다. 하지만 입가에는 은근히 만족스러운 미소가 걸려 있다. 당신은 옆자리에 앉아 창밖의 평범한 오후를 함께 바라본다. 에프넬은 다음 의뢰는 푸딩 말고 돈 되는 걸로 달라고 중얼거린다. 사소한 하루였지만 그만큼 평화로웠다는 사실을 둘 다 말로 꺼내지는 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"추리\",\"min\":9,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"추리\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"명탐정 에프넬과 조수\",\"text\":\"완벽한 추리로 범인과 동기까지 밝혀낸 날. 숙소 사람들은 두 사람을 명탐정과 조수라고 부르며 박수를 보낸다. 에프넬은 그런 칭호는 사절이라며 손사래를 치지만 현상금 봉투를 받는 손은 정직하게 기뻐한다. 밤이 되면 그녀는 당신에게 조수 월급은 푸딩 한 접시라며 장난스럽게 말한다. 하루도 그 곁에서 환하게 웃으며 이런 사건이라면 몇 번이든 좋다고 말한다. 푸딩이 사라진 아침은 그렇게 가장 웃긴 추억이 된다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"소란스러운 해결\",\"text\":\"추리는 조금 헤맸지만 결과적으로 푸딩 사건은 웃음 속에 마무리되었다. 하루는 모두에게 새 푸딩을 약속했고, 에프넬은 그럼 내 몫은 두 배로 달라고 흥정한다. 다시 시끌벅적해진 숙소에서 당신은 이 평범한 소동이 사실은 가장 소중한 일상임을 느낀다. 에프넬은 소란을 피우는 쪽도 해결하는 쪽도 결국 자기였다며 한숨을 쉬지만, 눈가에는 장난기가 맴돈다. 하루가 다음 푸딩 재료 목록을 적는 동안 에프넬은 몰래 첫 번째 줄에 자기 몫이라고 덧붙여 쓴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"미제로 남은 푸딩\",\"text\":\"사건은 어정쩡하게 끝났다. 범인은 밝혀졌지만 증거와 동기가 흐지부지해 하루의 푸딩은 끝내 돌아오지 않았다. 에프넬은 이런 건 사건도 아니라며 투덜대지만 다음엔 반드시 더 잘 잡자고 슬쩍 눈을 흘긴다. 소란도 실수도 모두 지나간 하루로 남는다. 그래도 숙소에서 함께 웃은 시간만큼은 어떤 의뢰 수당보다 값진 것이었다고 당신은 생각한다. 소동의 끝에 하루는 결국 웃으며 다음엔 푸딩에 이름표를 붙이겠다고 선언한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"추리\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"사라진 푸딩\",\"text\":\"아르카디아 렐름 숙소의 아침. 공용 냉장고에 넣어 둔 하루의 특제 푸딩이 통째로 사라졌다. 하루는 울상으로 범인을 찾겠다고 선언하고, 소파에 널브러져 있던 에프넬은 귀를 막으며 시끄럽다고 투덜댄다. 그러나 사건에 현상금이 걸리자 눈이 번쩍 뜨인다. 당신은 하루의 부탁으로 조사에 합류한다. 에프넬은 푸딩 하나로 이 난리냐며 코웃음 치지만 어느새 수사 모드로 몸을 일으킨다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"현장 검증\",\"text\":\"냉장고 앞은 의외로 깨끗하다. 포장지 하나, 숟가락 하나 남아 있지 않다. 에프넬은 쭈그려 앉아 바닥의 가는 흔적을 손끝으로 훑으며 이건 프로의 솜씨라고 진지하게 중얼거린다. 하루는 옆에서 감탄하며 메모를 하고, 당신은 문틈에서 설탕 가루 몇 알을 발견한다. 사소한 사건인데도 에프넬의 장난기와 승부욕이 묘하게 뒤섞여 분위기가 점점 들뜬다. 용의자는 숙소에 있던 세 명이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"냉장고 주변 설탕 가루의 경로를 따라간다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"용의자들을 한 명씩 불러 알리바이를 묻는다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"에프넬이 먹은 건 아니냐고 슬쩍 떠본다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"설탕의 길\",\"text\":\"설탕 가루는 주방에서 복도를 거쳐 어느 방문 앞에서 끊겨 있다. 에프넬은 코를 킁킁거리며 이건 단 냄새에 미친 놈의 짓이라고 득의양양하게 속삭인다. 하루는 그 방이 누구 방이냐고 놀라 입을 가리고, 당신은 문 안쪽에서 들리는 우적우적 소리를 알아챈다. 에프넬은 낄낄대며 사망 플래그가 서 있는 건 범인 쪽이라고 말한다. 숙소 복도는 순식간에 수사극의 무대가 되어, 하루는 발끝을 들고 에프넬은 능청스럽게 문 앞으로 다가선다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"첫 번째 용의자\",\"text\":\"복도 끝 방에서 졸린 눈의 동료가 나와 잠결에 억울하다고 호소한다. 에프넬은 알리바이의 허점을 사냥꾼처럼 파고들며 어젯밤 소등 후에 뭘 하고 있었냐고 능글맞게 압박한다. 하루는 그 말투에 눈치를 보며 진정하라고 뜯어말린다. 용의자는 정말 억울해 보이지만 입가에 푸른 얼룩이 묻어 있다. 당신은 대화 속에서 모순점을 찾을 수 있다. 에프넬은 용의자의 반응을 즐기듯 입꼬리를 올리며 취조실 분위기를 한껏 연출한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"입가의 푸른 얼룩이 푸딩 색과 다르다고 지적한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"하루가 만든 푸딩의 재료를 되짚어 본다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"일단 용의자를 풀어주고 다음 사람을 만난다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"하루의 푸딩 레시피\",\"text\":\"하루가 열심히 재료를 읊는 사이 에프넬은 하품을 삼키다가 갑자기 눈을 번쩍 뜬다. 우유와 달걀, 그리고 소울정크 열매를 갈아 넣었다는 말이 단서였다. 그 열매는 먹은 사람 입술을 보랏빛으로 물들이는 것으로 유명하다. 에프넬은 의기양양하게 이건 사건이 아니라 퍼즐이었다고 선언한다. 하루는 자신의 푸딩이 증거가 되었다는 사실에 뿌듯해하며 에프넬과 신나게 눈짓을 주고받는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"두 번째 용의자\",\"text\":\"다음 용의자는 숙소 지붕 위에서 낮잠을 자던 동료다. 에프넬이 사다리를 타고 올라가 깨우자 심술궂은 얼굴로 돈 되는 정보라도 주냐고 맞받아친다. 두 사람이 서로 보수를 흥정하는 와중에 하루는 눈물을 글썽이며 푸딩을 되찾고 싶다고 호소한다. 에프넬은 그 눈빛에 지고 만다. 사소한 서비스라며 마지못해 협조하지만 당신이 보기엔 이미 진심으로 푸딩 사건에 몰입하고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"하루를 안심시키며 증거부터 정리하자고 한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_2\",\"text\":\"에프넬의 흥정을 이용해 정보를 끌어낸다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_3\",\"text\":\"범인은 이미 정해졌다며 직감을 믿는다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"정보료는 푸딩 반쪽\",\"text\":\"당신의 제안으로 에프넬이 용의자에게 정보료 대신 되찾은 푸딩의 절반을 제시한다. 용의자는 흔들리는 눈빛으로 어젯밤 늦게 주방에서 수상한 그림자를 봤다고 털어놓는다. 하루는 이 방법이 통했다며 박수를 치고, 에프넬은 쓸데없이 약속 팔지 말라고 옆구리를 찌르지만 입꼬리는 올라가 있다. 에프넬은 빠르게 용의자 명단을 좁히고, 하루는 뒤에서 열심히 박수를 치며 응원을 보낸다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"한밤의 소동\",\"text\":\"추리가 막바지에 이르렀을 때 주방 쪽에서 쿵 하는 소리와 비명이 터진다. 달려가 보니 하루의 후배 소울워커가 푸딩 접시를 안은 채 얼어붙어 있다. 에프넬은 어랍쇼 하며 잡으려 하지만 상대는 도망치다가 소파 뒤로 구르고 말았다. 숙소는 순식간에 베개와 쿠션이 날아다니는 난장판이 된다. 당신은 혼란 속에서 상황을 정리해야 한다. 한순간에 수사극이 활극으로 변하자 에프넬은 오히려 신이 난 듯 소매를 걷어붙이고 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"범인을 진정시키고 이야기를 들어 준다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"에프넬과 함께 범인을 포위해 붙잡는다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o9_3\",\"text\":\"하루에게 범인의 정체를 먼저 밝히게 한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"쿠션 포위망\",\"text\":\"에프넬이 정면에서 시선을 끄는 사이 당신이 뒤에서 쿠션으로 퇴로를 막는다. 범인은 결국 푸딩 접시를 든 채 두 손을 든다. 에프넬은 세상에서 제일 한심한 현행범이라며 낄낄대고 하루는 눈물이 쏙 들어간다. 소동의 한가운데서 세 사람이 동시에 웃음을 터뜨리는 순간이다. 에프넬의 눈짓에 당신이 반사적으로 호응하자, 그녀는 마음에 든다는 듯 손가락으로 오케이 사인을 보낸다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"범인의 고백\",\"text\":\"범인은 훈련으로 지쳐 하루의 푸딩 향기에 홀려 몰래 먹었다고 고개를 숙인다. 이미 반 이상은 먹은 뒤라 하루의 표정이 복잡해진다. 에프넬은 팔짱을 낀 채 정말 한심하다며 쯧쯧 혀를 차지만 말투는 이미 풀려 있다. 사건은 사소했지만 숙소에는 묘하게 따뜻한 공기가 흐른다. 당신은 모두의 표정을 보며 이 소동이 어떻게 끝나야 할지 고민한다. 하루의 눈이 슬슬 촉촉해지는 것을 보며 에프넬의 말투는 점점 겉도는 독설이 되어 간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"남은 한 입\",\"text\":\"푸딩은 한 입 남아 있다. 하루가 그 마지막 한 입을 에프넬에게 건네며 사건을 해결해 줘서 고맙다고 활짝 웃는다. 에프넬은 어디서 이런 순수한 눈빛을 배웠냐며 투덜거리면서도 한 입을 받아먹는다. 입에 넣은 순간 그녀의 눈이 반달이 된다. 당신은 그 작은 행복을 놓치지 않고 바라본다. 에프넬은 맛은 평범하다고 말하지만 접시를 끝까지 비운다. 접시를 핥듯 비우는 모습이 어딘가 어린아이 같아서, 하루는 소리 내어 웃음을 터뜨리고 만다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"다음엔 모두가 함께 푸딩을 만들자고 제안한다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_2\",\"text\":\"에프넬의 현상금 수령을 도와준다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o12_3\",\"text\":\"범인에게 설거지 벌칙을 정해 준다\",\"varOps\":[{\"var\":\"추리\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"소동 이후의 오후\",\"text\":\"사건이 정리된 숙소는 평소의 소란으로 돌아왔다. 하루는 푸딩 재료를 다시 사 오겠다며 신나서 뛰어나가고, 에프넬은 소파에 다시 널브러져 졸린 척한다. 하지만 입가에는 은근히 만족스러운 미소가 걸려 있다. 당신은 옆자리에 앉아 창밖의 평범한 오후를 함께 바라본다. 에프넬은 다음 의뢰는 푸딩 말고 돈 되는 걸로 달라고 중얼거린다. 사소한 하루였지만 그만큼 평화로웠다는 사실을 둘 다 말로 꺼내지는 않는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"추리\",\"min\":9,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"추리\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"명탐정 에프넬과 조수\",\"text\":\"완벽한 추리로 범인과 동기까지 밝혀낸 날. 숙소 사람들은 두 사람을 명탐정과 조수라고 부르며 박수를 보낸다. 에프넬은 그런 칭호는 사절이라며 손사래를 치지만 현상금 봉투를 받는 손은 정직하게 기뻐한다. 밤이 되면 그녀는 당신에게 조수 월급은 푸딩 한 접시라며 장난스럽게 말한다. 하루도 그 곁에서 환하게 웃으며 이런 사건이라면 몇 번이든 좋다고 말한다. 푸딩이 사라진 아침은 그렇게 가장 웃긴 추억이 된다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"소란스러운 해결\",\"text\":\"추리는 조금 헤맸지만 결과적으로 푸딩 사건은 웃음 속에 마무리되었다. 하루는 모두에게 새 푸딩을 약속했고, 에프넬은 그럼 내 몫은 두 배로 달라고 흥정한다. 다시 시끌벅적해진 숙소에서 당신은 이 평범한 소동이 사실은 가장 소중한 일상임을 느낀다. 에프넬은 소란을 피우는 쪽도 해결하는 쪽도 결국 자기였다며 한숨을 쉬지만, 눈가에는 장난기가 맴돈다. 하루가 다음 푸딩 재료 목록을 적는 동안 에프넬은 몰래 첫 번째 줄에 자기 몫이라고 덧붙여 쓴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"미제로 남은 푸딩\",\"text\":\"사건은 어정쩡하게 끝났다. 범인은 밝혀졌지만 증거와 동기가 흐지부지해 하루의 푸딩은 끝내 돌아오지 않았다. 에프넬은 이런 건 사건도 아니라며 투덜대지만 다음엔 반드시 더 잘 잡자고 슬쩍 눈을 흘긴다. 소란도 실수도 모두 지나간 하루로 남는다. 그래도 숙소에서 함께 웃은 시간만큼은 어떤 의뢰 수당보다 값진 것이었다고 당신은 생각한다. 소동의 끝에 하루는 결국 웃으며 다음엔 푸딩에 이름표를 붙이겠다고 선언한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '숙소 간식 도난 사건 - 범인은 이 중에 있다'
);

-- 12. [에프넬] 루인 포트리스의 잔해 - F-N. EL이 돌아온 밤
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '루인 포트리스의 잔해 - F-N. EL이 돌아온 밤', 'published', 0, '{\"vars\":[{\"name\":\"유대\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"지도 위의 빨간 원\",\"text\":\"아르카디아 렐름 숙소의 밤. 별숲리그 정보국이 보내온 지도에는 폐허가 된 루인 포트리스의 좌표가 빨간 원으로 표시되어 있다. 네드 컴퍼니의 잔여 장비가 회수되지 않았다는 보고다. 에프넬은 지도를 한참 노려보다가 갑자기 웃음을 터뜨리며 무료 관광이냐고 빈정거린다. 하지만 창을 쥔 손가락 끝이 하얗게 질려 있다. 당신은 그녀가 혼자 가려 한다는 걸 직감하고 곁에서 말을 건다. 에프넬은 대답 대신 시선을 피한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"혼자 가겠다는 고집\",\"text\":\"에프넬은 가방을 챙기며 보수도 안 나오는 일에 따라올 필요는 없다고 못 박는다. 목소리는 장난스럽지만 평소와 달리 말끝이 아주 약간 떨린다. 루인 포트리스는 그녀가 실험체로 끌려갔다 실패작으로 폐기된 곳이다. 당신은 문가에 서서 그녀가 뿌리치려 하는 이유를 헤아려 본다. 방 안의 공기가 무겁게 가라앉고, 에프넬은 말투를 바꿔 거칠게 시꺼라고 내뱉는다. 만류하는 당신을 보며 그녀는 한 번 더 시선을 돌려 버린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"보수가 없어도 따라가겠다고 담담히 말한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"위험하니 별숲리그 지원을 요청하자고 말한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"그녀의 뜻을 존중해 말리지 않는다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"공짜 노예 따위\",\"text\":\"당신의 대답에 에프넬은 어이없다는 듯 웃으며 공짜로 부려먹을 노예가 제 발로 오겠다니 땡잡았다고 중얼거린다. 하지만 가방끈을 쥔 손에서 긴장이 조금 풀린다. 그녀는 말없이 옆 가방 하나를 당신에게 던지며 대신 짐은 들라고 한다. 이것이 그녀가 허락하는 방식의 동행 승낙이다. 당신은 조용히 가방을 어깨에 멘다. 두 사람은 가볍게 짐을 나누고, 에프넬은 투덜대면서도 걸음을 당신과 나란히 맞춘다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"폐허로 가는 길\",\"text\":\"황량한 평원 끝에 검게 무너진 요새가 모습을 드러낸다. 금이 간 외벽과 녹슨 철문, 바람에 날리는 바랜 N 마크 현수막이 시간이 멈춘 듯 서 있다. 에프넬은 걸음을 늦추지도, 서두르지도 않은 채 앞서 걸어가며 쓸데없는 농담을 연발한다. 하지만 철문 앞에서 갑자기 멈춰 선다. 당신은 숨을 고르는 그녀의 옆에 서서 기다린다. 요새의 입구에서 차가운 바람이 불어 나온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"괜찮다고 하지 않아도 된다고 말해 준다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"먼저 앞장서서 안전을 확인하겠다고 한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"분위기를 풀려고 농담을 던진다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"먼저 열어 줄게\",\"text\":\"당신이 앞서 문을 밀어 열자 에프넬이 깜짝 놀라 어이없다는 듯 쳐다본다. 이런 건 보통 내가 하는 거라고 투덜대지만 그녀의 어깨에서 긴장이 풀린다. 문이 열리며 묵은 먼지가 안개처럼 흩어진다. 안은 어둡고 조용하며, 한때 사람이 지나다녔다는 흔적이 곳곳에 남아 있다. 에프넬은 당신 뒤에 바싹 붙어 걷는다. 둘은 입구를 지나 어둡고 긴 통로로 들어서고, 에프넬은 아주 조용히 숨을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"번호가 새겨진 복도\",\"text\":\"복도 벽에는 아이들의 키만 한 높이로 번호들이 새겨져 있다. 에프넬은 그중 EL이라는 글자를 발견하고는 굳은 듯 서 있다. 숫자 옆에는 누군가 손톱으로 긁은 작은 별 하나가 새겨져 있다. 그녀는 잠시 말이 없다가 이거 내가 그린 거라고 쓴웃음 짓는다. 당신은 그녀가 이 벽 앞에서 얼마나 오래 서 있었는지 짐작한다. 복도 끝에서 기계 소리가 희미하게 울린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"그 별을 함께 바라보며 아무 말도 하지 않는다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_2\",\"text\":\"그 별이 예쁘다고 솔직하게 말한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_3\",\"text\":\"지나치게 감상에 빠지지 말고 서두르자고 재촉한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"예쁘다는 말의 무게\",\"text\":\"예쁘다는 말에 에프넬은 순간 숨을 멈춘다. 곧 소름 끼친다고 소리 지르지만 눈동자가 잠시 흔들린다. 그녀는 벽의 별을 소매로 쓱 문질러 지우려다 손을 멈추고, 결국 그대로 둔다. 아무도 기억해 주지 않을 거라 생각한 흔적이 누군가에게 아름답게 보였다는 사실이 묘하게 마음을 건드린 것이다. 작은 별 하나가 두 사람 사이에서 오래된 이야기를 대신 들려주듯 희미하게 빛난다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"깨어난 방어 시스템\",\"text\":\"복도 끝 방에 들어서자 오래된 방어 시스템이 붉은 눈을 뜬다. 천장의 포구와 벽의 레이저가 두 사람을 겨눈다. 에프넬은 창을 뽑아 돌리며 여긴 내가 제일 잘 안다고 외치고, 제어 패널을 향해 몸을 날린다. 하지만 패널은 번호 인증을 요구하고, 그녀의 몸에 새겨진 코드가 반응하며 격렬한 통증이 몰려온다. 당신은 바로 곁에서 상황을 판단해야 한다. 당신은 그녀의 비명 섞인 숨을 들으며 주저 없이 몸을 움직일 각오를 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"방어 시스템을 막아서며 시간을 번다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"에프넬을 부축해 패널에서 떼어 놓는다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_3\",\"text\":\"패널을 힘으로 부수자고 외친다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"아프면 아프다고 해\",\"text\":\"당신이 그녀의 팔을 당겨 패널에서 떼어 내자 에프넬이 이를 악물며 괜찮다고 우긴다. 하지만 이마에 식은땀이 맺혀 있다. 당신이 아프면 아프다고 하라고 하자 그녀는 한참 숨을 고르다가 아주 작게 아프다고 인정한다. 처음 입 밖에 낸 약한 소리다. 그리고는 곧바로 이건 서비스니까 기록은 남기지 말라고 덧붙인다. 방어 시스템의 붉은 빛이 차츰 사그라드는 동안 두 사람은 아무 말 없이 서로의 숨소리를 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"잠든 기계들의 침묵\",\"text\":\"방어 시스템이 멎은 방은 기이할 만큼 조용하다. 에프넬은 벽에 등을 기대 주저앉아 숨을 고르며 이런 데서 몇 년을 살았다니 웃기지도 않는다고 중얼거린다. 천장의 깨진 틈으로 달빛이 한 줄기 들어와 먼지를 반짝이게 한다. 당신은 물통을 건네고 그녀 곁에 앉는다. 에프넬은 물을 받아 마시고는 말없이 한참 달빛을 올려다본다. 그 침묵은 지금까지 그녀가 허락한 어떤 대화보다 길고 깊다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"마지막 기록\",\"text\":\"방어 시스템이 멎자 방 안쪽 선반 위에서 상자 하나가 드러난다. 안에는 낡은 어린이용 신발과 한 장의 보고서가 들어 있다. 에프넬이 끌려왔을 때 신고 있던 신발이다. 보고서에는 아이의 본명과 부모의 계약 금액이 적혀 있다. 그녀는 그 이름을 읽지 않으려 눈을 질끈 감는다. 당신은 상자를 닫아 줄지, 그녀의 선택에 맡길지 고민한다. 먼지 쌓인 신발 앞에서 시간이 거꾸로 흐르는 듯한 침묵이 오래 이어진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"보고서를 대신 태워 달라는 부탁을 들어 준다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_2\",\"text\":\"그녀가 스스로 결정할 때까지 기다린다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_3\",\"text\":\"신발만 가져가 기념으로 삼자고 제안한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"폐허 위의 아침\",\"text\":\"요새를 나서자 평원 위로 새벽빛이 번지고 있다. 에프넬은 말없이 걷다가 문득 내가 그 이름을 얼마나 싫어하는지 알지 하고 묻는다. 대답을 기다리지도 않고 이름 같은 건 필요 없었다고 웃어넘기려 하지만 눈가가 젖어 있다. 당신은 그 곁에서 조용히 같은 하늘을 바라본다. 에프넬은 오늘 일은 영업 비밀이라고 하며 입을 닫고, 그러나 손은 당신의 소매 끝을 아주 살짝 붙잡고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"유대\",\"min\":9,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"유대\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"에프넬이라는 이름으로\",\"text\":\"숙소로 돌아온 밤, 에프넬은 어둠 속에서 말없이 당신 옆에 앉는다. 오늘 일은 영업 비밀이라고 말하지만, 그 어느 때보다 편안한 숨소리다. 그녀는 불쑥 내 이름은 에프넬이야, 그것만 기억해 하고 중얼거린다. 당신은 고개를 끄덕이며 그 이름을 소중히 되뇐다. 과거가 아닌 지금의 그녀를 인정받은 밤이 조용히 깊어 간다. 먼 하늘에는 새벽별이 하나 남아 있고, 그 별이 벽에 새겨진 작은 별과 닮았다고 당신은 속으로 생각한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"비밀로 남기기로 한 날\",\"text\":\"돌아오는 길 내내 두 사람은 별말 없이 걸었다. 숙소에 도착하자 에프넬은 평소처럼 소파에 몸을 던지며 오늘 일을 입 밖에 내면 상담료를 물리겠다고 으름장을 놓는다. 하지만 이전보다 눈빛이 덜 날카롭다. 당신과 나눈 침묵은 그녀에게 작은 쉼터가 되었다. 그녀는 인정하지 않겠지만 그 침묵의 값을 언젠가 반드시 갚을 사람이다. 창밖의 달은 둘이 걸어온 길을 말없이 비추며, 다음 한 걸음을 조용히 기다린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"닫아 둔 서랍\",\"text\":\"에프넬은 결국 많은 말을 하지 않은 채 돌아왔다. 과거의 흔적을 마주하긴 했지만 마음의 서랍은 여전히 굳게 닫혀 있다. 그녀는 아무 일도 없었던 것처럼 농담을 던지며 숙소로 들어간다. 그래도 당신이 곁에 있었다는 사실은 그녀가 잊지 않을 것이다. 다음번엔 조금 더 열릴지도 모른다. 평원을 넘어가는 바람 속에서 두 사람은 같은 하늘 아래 각자의 속도로 걸음을 옮긴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"유대\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"지도 위의 빨간 원\",\"text\":\"아르카디아 렐름 숙소의 밤. 별숲리그 정보국이 보내온 지도에는 폐허가 된 루인 포트리스의 좌표가 빨간 원으로 표시되어 있다. 네드 컴퍼니의 잔여 장비가 회수되지 않았다는 보고다. 에프넬은 지도를 한참 노려보다가 갑자기 웃음을 터뜨리며 무료 관광이냐고 빈정거린다. 하지만 창을 쥔 손가락 끝이 하얗게 질려 있다. 당신은 그녀가 혼자 가려 한다는 걸 직감하고 곁에서 말을 건다. 에프넬은 대답 대신 시선을 피한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"혼자 가겠다는 고집\",\"text\":\"에프넬은 가방을 챙기며 보수도 안 나오는 일에 따라올 필요는 없다고 못 박는다. 목소리는 장난스럽지만 평소와 달리 말끝이 아주 약간 떨린다. 루인 포트리스는 그녀가 실험체로 끌려갔다 실패작으로 폐기된 곳이다. 당신은 문가에 서서 그녀가 뿌리치려 하는 이유를 헤아려 본다. 방 안의 공기가 무겁게 가라앉고, 에프넬은 말투를 바꿔 거칠게 시꺼라고 내뱉는다. 만류하는 당신을 보며 그녀는 한 번 더 시선을 돌려 버린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"보수가 없어도 따라가겠다고 담담히 말한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"위험하니 별숲리그 지원을 요청하자고 말한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"그녀의 뜻을 존중해 말리지 않는다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"공짜 노예 따위\",\"text\":\"당신의 대답에 에프넬은 어이없다는 듯 웃으며 공짜로 부려먹을 노예가 제 발로 오겠다니 땡잡았다고 중얼거린다. 하지만 가방끈을 쥔 손에서 긴장이 조금 풀린다. 그녀는 말없이 옆 가방 하나를 당신에게 던지며 대신 짐은 들라고 한다. 이것이 그녀가 허락하는 방식의 동행 승낙이다. 당신은 조용히 가방을 어깨에 멘다. 두 사람은 가볍게 짐을 나누고, 에프넬은 투덜대면서도 걸음을 당신과 나란히 맞춘다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"폐허로 가는 길\",\"text\":\"황량한 평원 끝에 검게 무너진 요새가 모습을 드러낸다. 금이 간 외벽과 녹슨 철문, 바람에 날리는 바랜 N 마크 현수막이 시간이 멈춘 듯 서 있다. 에프넬은 걸음을 늦추지도, 서두르지도 않은 채 앞서 걸어가며 쓸데없는 농담을 연발한다. 하지만 철문 앞에서 갑자기 멈춰 선다. 당신은 숨을 고르는 그녀의 옆에 서서 기다린다. 요새의 입구에서 차가운 바람이 불어 나온다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"괜찮다고 하지 않아도 된다고 말해 준다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"먼저 앞장서서 안전을 확인하겠다고 한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"분위기를 풀려고 농담을 던진다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":250,\"type\":\"story\",\"title\":\"먼저 열어 줄게\",\"text\":\"당신이 앞서 문을 밀어 열자 에프넬이 깜짝 놀라 어이없다는 듯 쳐다본다. 이런 건 보통 내가 하는 거라고 투덜대지만 그녀의 어깨에서 긴장이 풀린다. 문이 열리며 묵은 먼지가 안개처럼 흩어진다. 안은 어둡고 조용하며, 한때 사람이 지나다녔다는 흔적이 곳곳에 남아 있다. 에프넬은 당신 뒤에 바싹 붙어 걷는다. 둘은 입구를 지나 어둡고 긴 통로로 들어서고, 에프넬은 아주 조용히 숨을 고른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"번호가 새겨진 복도\",\"text\":\"복도 벽에는 아이들의 키만 한 높이로 번호들이 새겨져 있다. 에프넬은 그중 EL이라는 글자를 발견하고는 굳은 듯 서 있다. 숫자 옆에는 누군가 손톱으로 긁은 작은 별 하나가 새겨져 있다. 그녀는 잠시 말이 없다가 이거 내가 그린 거라고 쓴웃음 짓는다. 당신은 그녀가 이 벽 앞에서 얼마나 오래 서 있었는지 짐작한다. 복도 끝에서 기계 소리가 희미하게 울린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o7_1\",\"text\":\"그 별을 함께 바라보며 아무 말도 하지 않는다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o7_2\",\"text\":\"그 별이 예쁘다고 솔직하게 말한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o7_3\",\"text\":\"지나치게 감상에 빠지지 말고 서두르자고 재촉한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n10\",\"x\":3120,\"y\":250,\"type\":\"story\",\"title\":\"예쁘다는 말의 무게\",\"text\":\"예쁘다는 말에 에프넬은 순간 숨을 멈춘다. 곧 소름 끼친다고 소리 지르지만 눈동자가 잠시 흔들린다. 그녀는 벽의 별을 소매로 쓱 문질러 지우려다 손을 멈추고, 결국 그대로 둔다. 아무도 기억해 주지 않을 거라 생각한 흔적이 누군가에게 아름답게 보였다는 사실이 묘하게 마음을 건드린 것이다. 작은 별 하나가 두 사람 사이에서 오래된 이야기를 대신 들려주듯 희미하게 빛난다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n11\",\"x\":3420,\"y\":320,\"type\":\"story\",\"title\":\"깨어난 방어 시스템\",\"text\":\"복도 끝 방에 들어서자 오래된 방어 시스템이 붉은 눈을 뜬다. 천장의 포구와 벽의 레이저가 두 사람을 겨눈다. 에프넬은 창을 뽑아 돌리며 여긴 내가 제일 잘 안다고 외치고, 제어 패널을 향해 몸을 날린다. 하지만 패널은 번호 인증을 요구하고, 그녀의 몸에 새겨진 코드가 반응하며 격렬한 통증이 몰려온다. 당신은 바로 곁에서 상황을 판단해야 한다. 당신은 그녀의 비명 섞인 숨을 들으며 주저 없이 몸을 움직일 각오를 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o9_1\",\"text\":\"방어 시스템을 막아서며 시간을 번다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_2\",\"text\":\"에프넬을 부축해 패널에서 떼어 놓는다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o9_3\",\"text\":\"패널을 힘으로 부수자고 외친다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n13\",\"x\":4020,\"y\":250,\"type\":\"story\",\"title\":\"아프면 아프다고 해\",\"text\":\"당신이 그녀의 팔을 당겨 패널에서 떼어 내자 에프넬이 이를 악물며 괜찮다고 우긴다. 하지만 이마에 식은땀이 맺혀 있다. 당신이 아프면 아프다고 하라고 하자 그녀는 한참 숨을 고르다가 아주 작게 아프다고 인정한다. 처음 입 밖에 낸 약한 소리다. 그리고는 곧바로 이건 서비스니까 기록은 남기지 말라고 덧붙인다. 방어 시스템의 붉은 빛이 차츰 사그라드는 동안 두 사람은 아무 말 없이 서로의 숨소리를 확인한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n14\",\"x\":4320,\"y\":320,\"type\":\"story\",\"title\":\"잠든 기계들의 침묵\",\"text\":\"방어 시스템이 멎은 방은 기이할 만큼 조용하다. 에프넬은 벽에 등을 기대 주저앉아 숨을 고르며 이런 데서 몇 년을 살았다니 웃기지도 않는다고 중얼거린다. 천장의 깨진 틈으로 달빛이 한 줄기 들어와 먼지를 반짝이게 한다. 당신은 물통을 건네고 그녀 곁에 앉는다. 에프넬은 물을 받아 마시고는 말없이 한참 달빛을 올려다본다. 그 침묵은 지금까지 그녀가 허락한 어떤 대화보다 길고 깊다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"마지막 기록\",\"text\":\"방어 시스템이 멎자 방 안쪽 선반 위에서 상자 하나가 드러난다. 안에는 낡은 어린이용 신발과 한 장의 보고서가 들어 있다. 에프넬이 끌려왔을 때 신고 있던 신발이다. 보고서에는 아이의 본명과 부모의 계약 금액이 적혀 있다. 그녀는 그 이름을 읽지 않으려 눈을 질끈 감는다. 당신은 상자를 닫아 줄지, 그녀의 선택에 맡길지 고민한다. 먼지 쌓인 신발 앞에서 시간이 거꾸로 흐르는 듯한 침묵이 오래 이어진다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o12_1\",\"text\":\"보고서를 대신 태워 달라는 부탁을 들어 준다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_2\",\"text\":\"그녀가 스스로 결정할 때까지 기다린다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o12_3\",\"text\":\"신발만 가져가 기념으로 삼자고 제안한다\",\"varOps\":[{\"var\":\"유대\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"story\",\"title\":\"폐허 위의 아침\",\"text\":\"요새를 나서자 평원 위로 새벽빛이 번지고 있다. 에프넬은 말없이 걷다가 문득 내가 그 이름을 얼마나 싫어하는지 알지 하고 묻는다. 대답을 기다리지도 않고 이름 같은 건 필요 없었다고 웃어넘기려 하지만 눈가가 젖어 있다. 당신은 그 곁에서 조용히 같은 하늘을 바라본다. 에프넬은 오늘 일은 영업 비밀이라고 하며 입을 닫고, 그러나 손은 당신의 소매 끝을 아주 살짝 붙잡고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n18\",\"x\":5520,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"유대\",\"min\":9,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"유대\",\"min\":5,\"max\":null}]}]},{\"id\":\"n19\",\"x\":5820,\"y\":60,\"type\":\"story\",\"title\":\"에프넬이라는 이름으로\",\"text\":\"숙소로 돌아온 밤, 에프넬은 어둠 속에서 말없이 당신 옆에 앉는다. 오늘 일은 영업 비밀이라고 말하지만, 그 어느 때보다 편안한 숨소리다. 그녀는 불쑥 내 이름은 에프넬이야, 그것만 기억해 하고 중얼거린다. 당신은 고개를 끄덕이며 그 이름을 소중히 되뇐다. 과거가 아닌 지금의 그녀를 인정받은 밤이 조용히 깊어 간다. 먼 하늘에는 새벽별이 하나 남아 있고, 그 별이 벽에 새겨진 작은 별과 닮았다고 당신은 속으로 생각한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5820,\"y\":250,\"type\":\"story\",\"title\":\"비밀로 남기기로 한 날\",\"text\":\"돌아오는 길 내내 두 사람은 별말 없이 걸었다. 숙소에 도착하자 에프넬은 평소처럼 소파에 몸을 던지며 오늘 일을 입 밖에 내면 상담료를 물리겠다고 으름장을 놓는다. 하지만 이전보다 눈빛이 덜 날카롭다. 당신과 나눈 침묵은 그녀에게 작은 쉼터가 되었다. 그녀는 인정하지 않겠지만 그 침묵의 값을 언젠가 반드시 갚을 사람이다. 창밖의 달은 둘이 걸어온 길을 말없이 비추며, 다음 한 걸음을 조용히 기다린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n21\",\"x\":5820,\"y\":440,\"type\":\"story\",\"title\":\"닫아 둔 서랍\",\"text\":\"에프넬은 결국 많은 말을 하지 않은 채 돌아왔다. 과거의 흔적을 마주하긴 했지만 마음의 서랍은 여전히 굳게 닫혀 있다. 그녀는 아무 일도 없었던 것처럼 농담을 던지며 숙소로 들어간다. 그래도 당신이 곁에 있었다는 사실은 그녀가 잊지 않을 것이다. 다음번엔 조금 더 열릴지도 모른다. 평원을 넘어가는 바람 속에서 두 사람은 같은 하늘 아래 각자의 속도로 걸음을 옮긴다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":6120,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n7\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n8\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"o7_2\",\"to\":\"n10\"},{\"from\":\"n9\",\"fromPort\":\"o7_1\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"out\",\"to\":\"n11\"},{\"from\":\"n9\",\"fromPort\":\"o7_3\",\"to\":\"n11\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"o9_2\",\"to\":\"n13\"},{\"from\":\"n12\",\"fromPort\":\"o9_1\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"out\",\"to\":\"n14\"},{\"from\":\"n12\",\"fromPort\":\"o9_3\",\"to\":\"n14\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"o12_1\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_2\",\"to\":\"n17\"},{\"from\":\"n16\",\"fromPort\":\"o12_3\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"out\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"r1\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"r2\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n18\",\"fromPort\":\"else\",\"to\":\"n21\"},{\"from\":\"n21\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '루인 포트리스의 잔해 - F-N. EL이 돌아온 밤'
);

-- 13. [에프넬] 현상금 사냥 대결 - 지는 쪽이 저녁 쏜다
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '현상금 사냥 대결 - 지는 쪽이 저녁 쏜다', 'published', 0, '{\"vars\":[{\"name\":\"승부\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"게시판 앞의 도발\",\"text\":\"아르카디아 렐름 별숲리그 지부의 의뢰 게시판 앞. 에프넬이 현상금 전단 한 장을 손가락으로 튕기며 당신에게 내기를 건다. 오늘 하루 안에 더 큰 현상금을 챙기는 쪽이 이기고, 지는 쪽이 저녁을 사는 조건이다. 능글맞은 웃음에는 이미 이길 생각밖에 없다. 말은 가볍지만 눈빛은 사냥꾼처럼 빛난다. 당신은 협력자이면서 오늘만큼은 라이벌이 된다. 에프넬은 판돈은 안 걸어도 돈 냄새는 맡겠다며 신나서 어깨를 푼다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"각자의 사냥터\",\"text\":\"규칙은 단순하다. 정오까지 각자 다른 의뢰를 골라 해결하고, 현상금 영수증으로 승부를 가린다. 에프넬은 가장 비싼 전단인 협곡 소울정크 무리 토벌을 가져가고, 당신에게는 먼저 고르라는 듯 여유 있게 손을 내민다. 지부 직원은 혀를 내두르며 말리지만 아무도 이 승부를 말릴 수 없다. 당신은 남은 전단들을 훑어보며 전략을 짠다. 에프넬은 뒤에서 어디 한번 잘해 보라며 빈정거린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"story\",\"title\":\"전단 속의 함정\",\"text\":\"게시판 앞에서 전단을 고르던 중, 에프넬이 슬쩍 한 장을 뒤로 숨기는 것을 당신은 놓치지 않는다. 가장 비싼 전단일수록 이유가 있다는 건 용병 일을 해 온 그녀가 제일 잘 안다. 그녀는 내기를 거는 척하지만 위험한 의뢰는 자기가 먼저 가져가려는 속셈이다. 당신이 눈치채자 그녀는 어랍쇼 하고 시치미를 뗀다. 지부 직원의 한숨 소리가 길게 이어지는 가운데 두 사람은 서로의 속내를 은근히 가늠한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o4_1\",\"text\":\"위험하지만 보수가 큰 베시 추적 의뢰를 고른다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o4_2\",\"text\":\"안전하고 빠른 소울정크 퇴치 몇 건을 모은다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o4_3\",\"text\":\"에프넬 몰래 협곡 의뢰를 가로채려 한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n5\",\"x\":1620,\"y\":60,\"type\":\"story\",\"title\":\"정면 승부수\",\"text\":\"당신이 베시 추적 전단을 뽑아 들자 에프넬의 눈이 둥그레진다. 그녀는 제법인데 하고 휘파람을 불면서도 곧 질투 섞인 표정을 짓는다. 이 의뢰는 이계 종족을 상대로 한 위험 임무라 보수도 높다. 에프넬은 쓸데없이 죽지나 말라며 어깨를 툭 치고 협곡 쪽으로 달려간다. 이미 승부는 시작되었다. 그녀는 당신의 등을 향해 손을 흔들고, 두 사람은 반대 방향으로 갈라져 각자의 사냥터로 달려간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"협곡의 에프넬\",\"text\":\"정오가 가까워질 무렵, 협곡에서는 에프넬이 소울정크 무리를 한꺼번에 몰아치고 있다. 체술로 걷어차고 창으로 꿰뚫는 움직임에는 군더더기가 없다. 그녀는 입으로는 연신 당신을 놀리면서 몸은 혼자 열 마리를 상대한다. 그런데 한 마리가 그녀의 사각을 파고든다. 당신이 근처를 지나던 중 그 장면을 발견했고, 승부와 도움 사이에서 짧은 선택의 순간이 온다. 에프넬은 아직 당신의 존재를 모른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"승부는 승부, 일단 그녀를 도와 사각의 적을 쓰러뜨린다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"모른 척 지나치며 내 의뢰를 계속한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"그녀가 위험해질 때까지 지켜본다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"도움은 반칙이 아냐\",\"text\":\"당신이 던진 일격이 사각의 소울정크를 쓰러뜨리자 에프넬이 휙 돌아보고 눈을 부릅뜬다. 누가 도와 달랬냐고 소리치지만 얼굴에는 안도가 스쳤다. 이건 무효라고 주장하는 그녀에게 당신은 영수증은 서로의 몫이라고 웃는다. 에프넬은 잠시 입을 다물다가 칫 하고 혀를 차며 이번 한 번만 서비스라고 중얼거린다. 서로 말은 없었지만 마음 한쪽에서는 이 소란이 싫지만은 않다는 공감이 스며든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"숨어 있던 우두머리\",\"text\":\"협곡 안쪽 깊은 곳에서 유난히 커다란 소울정크 우두머리가 모습을 드러낸다. 이 녀석의 현상금이 오늘 전단 중 최고액이다. 에프넬과 당신은 거의 동시에 도착해 눈이 마주친다. 서로 이 녀석은 내 거라는 눈빛으로 불꽃이 튄다. 하지만 우두머리의 덩치는 혼자서 상대하기엔 만만치 않아 보인다. 에프넬은 능청스럽게 협상을 제안한다. 당신은 승부와 협력 사이에서 선택해야 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"현상금을 반반 나누기로 하고 함께 싸운다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"먼저 일격을 내서 선공을 가져간다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"에프넬에게 선공을 양보하고 지원한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"빼앗긴 선공\",\"text\":\"당신이 선공을 날리자 우두머리가 거칠게 반응해 둘 모두를 쫓기 시작한다. 에프넬은 이 바보야 하고 외치면서도 몸을 날려 당신을 낚아채 피한다. 간발의 차로 바위 뒤에 숨은 두 사람은 숨을 헐떡이며 서로를 노려본다. 승부에 눈이 먼 대가를 톡톡히 치른 셈이지만 에프넬의 입가에는 웃음이 걸려 있다. 우두머리와의 거리가 좁혀지는 사이, 에프넬은 어느새 당신이 믿을 수 있는 등을 맡기고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"마지막 일격\",\"text\":\"우두머리가 거대한 팔을 휘두르는 순간, 에프넬이 창을 박아 넣어 움직임을 묶는다. 당신이 그 틈을 파고들어 마무리를 지을 차례다. 둘의 호흡이 의외로 잘 맞아떨어지며 협곡 전체가 흔들릴 만큼의 충격이 터진다. 쓰러진 우두머리의 영수증은 누구의 몫일까. 에프넬은 숨을 헐떡이며 이거 누구 몫이냐고 묻고, 당신은 그 질문에 대한 답을 가지고 있다. 먼지가 가라앉고 나서야 둘은 서로의 얼굴이 온통 흙투성이라는 걸 알고 동시에 웃음을 터뜨린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"영수증은 에프넬 이름으로 올리고 대신 저녁은 얻어먹는다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_2\",\"text\":\"반반 나눠서 영수증을 둘로 쪼갠다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"당신 이름으로 올리고 당당히 저녁을 요구한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":440,\"type\":\"story\",\"title\":\"승부사의 자존심\",\"text\":\"당신의 선언에 에프넬은 아앙 하고 눈썹을 치켜세운다. 하지만 이내 큰 소리로 웃어 버린다. 이기고 싶은 마음을 숨기지 않는 사람이 마음에 든다는 듯이다. 그녀는 영수증을 접어 당신에게 던지며 다음 판은 반드시 이긴다고 선언한다. 기분 나쁜 척하지만 눈은 반짝이고 있다. 두 사람은 숨을 고르며 길고 가벼운 웃음을 나누고, 협곡의 메아리가 그 웃음을 오래 되돌려 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"정산소의 숫자\",\"text\":\"지부로 돌아와 정산 창구에 영수증이 올려진다. 직원이 계산기를 두드리는 동안 에프넬은 손톱을 물어뜯으며 숫자를 훔쳐본다. 결과는 박빙이다. 몇 푼 차이로 승부가 갈릴 것이다. 당신과 에프넬은 서로 곁눈질하며 긴장한다. 지부 로비의 다른 소울워커들까지 구경을 하러 모여든다. 직원이 마침내 결과를 읽기 시작하자 에프넬은 침을 꿀꺽 삼킨다. 구경꾼들의 웅성거림 속에서도 에프넬의 시선은 오직 계산기 위의 숫자에 못 박혀 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"저녁은 누가 쏘나\",\"text\":\"승부의 결과가 나온 뒤, 두 사람은 지부 근처 식당의 구석 자리에 앉는다. 에프넬은 메뉴판을 펼치고 가장 비싼 것부터 훑어보며 눈을 반짝인다. 누가 사든 일단 먹고 보자는 기세다. 당신은 그녀의 표정에서 승부 이상의 기쁨을 읽는다. 오늘 하루 같이 달린 시간이 서로에게 편해졌다는 사실이 은근한 온기로 남는다. 에프넬은 다음 승부는 내일이라고 선언한다. 오늘 하루가 이렇게 가볍게 지나가도 좋은지 의아해하면서도 그녀는 슬며시 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"승부\",\"min\":7,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"승부\",\"min\":4,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"승자는 당신\",\"text\":\"정산 결과는 당신의 승리였다. 에프넬은 분하다는 듯 이를 갈면서도 약속대로 저녁값을 치르고 가장 비싼 요리를 시켜 준다. 투덜거림은 끝이 없지만 눈매는 한껏 부드럽다. 다음 승부는 반드시 이긴다며 손가락을 들이대는 그녀에게 당신은 웃으며 건배를 청한다. 그녀는 잔을 마주치며 고맙다고 아주 작게 중얼거린다. 그날 밤 에프넬은 졌다고 인정하면서도 눈에는 오기 대신 호의가 가득하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"무승부의 저녁\",\"text\":\"결과는 동점이었다. 에프넬은 이런 결말은 비겁하다고 투덜대면서도 둘이 반반 계산하자고 제안한다. 식당 불빛 아래서 서로의 활약을 과장해 떠드는 두 사람은 어느새 오래된 친구처럼 보인다. 당신은 그녀가 건네는 음료 잔을 받아 들며 이 무승부가 오히려 가장 즐거운 결과라고 생각한다. 그녀는 계산서를 반으로 가르며 오늘의 승부는 서로에게 좋은 훈련이었다고 말한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"에프넬의 승리 선언\",\"text\":\"정산 결과는 에프넬의 승리였다. 그녀는 의자 위에 올라서 승자의 포즈를 취하고 당신에게 저녁을 사라고 능글맞게 명령한다. 당신은 지갑을 열면서도 웃음을 참지 못한다. 에프넬은 투덜대는 당신의 접시에 슬쩍 고기 한 점을 덜어 주고는 못 본 척 고개를 돌린다. 승부는 졌지만 그녀의 서투른 배려는 충분히 값진 것이다. 당신이 건네는 마지막 잔을 받아 든 그녀는 다음 승부를 위해 이미 작전을 짜기 시작한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"o4_1\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n4\",\"fromPort\":\"o4_2\",\"to\":\"n6\"},{\"from\":\"n4\",\"fromPort\":\"o4_3\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"승부\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"게시판 앞의 도발\",\"text\":\"아르카디아 렐름 별숲리그 지부의 의뢰 게시판 앞. 에프넬이 현상금 전단 한 장을 손가락으로 튕기며 당신에게 내기를 건다. 오늘 하루 안에 더 큰 현상금을 챙기는 쪽이 이기고, 지는 쪽이 저녁을 사는 조건이다. 능글맞은 웃음에는 이미 이길 생각밖에 없다. 말은 가볍지만 눈빛은 사냥꾼처럼 빛난다. 당신은 협력자이면서 오늘만큼은 라이벌이 된다. 에프넬은 판돈은 안 걸어도 돈 냄새는 맡겠다며 신나서 어깨를 푼다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"각자의 사냥터\",\"text\":\"규칙은 단순하다. 정오까지 각자 다른 의뢰를 골라 해결하고, 현상금 영수증으로 승부를 가린다. 에프넬은 가장 비싼 전단인 협곡 소울정크 무리 토벌을 가져가고, 당신에게는 먼저 고르라는 듯 여유 있게 손을 내민다. 지부 직원은 혀를 내두르며 말리지만 아무도 이 승부를 말릴 수 없다. 당신은 남은 전단들을 훑어보며 전략을 짠다. 에프넬은 뒤에서 어디 한번 잘해 보라며 빈정거린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"story\",\"title\":\"전단 속의 함정\",\"text\":\"게시판 앞에서 전단을 고르던 중, 에프넬이 슬쩍 한 장을 뒤로 숨기는 것을 당신은 놓치지 않는다. 가장 비싼 전단일수록 이유가 있다는 건 용병 일을 해 온 그녀가 제일 잘 안다. 그녀는 내기를 거는 척하지만 위험한 의뢰는 자기가 먼저 가져가려는 속셈이다. 당신이 눈치채자 그녀는 어랍쇼 하고 시치미를 뗀다. 지부 직원의 한숨 소리가 길게 이어지는 가운데 두 사람은 서로의 속내를 은근히 가늠한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n4\",\"x\":1320,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o4_1\",\"text\":\"위험하지만 보수가 큰 베시 추적 의뢰를 고른다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o4_2\",\"text\":\"안전하고 빠른 소울정크 퇴치 몇 건을 모은다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o4_3\",\"text\":\"에프넬 몰래 협곡 의뢰를 가로채려 한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n5\",\"x\":1620,\"y\":60,\"type\":\"story\",\"title\":\"정면 승부수\",\"text\":\"당신이 베시 추적 전단을 뽑아 들자 에프넬의 눈이 둥그레진다. 그녀는 제법인데 하고 휘파람을 불면서도 곧 질투 섞인 표정을 짓는다. 이 의뢰는 이계 종족을 상대로 한 위험 임무라 보수도 높다. 에프넬은 쓸데없이 죽지나 말라며 어깨를 툭 치고 협곡 쪽으로 달려간다. 이미 승부는 시작되었다. 그녀는 당신의 등을 향해 손을 흔들고, 두 사람은 반대 방향으로 갈라져 각자의 사냥터로 달려간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"story\",\"title\":\"협곡의 에프넬\",\"text\":\"정오가 가까워질 무렵, 협곡에서는 에프넬이 소울정크 무리를 한꺼번에 몰아치고 있다. 체술로 걷어차고 창으로 꿰뚫는 움직임에는 군더더기가 없다. 그녀는 입으로는 연신 당신을 놀리면서 몸은 혼자 열 마리를 상대한다. 그런데 한 마리가 그녀의 사각을 파고든다. 당신이 근처를 지나던 중 그 장면을 발견했고, 승부와 도움 사이에서 짧은 선택의 순간이 온다. 에프넬은 아직 당신의 존재를 모른다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n7\",\"x\":2220,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o6_1\",\"text\":\"승부는 승부, 일단 그녀를 도와 사각의 적을 쓰러뜨린다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o6_2\",\"text\":\"모른 척 지나치며 내 의뢰를 계속한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o6_3\",\"text\":\"그녀가 위험해질 때까지 지켜본다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n8\",\"x\":2520,\"y\":60,\"type\":\"story\",\"title\":\"도움은 반칙이 아냐\",\"text\":\"당신이 던진 일격이 사각의 소울정크를 쓰러뜨리자 에프넬이 휙 돌아보고 눈을 부릅뜬다. 누가 도와 달랬냐고 소리치지만 얼굴에는 안도가 스쳤다. 이건 무효라고 주장하는 그녀에게 당신은 영수증은 서로의 몫이라고 웃는다. 에프넬은 잠시 입을 다물다가 칫 하고 혀를 차며 이번 한 번만 서비스라고 중얼거린다. 서로 말은 없었지만 마음 한쪽에서는 이 소란이 싫지만은 않다는 공감이 스며든다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"숨어 있던 우두머리\",\"text\":\"협곡 안쪽 깊은 곳에서 유난히 커다란 소울정크 우두머리가 모습을 드러낸다. 이 녀석의 현상금이 오늘 전단 중 최고액이다. 에프넬과 당신은 거의 동시에 도착해 눈이 마주친다. 서로 이 녀석은 내 거라는 눈빛으로 불꽃이 튄다. 하지만 우두머리의 덩치는 혼자서 상대하기엔 만만치 않아 보인다. 에프넬은 능청스럽게 협상을 제안한다. 당신은 승부와 협력 사이에서 선택해야 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"현상금을 반반 나누기로 하고 함께 싸운다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"먼저 일격을 내서 선공을 가져간다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"에프넬에게 선공을 양보하고 지원한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"빼앗긴 선공\",\"text\":\"당신이 선공을 날리자 우두머리가 거칠게 반응해 둘 모두를 쫓기 시작한다. 에프넬은 이 바보야 하고 외치면서도 몸을 날려 당신을 낚아채 피한다. 간발의 차로 바위 뒤에 숨은 두 사람은 숨을 헐떡이며 서로를 노려본다. 승부에 눈이 먼 대가를 톡톡히 치른 셈이지만 에프넬의 입가에는 웃음이 걸려 있다. 우두머리와의 거리가 좁혀지는 사이, 에프넬은 어느새 당신이 믿을 수 있는 등을 맡기고 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"마지막 일격\",\"text\":\"우두머리가 거대한 팔을 휘두르는 순간, 에프넬이 창을 박아 넣어 움직임을 묶는다. 당신이 그 틈을 파고들어 마무리를 지을 차례다. 둘의 호흡이 의외로 잘 맞아떨어지며 협곡 전체가 흔들릴 만큼의 충격이 터진다. 쓰러진 우두머리의 영수증은 누구의 몫일까. 에프넬은 숨을 헐떡이며 이거 누구 몫이냐고 묻고, 당신은 그 질문에 대한 답을 가지고 있다. 먼지가 가라앉고 나서야 둘은 서로의 얼굴이 온통 흙투성이라는 걸 알고 동시에 웃음을 터뜨린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"영수증은 에프넬 이름으로 올리고 대신 저녁은 얻어먹는다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_2\",\"text\":\"반반 나눠서 영수증을 둘로 쪼갠다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_3\",\"text\":\"당신 이름으로 올리고 당당히 저녁을 요구한다\",\"varOps\":[{\"var\":\"승부\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":440,\"type\":\"story\",\"title\":\"승부사의 자존심\",\"text\":\"당신의 선언에 에프넬은 아앙 하고 눈썹을 치켜세운다. 하지만 이내 큰 소리로 웃어 버린다. 이기고 싶은 마음을 숨기지 않는 사람이 마음에 든다는 듯이다. 그녀는 영수증을 접어 당신에게 던지며 다음 판은 반드시 이긴다고 선언한다. 기분 나쁜 척하지만 눈은 반짝이고 있다. 두 사람은 숨을 고르며 길고 가벼운 웃음을 나누고, 협곡의 메아리가 그 웃음을 오래 되돌려 준다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"정산소의 숫자\",\"text\":\"지부로 돌아와 정산 창구에 영수증이 올려진다. 직원이 계산기를 두드리는 동안 에프넬은 손톱을 물어뜯으며 숫자를 훔쳐본다. 결과는 박빙이다. 몇 푼 차이로 승부가 갈릴 것이다. 당신과 에프넬은 서로 곁눈질하며 긴장한다. 지부 로비의 다른 소울워커들까지 구경을 하러 모여든다. 직원이 마침내 결과를 읽기 시작하자 에프넬은 침을 꿀꺽 삼킨다. 구경꾼들의 웅성거림 속에서도 에프넬의 시선은 오직 계산기 위의 숫자에 못 박혀 있다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"저녁은 누가 쏘나\",\"text\":\"승부의 결과가 나온 뒤, 두 사람은 지부 근처 식당의 구석 자리에 앉는다. 에프넬은 메뉴판을 펼치고 가장 비싼 것부터 훑어보며 눈을 반짝인다. 누가 사든 일단 먹고 보자는 기세다. 당신은 그녀의 표정에서 승부 이상의 기쁨을 읽는다. 오늘 하루 같이 달린 시간이 서로에게 편해졌다는 사실이 은근한 온기로 남는다. 에프넬은 다음 승부는 내일이라고 선언한다. 오늘 하루가 이렇게 가볍게 지나가도 좋은지 의아해하면서도 그녀는 슬며시 웃는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"승부\",\"min\":7,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"승부\",\"min\":4,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"승자는 당신\",\"text\":\"정산 결과는 당신의 승리였다. 에프넬은 분하다는 듯 이를 갈면서도 약속대로 저녁값을 치르고 가장 비싼 요리를 시켜 준다. 투덜거림은 끝이 없지만 눈매는 한껏 부드럽다. 다음 승부는 반드시 이긴다며 손가락을 들이대는 그녀에게 당신은 웃으며 건배를 청한다. 그녀는 잔을 마주치며 고맙다고 아주 작게 중얼거린다. 그날 밤 에프넬은 졌다고 인정하면서도 눈에는 오기 대신 호의가 가득하다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"무승부의 저녁\",\"text\":\"결과는 동점이었다. 에프넬은 이런 결말은 비겁하다고 투덜대면서도 둘이 반반 계산하자고 제안한다. 식당 불빛 아래서 서로의 활약을 과장해 떠드는 두 사람은 어느새 오래된 친구처럼 보인다. 당신은 그녀가 건네는 음료 잔을 받아 들며 이 무승부가 오히려 가장 즐거운 결과라고 생각한다. 그녀는 계산서를 반으로 가르며 오늘의 승부는 서로에게 좋은 훈련이었다고 말한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"에프넬의 승리 선언\",\"text\":\"정산 결과는 에프넬의 승리였다. 그녀는 의자 위에 올라서 승자의 포즈를 취하고 당신에게 저녁을 사라고 능글맞게 명령한다. 당신은 지갑을 열면서도 웃음을 참지 못한다. 에프넬은 투덜대는 당신의 접시에 슬쩍 고기 한 점을 덜어 주고는 못 본 척 고개를 돌린다. 승부는 졌지만 그녀의 서투른 배려는 충분히 값진 것이다. 당신이 건네는 마지막 잔을 받아 든 그녀는 다음 승부를 위해 이미 작전을 짜기 시작한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"out\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"o4_1\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n4\",\"fromPort\":\"o4_2\",\"to\":\"n6\"},{\"from\":\"n4\",\"fromPort\":\"o4_3\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"out\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"o6_1\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_2\",\"to\":\"n9\"},{\"from\":\"n7\",\"fromPort\":\"o6_3\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '현상금 사냥 대결 - 지는 쪽이 저녁 쏜다'
);

-- 14. [에프넬] 에프넬이 앓아누운 날 - 츤데레 간호 역전극
INSERT INTO character_stories (character_id, title, status, is_adult, draft_json, published_json, published_at)
SELECT @efnel_id, '에프넬이 앓아누운 날 - 츤데레 간호 역전극', 'published', 0, '{\"vars\":[{\"name\":\"정성\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"열 오른 아침\",\"text\":\"아르카디아 렐름 숙소의 이른 아침. 평소라면 벌써 어딘가에서 보수 협상을 하고 있을 에프넬이 이불을 뒤집어쓴 채 나오지 않는다. 문틈으로 들려오는 목소리는 갈라졌고 콧소리가 섞여 있다. 당신이 문을 두드리자 감기 따위 없다며 단호하게 외치지만 곧 기침이 터진다. 시즌 2의 연이은 전투로 쌓인 피로가 한꺼번에 터진 모양이다. 당신은 협력자로서 그녀의 방문 앞에 서서 어떻게 들어갈지 고민한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"문 앞의 실랑이\",\"text\":\"에프넬은 방문을 빼꼼 열고 사람이 아프면 절대 안 되는 직업이라며 우긴다. 하지만 얼굴은 새빨갛고 눈은 풀려 있으며 서 있는 것조차 위태롭다. 그녀는 동정은 사양이고 영웅 취급도 사양이라며 문을 닫으려 한다. 하루는 일정 때문에 자리를 비웠고 숙소에는 당신뿐이다. 당신은 그녀가 정말 괜찮은지 판단해야 한다. 에프넬은 걱정 같은 건 하지 말라며 눈을 흘기지만 목소리는 떨린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"문틈으로 들어가 이마에 손을 얹어 열을 잰다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"약부터 사 오겠다고 말하고 일단 물러난다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"괜찮다는 말을 믿고 돌아선다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"이마의 온도\",\"text\":\"당신의 손이 이마에 닿자 에프넬은 얼어붙은 듯 굳어 버린다. 곧 놀란 고양이처럼 뒷걸음질 치지만 열 때문에 다리에 힘이 풀려 침대 모서리에 주저앉는다. 이마는 불덩이처럼 뜨겁다. 그녀는 소름 끼친다고 외치려다 기침에 걸려 말을 잇지 못한다. 당신은 조용히 이불을 끌어당겨 덮어 주고, 그녀는 시선을 피한 채 입술만 삐죽 내민다. 이마를 짚던 손을 떼자 방 안에는 어색하면서도 따뜻한 침묵이 한참 머문다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"고집불통 환자\",\"text\":\"침대에 누웠으면서도 에프넬은 누구에게도 보이고 싶지 않다는 듯 이불을 머리끝까지 끌어올린다. 약 같은 거 필요 없고 자고 일어나면 낫는다고 우기지만 기침이 그 말을 배신한다. 당신은 물수건과 따뜻한 물을 준비하며 그녀의 고집에 맞춰 줄지, 단호하게 돌봐 줄지 갈등한다. 에프넬은 이불 틈으로 눈만 내놓고 당신을 감시하듯 쳐다본다. 어쩐지 어린 시절의 어떤 기억이 그녀 눈에 스쳐 간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"따뜻한 죽을 직접 끓여 가져다준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"약을 건네고 쉬게 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"놀리듯이 빈정거리며 상태를 살핀다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":60,\"type\":\"story\",\"title\":\"서비스 요금 없음\",\"text\":\"죽 냄새가 방 안에 퍼지자 이불 속에서 꼬르륵 소리가 난다. 에프넬은 이건 서비스인지 유료인지 따지려다 수저를 든 채 멈춘다. 한 숟가락 입에 넣은 순간 얼굴이 풀리며 의외로 괜찮다고 인정한다. 이런 따뜻한 걸 먹어 본 게 오랜만이라는 말은 끝내 입 밖에 내지 않지만 수저를 놓지 않는다. 당신은 모르는 척 물을 따라 준다. 에프넬은 식은 죽 한 숟가락마저 남기지 않고, 빈 그릇을 슬쩍 이불 아래로 숨기려 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"열에 뜬 헛소리\",\"text\":\"오후가 되자 열이 더 오른 에프넬은 반쯤 잠들어 중얼거린다. 평소엔 결코 입 밖에 내지 않는 말들이 흘러나온다. 부모가 팔아넘긴 날의 이야기, 아무도 찾아오지 않던 실험실의 밤, 그리고 포이즌의 이름까지. 당신은 그 곁에 앉아 땀에 젖은 이마의 수건을 갈아 준다. 그녀는 눈을 감은 채 가지 말라고 아주 작게 중얼거린다. 깨어 있었다면 절대 하지 않았을 말이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"식은땀과 새벽의 수건\",\"text\":\"열이 정점을 지나는 새벽, 에프넬의 숨소리가 조금씩 고르게 가라앉는다. 당신은 몇 번째인지 모를 찬 수건을 짜서 이마에 올려 준다. 그녀는 눈을 감은 채 이마 위의 시원함에 안도하듯 작은 숨을 내쉰다. 창밖으로는 동이 트기 전의 푸른 어둠이 드리워 있고, 방 안에는 시계 소리만 낮게 울린다. 당신은 이 조용한 시간이 그녀에게 얼마나 드문 휴식일지 헤아리며 가만히 지켜본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"조용히 곁에 앉아 손을 잡아 준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"못 들은 척하고 방 안을 정리한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"하루에게 연락해 도움을 요청한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"모른 척하는 배려\",\"text\":\"당신은 일부러 컵 부딪히는 소리를 내며 방 안을 정리한다. 잠결의 말은 흘려보내는 것이 그녀를 위한 일이라 생각했기 때문이다. 잠시 후 에프넬이 실눈을 뜨고 당신의 등을 한참 쳐다본다. 들었냐고 묻지 않고 그저 다행이라는 듯 다시 눈을 감는다. 말하지 않아도 오가는 신뢰가 방 안의 공기를 부드럽게 바꾼다. 그녀는 아무 일도 없었던 것처럼 조용히 숨을 고르고, 방 안의 공기는 한결 편안하게 가라앉는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"깨어난 에프넬\",\"text\":\"저녁 무렵 눈을 뜬 에프넬은 머리맡의 수건과 약, 그리고 졸고 있는 당신을 발견한다. 순간 얼굴이 새빨개지며 이불을 끌어당긴다. 내가 뭐라고 한 건 아니겠지 하고 위협적으로 묻는다. 목소리는 여전히 갈라져 있지만 열은 한결 내려간 상태다. 당신은 그녀의 질문에 어떻게 대답할지 생각한다. 에프넬은 빚지는 건 질색이라며 이 간호 비용을 청구하라고 으르렁거린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"청구서 대신 다 나으면 같이 밥 먹자고 말한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"아무 말도 못 들었다고 시치미를 뗀다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"간호비 대신 한 번 빚졌다고 놀린다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":440,\"type\":\"story\",\"title\":\"빚쟁이 선언\",\"text\":\"당신의 말에 에프넬은 기가 막혀 입을 벌렸다가 베개를 던진다. 하지만 힘이 없어 베개는 당신 무릎 앞에서 떨어진다. 그녀는 이 은혜는 기억하겠지만 갚는 건 내 방식대로라고 선언한다. 빚 이야기를 하는 그녀의 입꼬리가 은근히 올라가 있는 것을 당신은 놓치지 않는다. 오랜만에 방 안에 웃음이 퍼진다. 오랜만에 방 안에 퍼진 웃음소리가 열기를 식히듯 부드럽게 두 사람 사이를 감싼다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"역전된 밤\",\"text\":\"밤이 깊어지자 에프넬은 몸을 일으켜 앉는다. 이번에는 거꾸로 당신이 졸음에 겨워 꾸벅거리고 있다. 그녀는 투덜거리면서도 담요를 당신 어깨에 걸쳐 준다. 공짜로 부려먹을 노예가 쓰러지면 곤란하다는 변명을 중얼거리지만 손길은 꽤 조심스럽다. 당신은 반쯤 깬 상태로 그 광경을 알아챈다. 창밖으로 아르카디아 렐름의 야경이 펼쳐지는 조용한 밤이 천천히 흘러간다. 평소의 독설은 간 곳 없이, 대신 조용히 서툰 손짓들이 그녀의 진심을 대신 이야기한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"다음 날 아침\",\"text\":\"아침 햇살이 방 안으로 들어올 때 에프넬은 이미 평소 모습으로 돌아와 있다. 목소리는 여전히 갈라졌지만 빈정거림은 완전히 회복되었다. 그녀는 어제 일은 전부 열 때문에 생긴 환각이라고 선언하며 눈을 흘긴다. 하지만 식탁 위에는 그녀가 서투르게 차린 아침 한 상이 놓여 있다. 당신은 말없이 자리에 앉아 수저를 든다. 에프넬은 맛에 대한 평가는 사양이라고 못 박는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":8,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":5,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"서툴게 차린 아침 한 상\",\"text\":\"그녀가 차린 아침은 간이 안 맞고 모양도 엉망이지만 당신은 끝까지 맛있게 먹는다. 에프넬은 과장하지 말라며 투덜거리면서도 두 번째 그릇을 채워 준다. 나아진 목소리로 이번 일은 서비스라고 말하며 당신 눈을 피한다. 하지만 그녀의 귀끝은 이미 붉게 물들어 있고, 앞으로 아플 때는 당신이 곁에 있어도 좋다는 무언의 허락이 식탁 위에 놓여 있다. 이 아침의 소소한 풍경이 당신에게는 어떤 전투의 승리보다도 값진 보수로 남는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"다 나으면 갚을게\",\"text\":\"에프넬은 아침을 먹고 약을 삼킨 뒤 소파에 앉아 중얼거린다. 이번 일은 언젠가 반드시 갚는다고. 말투는 퉁명스럽지만 눈빛은 한결 부드럽다. 당신은 대답 대신 웃으며 컵에 따뜻한 차를 채운다. 아직 완전히 열린 마음은 아니지만 문틈이 조금 넓어진 아침이다. 찻잔에서 오르는 김 너머로 두 사람은 말없이 평범한 아침의 평화를 나눈다. 그 평범함이 이 두 사람에게는 가장 귀한 보상이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"혼자 앓은 하루\",\"text\":\"에프넬은 끝내 당신의 손길을 완전히 받아들이지 않았고 대부분의 시간을 이불 속에서 혼자 버텼다. 다음 날 아침 그녀는 아무 일도 없었다는 듯 장난스럽게 인사하지만 눈 밑에는 피로가 남아 있다. 당신은 조금 아쉬운 마음으로 차를 건넨다. 그녀는 말없이 받아 마시며 다음엔 조금 더 곁에 있어 줘도 된다고 말하는 듯한 눈빛을 보낸다. 그래도 창가의 햇살 속에서 두 사람은 자연스럽게 하루를 시작한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', '{\"vars\":[{\"name\":\"정성\",\"initial\":0}],\"nodes\":[{\"id\":\"start\",\"x\":120,\"y\":320,\"type\":\"start\"},{\"id\":\"n1\",\"x\":420,\"y\":320,\"type\":\"story\",\"title\":\"열 오른 아침\",\"text\":\"아르카디아 렐름 숙소의 이른 아침. 평소라면 벌써 어딘가에서 보수 협상을 하고 있을 에프넬이 이불을 뒤집어쓴 채 나오지 않는다. 문틈으로 들려오는 목소리는 갈라졌고 콧소리가 섞여 있다. 당신이 문을 두드리자 감기 따위 없다며 단호하게 외치지만 곧 기침이 터진다. 시즌 2의 연이은 전투로 쌓인 피로가 한꺼번에 터진 모양이다. 당신은 협력자로서 그녀의 방문 앞에 서서 어떻게 들어갈지 고민한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n2\",\"x\":720,\"y\":320,\"type\":\"story\",\"title\":\"문 앞의 실랑이\",\"text\":\"에프넬은 방문을 빼꼼 열고 사람이 아프면 절대 안 되는 직업이라며 우긴다. 하지만 얼굴은 새빨갛고 눈은 풀려 있으며 서 있는 것조차 위태롭다. 그녀는 동정은 사양이고 영웅 취급도 사양이라며 문을 닫으려 한다. 하루는 일정 때문에 자리를 비웠고 숙소에는 당신뿐이다. 당신은 그녀가 정말 괜찮은지 판단해야 한다. 에프넬은 걱정 같은 건 하지 말라며 눈을 흘기지만 목소리는 떨린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n3\",\"x\":1020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o3_1\",\"text\":\"문틈으로 들어가 이마에 손을 얹어 열을 잰다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o3_2\",\"text\":\"약부터 사 오겠다고 말하고 일단 물러난다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o3_3\",\"text\":\"괜찮다는 말을 믿고 돌아선다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n4\",\"x\":1320,\"y\":60,\"type\":\"story\",\"title\":\"이마의 온도\",\"text\":\"당신의 손이 이마에 닿자 에프넬은 얼어붙은 듯 굳어 버린다. 곧 놀란 고양이처럼 뒷걸음질 치지만 열 때문에 다리에 힘이 풀려 침대 모서리에 주저앉는다. 이마는 불덩이처럼 뜨겁다. 그녀는 소름 끼친다고 외치려다 기침에 걸려 말을 잇지 못한다. 당신은 조용히 이불을 끌어당겨 덮어 주고, 그녀는 시선을 피한 채 입술만 삐죽 내민다. 이마를 짚던 손을 떼자 방 안에는 어색하면서도 따뜻한 침묵이 한참 머문다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n5\",\"x\":1620,\"y\":320,\"type\":\"story\",\"title\":\"고집불통 환자\",\"text\":\"침대에 누웠으면서도 에프넬은 누구에게도 보이고 싶지 않다는 듯 이불을 머리끝까지 끌어올린다. 약 같은 거 필요 없고 자고 일어나면 낫는다고 우기지만 기침이 그 말을 배신한다. 당신은 물수건과 따뜻한 물을 준비하며 그녀의 고집에 맞춰 줄지, 단호하게 돌봐 줄지 갈등한다. 에프넬은 이불 틈으로 눈만 내놓고 당신을 감시하듯 쳐다본다. 어쩐지 어린 시절의 어떤 기억이 그녀 눈에 스쳐 간다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n6\",\"x\":1920,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o5_1\",\"text\":\"따뜻한 죽을 직접 끓여 가져다준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o5_2\",\"text\":\"약을 건네고 쉬게 한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o5_3\",\"text\":\"놀리듯이 빈정거리며 상태를 살핀다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":0}]}]},{\"id\":\"n7\",\"x\":2220,\"y\":60,\"type\":\"story\",\"title\":\"서비스 요금 없음\",\"text\":\"죽 냄새가 방 안에 퍼지자 이불 속에서 꼬르륵 소리가 난다. 에프넬은 이건 서비스인지 유료인지 따지려다 수저를 든 채 멈춘다. 한 숟가락 입에 넣은 순간 얼굴이 풀리며 의외로 괜찮다고 인정한다. 이런 따뜻한 걸 먹어 본 게 오랜만이라는 말은 끝내 입 밖에 내지 않지만 수저를 놓지 않는다. 당신은 모르는 척 물을 따라 준다. 에프넬은 식은 죽 한 숟가락마저 남기지 않고, 빈 그릇을 슬쩍 이불 아래로 숨기려 한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n8\",\"x\":2520,\"y\":320,\"type\":\"story\",\"title\":\"열에 뜬 헛소리\",\"text\":\"오후가 되자 열이 더 오른 에프넬은 반쯤 잠들어 중얼거린다. 평소엔 결코 입 밖에 내지 않는 말들이 흘러나온다. 부모가 팔아넘긴 날의 이야기, 아무도 찾아오지 않던 실험실의 밤, 그리고 포이즌의 이름까지. 당신은 그 곁에 앉아 땀에 젖은 이마의 수건을 갈아 준다. 그녀는 눈을 감은 채 가지 말라고 아주 작게 중얼거린다. 깨어 있었다면 절대 하지 않았을 말이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n9\",\"x\":2820,\"y\":320,\"type\":\"story\",\"title\":\"식은땀과 새벽의 수건\",\"text\":\"열이 정점을 지나는 새벽, 에프넬의 숨소리가 조금씩 고르게 가라앉는다. 당신은 몇 번째인지 모를 찬 수건을 짜서 이마에 올려 준다. 그녀는 눈을 감은 채 이마 위의 시원함에 안도하듯 작은 숨을 내쉰다. 창밖으로는 동이 트기 전의 푸른 어둠이 드리워 있고, 방 안에는 시계 소리만 낮게 울린다. 당신은 이 조용한 시간이 그녀에게 얼마나 드문 휴식일지 헤아리며 가만히 지켜본다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n10\",\"x\":3120,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o8_1\",\"text\":\"조용히 곁에 앉아 손을 잡아 준다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o8_2\",\"text\":\"못 들은 척하고 방 안을 정리한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o8_3\",\"text\":\"하루에게 연락해 도움을 요청한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n11\",\"x\":3420,\"y\":250,\"type\":\"story\",\"title\":\"모른 척하는 배려\",\"text\":\"당신은 일부러 컵 부딪히는 소리를 내며 방 안을 정리한다. 잠결의 말은 흘려보내는 것이 그녀를 위한 일이라 생각했기 때문이다. 잠시 후 에프넬이 실눈을 뜨고 당신의 등을 한참 쳐다본다. 들었냐고 묻지 않고 그저 다행이라는 듯 다시 눈을 감는다. 말하지 않아도 오가는 신뢰가 방 안의 공기를 부드럽게 바꾼다. 그녀는 아무 일도 없었던 것처럼 조용히 숨을 고르고, 방 안의 공기는 한결 편안하게 가라앉는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n12\",\"x\":3720,\"y\":320,\"type\":\"story\",\"title\":\"깨어난 에프넬\",\"text\":\"저녁 무렵 눈을 뜬 에프넬은 머리맡의 수건과 약, 그리고 졸고 있는 당신을 발견한다. 순간 얼굴이 새빨개지며 이불을 끌어당긴다. 내가 뭐라고 한 건 아니겠지 하고 위협적으로 묻는다. 목소리는 여전히 갈라져 있지만 열은 한결 내려간 상태다. 당신은 그녀의 질문에 어떻게 대답할지 생각한다. 에프넬은 빚지는 건 질색이라며 이 간호 비용을 청구하라고 으르렁거린다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n13\",\"x\":4020,\"y\":320,\"type\":\"choice\",\"options\":[{\"id\":\"o10_1\",\"text\":\"청구서 대신 다 나으면 같이 밥 먹자고 말한다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":2}]},{\"id\":\"o10_2\",\"text\":\"아무 말도 못 들었다고 시치미를 뗀다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]},{\"id\":\"o10_3\",\"text\":\"간호비 대신 한 번 빚졌다고 놀린다\",\"varOps\":[{\"var\":\"정성\",\"op\":\"add\",\"value\":1}]}]},{\"id\":\"n14\",\"x\":4320,\"y\":440,\"type\":\"story\",\"title\":\"빚쟁이 선언\",\"text\":\"당신의 말에 에프넬은 기가 막혀 입을 벌렸다가 베개를 던진다. 하지만 힘이 없어 베개는 당신 무릎 앞에서 떨어진다. 그녀는 이 은혜는 기억하겠지만 갚는 건 내 방식대로라고 선언한다. 빚 이야기를 하는 그녀의 입꼬리가 은근히 올라가 있는 것을 당신은 놓치지 않는다. 오랜만에 방 안에 웃음이 퍼진다. 오랜만에 방 안에 퍼진 웃음소리가 열기를 식히듯 부드럽게 두 사람 사이를 감싼다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n15\",\"x\":4620,\"y\":320,\"type\":\"story\",\"title\":\"역전된 밤\",\"text\":\"밤이 깊어지자 에프넬은 몸을 일으켜 앉는다. 이번에는 거꾸로 당신이 졸음에 겨워 꾸벅거리고 있다. 그녀는 투덜거리면서도 담요를 당신 어깨에 걸쳐 준다. 공짜로 부려먹을 노예가 쓰러지면 곤란하다는 변명을 중얼거리지만 손길은 꽤 조심스럽다. 당신은 반쯤 깬 상태로 그 광경을 알아챈다. 창밖으로 아르카디아 렐름의 야경이 펼쳐지는 조용한 밤이 천천히 흘러간다. 평소의 독설은 간 곳 없이, 대신 조용히 서툰 손짓들이 그녀의 진심을 대신 이야기한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n16\",\"x\":4920,\"y\":320,\"type\":\"story\",\"title\":\"다음 날 아침\",\"text\":\"아침 햇살이 방 안으로 들어올 때 에프넬은 이미 평소 모습으로 돌아와 있다. 목소리는 여전히 갈라졌지만 빈정거림은 완전히 회복되었다. 그녀는 어제 일은 전부 열 때문에 생긴 환각이라고 선언하며 눈을 흘긴다. 하지만 식탁 위에는 그녀가 서투르게 차린 아침 한 상이 놓여 있다. 당신은 말없이 자리에 앉아 수저를 든다. 에프넬은 맛에 대한 평가는 사양이라고 못 박는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n17\",\"x\":5220,\"y\":320,\"type\":\"branch\",\"rules\":[{\"id\":\"r1\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":8,\"max\":null}]},{\"id\":\"r2\",\"logic\":\"and\",\"terms\":[{\"var\":\"정성\",\"min\":5,\"max\":null}]}]},{\"id\":\"n18\",\"x\":5520,\"y\":60,\"type\":\"story\",\"title\":\"서툴게 차린 아침 한 상\",\"text\":\"그녀가 차린 아침은 간이 안 맞고 모양도 엉망이지만 당신은 끝까지 맛있게 먹는다. 에프넬은 과장하지 말라며 투덜거리면서도 두 번째 그릇을 채워 준다. 나아진 목소리로 이번 일은 서비스라고 말하며 당신 눈을 피한다. 하지만 그녀의 귀끝은 이미 붉게 물들어 있고, 앞으로 아플 때는 당신이 곁에 있어도 좋다는 무언의 허락이 식탁 위에 놓여 있다. 이 아침의 소소한 풍경이 당신에게는 어떤 전투의 승리보다도 값진 보수로 남는다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n19\",\"x\":5520,\"y\":250,\"type\":\"story\",\"title\":\"다 나으면 갚을게\",\"text\":\"에프넬은 아침을 먹고 약을 삼킨 뒤 소파에 앉아 중얼거린다. 이번 일은 언젠가 반드시 갚는다고. 말투는 퉁명스럽지만 눈빛은 한결 부드럽다. 당신은 대답 대신 웃으며 컵에 따뜻한 차를 채운다. 아직 완전히 열린 마음은 아니지만 문틈이 조금 넓어진 아침이다. 찻잔에서 오르는 김 너머로 두 사람은 말없이 평범한 아침의 평화를 나눈다. 그 평범함이 이 두 사람에게는 가장 귀한 보상이다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"n20\",\"x\":5520,\"y\":440,\"type\":\"story\",\"title\":\"혼자 앓은 하루\",\"text\":\"에프넬은 끝내 당신의 손길을 완전히 받아들이지 않았고 대부분의 시간을 이불 속에서 혼자 버텼다. 다음 날 아침 그녀는 아무 일도 없었다는 듯 장난스럽게 인사하지만 눈 밑에는 피로가 남아 있다. 당신은 조금 아쉬운 마음으로 차를 건넨다. 그녀는 말없이 받아 마시며 다음엔 조금 더 곁에 있어 줘도 된다고 말하는 듯한 눈빛을 보낸다. 그래도 창가의 햇살 속에서 두 사람은 자연스럽게 하루를 시작한다.\",\"imageUrl\":null,\"varOps\":[]},{\"id\":\"end\",\"x\":5820,\"y\":320,\"type\":\"end\"}],\"edges\":[{\"from\":\"start\",\"fromPort\":\"out\",\"to\":\"n1\"},{\"from\":\"n1\",\"fromPort\":\"out\",\"to\":\"n2\"},{\"from\":\"n2\",\"fromPort\":\"out\",\"to\":\"n3\"},{\"from\":\"n3\",\"fromPort\":\"o3_1\",\"to\":\"n4\"},{\"from\":\"n4\",\"fromPort\":\"out\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_2\",\"to\":\"n5\"},{\"from\":\"n3\",\"fromPort\":\"o3_3\",\"to\":\"n5\"},{\"from\":\"n5\",\"fromPort\":\"out\",\"to\":\"n6\"},{\"from\":\"n6\",\"fromPort\":\"o5_1\",\"to\":\"n7\"},{\"from\":\"n7\",\"fromPort\":\"out\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_2\",\"to\":\"n8\"},{\"from\":\"n6\",\"fromPort\":\"o5_3\",\"to\":\"n8\"},{\"from\":\"n8\",\"fromPort\":\"out\",\"to\":\"n9\"},{\"from\":\"n9\",\"fromPort\":\"out\",\"to\":\"n10\"},{\"from\":\"n10\",\"fromPort\":\"o8_2\",\"to\":\"n11\"},{\"from\":\"n10\",\"fromPort\":\"o8_1\",\"to\":\"n12\"},{\"from\":\"n11\",\"fromPort\":\"out\",\"to\":\"n12\"},{\"from\":\"n10\",\"fromPort\":\"o8_3\",\"to\":\"n12\"},{\"from\":\"n12\",\"fromPort\":\"out\",\"to\":\"n13\"},{\"from\":\"n13\",\"fromPort\":\"o10_3\",\"to\":\"n14\"},{\"from\":\"n13\",\"fromPort\":\"o10_1\",\"to\":\"n15\"},{\"from\":\"n13\",\"fromPort\":\"o10_2\",\"to\":\"n15\"},{\"from\":\"n14\",\"fromPort\":\"out\",\"to\":\"n15\"},{\"from\":\"n15\",\"fromPort\":\"out\",\"to\":\"n16\"},{\"from\":\"n16\",\"fromPort\":\"out\",\"to\":\"n17\"},{\"from\":\"n17\",\"fromPort\":\"r1\",\"to\":\"n18\"},{\"from\":\"n18\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"r2\",\"to\":\"n19\"},{\"from\":\"n19\",\"fromPort\":\"out\",\"to\":\"end\"},{\"from\":\"n17\",\"fromPort\":\"else\",\"to\":\"n20\"},{\"from\":\"n20\",\"fromPort\":\"out\",\"to\":\"end\"}]}', NOW()
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM character_stories WHERE character_id = @efnel_id AND title = '에프넬이 앓아누운 날 - 츤데레 간호 역전극'
);
